  ('cpiuris2025::a6559b0e1ad0eea80b39a78185edc2a4', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Restrições ao acesso a informações sobre medidas socioeducativas', '## Restrições ao acesso a informações sobre medidas socioeducativas

O adolescente tem direito a restrição do acesso a informações sobre suas medidas socioeducativas, exceto em caso de autorização judicial.

### Conceitos
- **Acesso restrito**: Restrição ao acesso a informações sobre medidas socioeducativas
- **Autorização judicial**: Necessidade de autorização judicial para acessar informações sobre medidas socioeducativas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre acesso restrito e autorização judicial
- Importância do consentimento informado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.188 (2)", "page_number": 188, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T00:47:34.754660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=188", "doc_key": "a6559b0e1ad0eea80b39a78185edc2a4"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'f5153ff4e477452b43e1d83637d775579d56fff8dab8ba1b163a5b7b55e05848'),
  ('cpiuris2025::013c3d851f01afe2556fe53ef9484404', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Plano Individual de Acompanhamento (PIA) para adolescentes em programas de atendimento socioeducativo', '## Plano Individual de Acompanhamento (PIA) para adolescentes em programas de atendimento socioeducativo

O PIA é um documento que define os objetivos, atividades e medidas para o desenvolvimento do adolescente em programas de atendimento socioeducativo.

### Conceitos
- **Plano Individual de Acompanhamento (PIA)**: Um documento que define os objetivos, atividades e medidas para o desenvolvimento do adolescente em programas de atendimento socioeducativo.
- **Programa de Atendimento Socioeducativo**: Um programa que oferece apoio e orientação ao adolescente para ajudá-lo a se reintegrar à sociedade.
- **Medidas de Semiliberdade ou Internação**: Medidas que limitam a liberdade do adolescente, como internação em um programa de atendimento socioeducativo.
- **Prestação de Serviços à Comunidade**: Uma medida que obriga o adolescente a realizar atividades benefícias para a comunidade.
- **Liberdade Assistida**: Uma medida que permite ao adolescente realizar suas atividades pessoais e sociais, com supervisão do programa de atendimento socioeducativo.

### Referências legais
- Art. 54 da Lei do Sinase

### Dicas de prova
- Entenda a importância do PIA e como ele é utilizado em programas de atendimento socioeducativo.
- Conheça as diferentes medidas que podem ser aplicadas ao adolescente, como semiliberdade, internação, prestação de serviços à comunidade e liberdade assistida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.188 (1)", "page_number": 188, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 54 da Lei do Sinase"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T00:48:53.325812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=188", "doc_key": "013c3d851f01afe2556fe53ef9484404"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '705d5d83b7b9026558270679500a9a899123468433316da1662c4d1f14fc990d'),
  ('cpiuris2025::269906e4fcac042a7f54c58109e0bdb6', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Reavaliaó de medidas socioeducativas', '## Reavaliaó de medidas socioeducativas

A Lei do Sinase estabelece a periodicidade para reavaliaÊssas das medidas socioeducativas, que devem ser realizadas a cada 6 meses. O pedido de reavaliaÊssao pode ser feito por diversas partes, incluindo o Ministério Público e o defensor.

### Conceitos
- **ReavaliaÊssao**: Processo de avaliaÊssão da efic¬cia das medidas socioeducativas
- **Medidas socioeducativas**: Mensuras impostas ao adolescente para reabilitaÊssó e reintegraÜl na sociedade
- **Plano individual**: Documento que estabelece as atividades e objetivos para o cumprimento da medida socioeducativa

### Referências legais
- Art. 42 da Lei do Sinase

### Dicas de prova
- Entenda a periodicidade de reavaliaÊssao e os motivos que justificam o pedido
- Conheça as partes que podem solicitar a reavaliaÊssao', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.189", "page_number": 189, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 42 da Lei do Sinase"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T00:49:17.559422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=189", "doc_key": "269906e4fcac042a7f54c58109e0bdb6"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', '64729e4b5fb5b4f3c9390f7a2f7b8539198b42f1e0f7e163c1230cbea0f48387'),
  ('cpiuris2025::1197683a56b66f614293fa65a2c9ff9d', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Medidas Socioeducativas e Direitos dos Adolescentes', '## Medidas Socioeducativas e Direitos dos Adolescentes

A unificação das medidas socioeducativas não pode ocorrer entre as estipuladas em remissão ministerial e em sentença, devido à natureza distinta e consequências diversas. A autoridade judiciária não pode determinar reinício de cumprimento de medida socioeducativa ou deixar de considerar prazos máximos previstos no ECA.

### Conceitos
- **Medidas Socioeducativas**: Ações tomadas pelo Estado para disciplinar menores de idade
- **Remissão Ministerial**: Decisão do juiz que permite a liberação do menor de medida socioeducativa, sem necessidade de cumprimento de pena
- **Sentença**: Decisão final do juiz em um processo
- **ECA**: Código de Menores, que estabelece regras para a internação e o tratamento de menores de idade
- **Internação**: Ação socioeducativa que envolve a colocação do menor em um estabelecimento especializado
- **Visita**: Direito do adolescente à visita de familiares, amigos e outros entes queridos

### Referências legais
- Art. 45, § 2º da Lei do Sinase

### Jurisprudência
- STJ. 6ª Turma. AgRg no HC 848.765/SC
- RE 123456

### Dicas de prova
- Entenda a diferença entre medidas socioeducativas estipuladas em remissão ministerial e sentença
- Conheça os direitos dos adolescentes em relação à visita de familiares e amigos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.190 (1)", "page_number": 190, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 45, § 2º da Lei do Sinase"], "jurisprudence": ["STJ. 6ª Turma. AgRg no HC 848.765/SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T00:50:34.048258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=190", "doc_key": "1197683a56b66f614293fa65a2c9ff9d"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '89031925ba0aa6fd1c6359b50d87ac8a078491b892e17184b90e5548d6d7fa23'),
  ('cpiuris2025::fee91c19c57c1614eeab3459d3de079d', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Extinção de medida socioeducativa', '## Extinção de medida socioeducativa

A medida socioeducativa é extinta nos casos previstos no art. 46 da Lei do Sinase, incluindo a morte do adolescente, realização de sua finalidade, aplicação de pena privativa de liberdade, condição de doença grave e demais hipóteses previstas em lei.

### Conceitos
- **Extinção de medida socioeducativa**: Fim da aplicação da medida socioeducativa
- **Lei do Sinase**: Legislação que regula a medidas socioeducativas

### Referências legais
- Art. 46 da Lei do Sinase

### Dicas de prova
- Entenda o conceito de extinção de medida socioeducativa e as hipóteses previstas no art. 46 da Lei do Sinase.
- Pergunte sobre a relação entre a aplicação de pena privativa de liberdade e a extinção da medida socioeducativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.190 (2)", "page_number": 190, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 46 da Lei do Sinase"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T00:50:44.634278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=190", "doc_key": "fee91c19c57c1614eeab3459d3de079d"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '4da1e1a70281c5bf83a50a60b4bc67ade189b38cceb4ddc22e3f5f34f83ca58d'),
  ('cpiuris2025::95b9c93240c8e5035862c4ecf6d1e808', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Revisão Judicial e Regimes Disciplinares', '## Revisão Judicial e Regimes Disciplinares

Resumo sobre a revisão judicial e os regimes disciplinares para socioeducandos.

### Conceitos
- **Revisão Judicial**: Processo autônomo para postular revisão de sanção disciplinar
- **Regimes Disciplinares**: Princípios a seguir nas entidades de atendimento socioeducativo
- **Sanção de Duração Determinada**: Sanção com duração fixa
- **Audiência do Socioeducando**: Oportunidade para o socioeducando ser ouvido em casos de processo disciplinar
- **Garantias de Defesa**: Requisitos para garantir ampla defesa ao socioeducando
- **Extinção da Sanção**: Causas que eximem, atenuam ou agravam a sanção disciplinar
- **Proibição de Isolamento**: Sanção proibida, salvo em casos de segurança

### Referências legais
- Art. 46, § 1º da Lei do Sinase

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza jurídica da revisão judicial
- Conheça os princípios dos regimes disciplinares
- Identifique as garantias de defesa para o socioeducando', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.191 (1)", "page_number": 191, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 46, § 1º da Lei do Sinase"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T00:51:59.076732+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=191", "doc_key": "95b9c93240c8e5035862c4ecf6d1e808"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '1ff0550f1e4c11a0f5f8f201efbf44dd816d1f86145af929b21c25202324d34c'),
  ('cpiuris2025::73efd2fb31b16f8b301cdce99b1d4071', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Garantia de solicitação e rito de apreciação dos recursos cabíveis', '## Garantia de solicitação e rito de apreciação dos recursos cabíveis

O texto destaca a garantia de solicitação e o rito de apreciação dos recursos cabíveis, independentemente da responsabilidade civil ou penal. Além disso, salienta que o regime disciplinar é independente e não pode ser confundido com a responsabilidade infracional.

### Conceitos
- **Responsabilidade Infracional**: Conduzida ao uso do termo para descrever a responsabilidade de um socioeducando por um ato infracional
- **Falta Disciplinar**: Ocorre quando o socioeducando comete um ato que não é considerado infração penal, mas que pode ser punido pela disciplina da instituição

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre responsabilidade civil e penal
- Conheça o conceito de falta disciplinar e sua relação com a responsabilidade infracional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.191 (2)", "page_number": 191, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T00:52:38.380228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=191", "doc_key": "73efd2fb31b16f8b301cdce99b1d4071"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'b40409ace79f27dc71213ad87aa32cc9db338a4cfd73843cb3e22edf34ab6651'),
  ('cpiuris2025::98b18d14e67b0ccdeb2598e496fb3147', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Prisão Cautelar e Atos Infracionais', '## Prisão Cautelar e Atos Infracionais

A prisão cautelar pode ser fundada em atos infracionais durante a adolescência, desde que observados critérios específicos, como gravidade concreta do ato, distância temporal entre o ato e o crime e comprovação do ato infracional.

### Conceitos
- **Prisão Cautelar**: Medida provvisória de prisão para garantir a ordem pública e segurança
- **Atos Infracionais**: Ações ou omissões que violam a lei, cometidas por menores de idade
- **Critérios Orientadores**: Gravidade concreta do ato, distância temporal entre o ato e o crime e comprovação do ato infracional

### Referências legais
- Art. 28 da Lei de drogas

### Jurisprudência
- HC 119160/SP
- RHC 63.855-MG

### Dicas de prova
- Distinção entre prisão cautelar e prisão preventiva
- Importância dos critérios orientadores na decretação de prisão cautelar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.192 (2)", "page_number": 192, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 28 da Lei de drogas"], "jurisprudence": ["HC 119160/SP", "RHC 63.855-MG"], "confidence": 0.8, "extracted_at": "2026-05-30T00:54:13.077272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=192", "doc_key": "98b18d14e67b0ccdeb2598e496fb3147"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'fdc9b9890ba8c09cc616bf97b09001e82591c5414901811bd4959b201895a884'),
  ('cpiuris2025::5fcd90ce71f1163f5f8733c1348eb455', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Excepcionalidade na aplicação de medida socioeducativa', '## Excepcionalidade na aplicação de medida socioeducativa

A Lei do Sistema Nacional de Atendimento Socioeducativo (SINASE) estabelece que os adolescentes submetidos a medida socioeducativa têm direito a ser incluídos em programa de meio aberto, exceto em casos de ato infracional cometido mediante grave ameaça ou violência à pessoa. No entanto, a aplicação dessa regra deve ser relativizada caso a caso e verificada a imprescindibilidade da medida de internação.

### Conceitos
- **Medida socioeducativa**: Mensagem que define as medidas a serem adotadas em relação ao adolescente infrator
- **Programa de meio aberto**: O programa oferece alternativas para o adolescente, como educação e reabilitação, em vez de internação
- **Ato infracional**: Ação cometida pelo adolescente que viola a lei
- **Medida de privação da liberdade**: Mensagem que impõe restrições à liberdade do adolescente

### Referências legais
- Art. 49, II, da Lei n. 12.594/2012

### Jurisprudência
- HC 316.435-MG (DJe 11/9/2015)

### Dicas de prova
- Entenda a excepcionalidade na aplicação de medida socioeducativa
- Verifique se a regra do art. 49, II, do SINASE pode ser aplicada indistintamente ou sem critério', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.193 (1)", "page_number": 193, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 49, II, da Lei n. 12.594/2012"], "jurisprudence": ["HC 316.435-MG (DJe 11/9/2015)"], "confidence": 0.8, "extracted_at": "2026-05-30T00:55:30.214276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=193", "doc_key": "5fcd90ce71f1163f5f8733c1348eb455"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '719e1f55a210651df86fe308be056809aea09e6bc228495dee538df6cc2b5c8a'),
  ('cpiuris2025::c337201eb1a52f72c14b6bf9c3598c12', 'doutrina', 'cp_iuris', 'Direito da Criancça e do Adolescente — Medida socioeducativa em casos de atos infracionais equiparados ao crime de roubo qualificado', '## Medida socioeducativa em casos de atos infracionais equiparados ao crime de roubo qualificado

A Medida Socioeducativa de Internação pode ser imposta a adolescentes que cometeram atos infracionais equiparados ao crime de roubo qualificado, mas não é aplicável em casos de uso de drogas. A decisão deve estar fundamentada em princípios da brevidade, excepcionalidade e respeito à condição peculiar de pessoa em desenvolvimento.

### Conceitos
- **Medida Socioeducativa**: Misure de internação ou reclusão para adolescentes que cometeram atos infracionais
- **Habeas Corpus**: Recurso para anular decisões do juiz
- **Súmula 691/STF**: Proíbe a aplicação de medida socioeducativa de semiliberdade em casos de uso de drogas

### Referências legais
- Art. 157, § 2º, II, do CP
- Súmula 691/STF

### Jurisprudência
- RE 122125
- RHC 122125
- Habeas Corpus em casos de uso de drogas

### Dicas de prova
- Distinção entre atos infracionais equiparados ao crime de roubo qualificado e uso de drogas
- Avaliação da medida socioeducativa mais adequada a ser aplicada
- Fundamentação idônea para decisões do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.192 (1)", "page_number": 192, "discipline": "Direito da Criancça e do Adolescente", "legal_refs": ["Art. 157, § 2º, II, do CP", "Súmula 691/STF"], "jurisprudence": ["RE 122125", "RHC 122125", "Habeas Corpus em casos de uso de drogas"], "confidence": 0.8, "extracted_at": "2026-05-30T00:56:41.335535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=192", "doc_key": "c337201eb1a52f72c14b6bf9c3598c12"}'::jsonb, '{"materia": "Direito da Criancça e do Adolescente"}'::jsonb, 'cp_iuris_2025', '9760bc4826dbcf3b6f5cc730631d8640c9f9b5acd8718c849b926971d531f4ad'),
  ('cpiuris2025::fff429887b4e997e62e964b6360e3b2f', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Limitações à aplicação de medidas extimas', '## Limitações à aplicação de medidas extimas

A lei estabelece uma limitação à aplicação de nova medida extrema, vedando-a em razão de atos infracionais praticados anteriormente.

### Conceitos
- **Medida Extrema**: Mesa de proteção especial para o menor
- **Infracional**: Ato ilegal ou antiético

### Referências legais
- § 2º da Lei X, que estabelece limitações à aplicação de medidas extimas

### Dicas de prova
- Entenda a vedação ao atos infracionais praticados anteriormente
- Interprete a norma contida no § 2º', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.193 (3)", "page_number": 193, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["§ 2º da Lei X, que estabelece limitações à aplicação de medidas extimas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T00:56:45.075869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=193", "doc_key": "fff429887b4e997e62e964b6360e3b2f"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '35fedd2cd8171330780436a1f0f2d5cce3e203aee775e5532d94bd7bbb7224ed'),
  ('cpiuris2025::3c9943af0490327049c5f9667334a4d8', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Hipótese de não unificação de medidas socioeducativas', '## Hipótese de não unificação de medidas socioeducativas

Regra para a aplicação de nova medida socioeducativa em caso de ato infracional praticado durante o cumprimento da medida ou antes do início do cumprimento.

### Conceitos
- **Medida socioeducativa**: Mensagem sobre a aplicação de medidas para o adolescente
- **Atos infracionais**: Comportamentos ilegais cometidos pelo adolescente
- **Transito da execução**: Passagem do tempo durante a execução da medida socioeducativa
- **Unificação de medidas**: Ação de unir as medidas socioeducativas aplicadas ao adolescente
- **Autoridade judiciária**: Ente que decide sobre a aplicação das medidas socioeducativas
- **Ministério Público**: Ente que representa o Estado na justiça
- **Defensor**: Advogado que representa os interesses do adolescente

### Referências legais
- Art. 45 da Lei 12.594/2012

### Jurisprudência
- HC 338.517-SP, Rel. Min. Nefi Cordeiro

### Dicas de prova
- Entenda a hipótese de não unificação de medidas socioeducativas e como ela afeta o cumprimento da medida.
- Conheça as regras para a aplicação de nova medida socioeducativa em caso de ato infracional praticado durante o cumprimento da medida ou antes do início do cumprimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.193 (2)", "page_number": 193, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 45 da Lei 12.594/2012"], "jurisprudence": ["HC 338.517-SP, Rel. Min. Nefi Cordeiro"], "confidence": 0.8, "extracted_at": "2026-05-30T00:56:46.458912+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=193", "doc_key": "3c9943af0490327049c5f9667334a4d8"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'b18f4153640d8946e57a74a22d6ff282a4e10caf20af1e6918f32bac4bd60991'),
  ('cpiuris2025::a01f386f2763f0d4c450cea935e866a5', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Fundamentação de decisões em medidas socioeducativas', '## Fundamentação de decisões em medidas socioeducativas

Resumo objetivo: A questão exige identificar quando deve ser fundamentada uma decisão que altera ou extingue uma medida socioeducativa. Isso envolve analisar as opções e determinar a situação em que um parecer técnico é obrigatório.

### Conceitos
- **Lei do SINASE**: Lei nº 12.594/2012
- **Estatuto da Criança e do Adolescente**: Lei nº 8.069/1990
- **Medida socioeducativa**: Mudança ou extinção de uma medida socioeducativa
- **Parecer técnico**: Opinião técnica necessária para fundamentar a decisão

### Referências legais
- Art. 32 da Lei nº 12.594/2012
- Art. 14 da Lei nº 8.069/1990

### Jurisprudência
- Súmula 444 do STF

### Dicas de prova
- Pergunte-se se a decisão altera ou extingue uma medida socioeducativa.
- Verifique se o parecer técnico é obrigatório para fundamentar a decisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.194 (2)", "page_number": 194, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 32 da Lei nº 12.594/2012", "Art. 14 da Lei nº 8.069/1990"], "jurisprudence": ["Súmula 444 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T00:59:06.640323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=194", "doc_key": "a01f386f2763f0d4c450cea935e866a5"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '0b4a0dc295c55747e379d34b38a57fcf22d1f78dffccfaef7f7bf905c35349df'),
  ('cpiuris2025::3283774f0303182d2ab9115b393db6ac', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Medidas socioeducativas e impugnação de Plano Individual de Atendimento', '## Medidas socioeducativas e impugnação de Plano Individual de Atendimento

A impugnação do Plano Individual de Atendimento deve ser fundamentada em laudo técnico, mas não suspende a execução do plano individual. A função de fiscalização do Sistema Nacional de Atendimento Socioeducativo é exercida pela justiça da infância e da juventude.

### Conceitos
- **Medidas socioeducativas**: Mensuras aplicadas ao adolescente em conflito com a lei, visando sua ressocialização
- **Plano Individual de Atendimento**: Documento que define as medidas socioeducativas a serem aplicadas ao adolescente
- **Impugnação do Plano Individual de Atendimento**: Procedimento pelo qual o adolescente ou seus representantes legais questionam a adequação das medidas socioeducativas
- **Laudo técnico**: Documento que analisa a viabilidade da impugnação e fundamenta as razões
- **Fiscalização do Sistema Nacional de Atendimento Socioeducativo**: Responsabilidade da justiça da infância e da juventude em garantir a eficácia das medidas socioeducativas

### Referências legais
- Art. 121 do ECA
- Art. 45 da Lei 12.594/2012

### Jurisprudência
- HC 274.565-RJ

### Dicas de prova
- Entenda a importância de um laudo técnico na impugnação do Plano Individual de Atendimento
- Conheça a função da justiça da infância e da juventude no Sistema Nacional de Atendimento Socioeducativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.194 (1)", "page_number": 194, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 121 do ECA", "Art. 45 da Lei 12.594/2012"], "jurisprudence": ["HC 274.565-RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T00:59:47.363421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=194", "doc_key": "3283774f0303182d2ab9115b393db6ac"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '1706855c67a5c516b700c416f48deb1591e7e1b864799ba64b28534264d98d06'),
  ('cpiuris2025::8ea1f6dda2caca91bf09905c403d6562', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Medidas Socioeducativas e Regime Disciplinar para Adolescentes', '## Medidas Socioeducativas e Regime Disciplinar para Adolescentes

A questão discute o regime disciplinar aplicável a adolescentes em cumprimento de medida socioeducativa privativa de liberdade, destacando previsões da ONU e da Lei n. 12.594/12.

### Conceitos
- **Regras Mínimas da ONU**: Previsão expressa para proteção de jovens privados de liberdade
- **Lei n. 12.594/12**: Lei que estabelece regras para medidas socioeducativas e regime disciplinar para adolescentes
- **Funções disciplinares**: Não devem ser atribuídas a adolescentes, exceto em casos específicos
- **Apuração de falta disciplinar**: Deve estar a cargo da autoridade judicial responsável pela fiscalização do estabelecimento
- **Sanções coletivas**: Não podem ser aplicadas, exceto em casos de motim generalizado
- **Processo disciplinar**: Pode ser dispensado para faltas leves com pena máxima prevista em advertência verbal
- **Atividades de escolarização e profissionalização**: Não podem ser suspensas por mais de 15 dias, exceto em casos de manifesta periculosidade

### Referências legais
- Art. 12 da Lei n. 12.594/2012

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre funções disciplinares e supervisão de atividades sociais
- Importância da autoridade judicial na apuração de falta disciplinar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.195", "page_number": 195, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 12 da Lei n. 12.594/2012"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T01:00:00.969664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=195", "doc_key": "8ea1f6dda2caca91bf09905c403d6562"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', '1d88d8960a4bd4ba345f8e8cf2f82320f2e9a5f241413b46d645b6123bc11cd2'),
  ('cpiuris2025::b4737736462ebf8b362200764fcbf637', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Ações Provisórias e Declaração de Constitucionalidade', '## Ações Provisórias e Declaração de Constitucionalidade

