  ('cpiuris2025::a8ef610fea61f345e21fe4767ce2212f', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Repetição de Processos e Recursos', '## Repetição de Processos e Recursos

A repetição de processos e recursos é um tema importante no Direito da Criança e do Adolescente, envolvendo a análise de casos em que os processos foram repetidos por razões legais ou técnicas.

### Conceitos
- **Repetição de Processo**: Ação em que se busca anular o processo anterior por motivos técnicos ou legais.
- **Recursos Extraordinários**: Mérito da ação, com o objetivo de alterar a decisão do juiz de primeiro grau.
- **Recurso Ordinário Conconstitucional**: Ação que visa interpretar ou modificar a Constituição Federal.
- **Súmula**: Preceito jurídico estabelecido pela autoridade judiciária, com o objetivo de evitar a repetição de decisões idênticas.

### Referências legais
- Art. 522 do Código de Processo Civil
- Súmula 01
- Súmula 108/STJ

### Jurisprudência
- REsp 1.421.409/DF
- REsp 1.452.660/ES
- REsp 1.517.973/PE
- REsp 1.543.267/SC
- REsp 1.545.959/SC
- REsp 1.550.166/DF

### Dicas de prova
- Entenda a diferença entre repetição de processo e recurso extraordinário.
- Conheça as súmulas do STJ e como elas podem influenciar a decisão do juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf", "source_ref": "IURIS - Direito da Criança e do Adolescente - 2025.pdf · p.200", "page_number": 200, "discipline": "Direito da Criança e do Adolescente", "legal_refs": ["Art. 522 do Código de Processo Civil", "Súmula 01", "Súmula 108/STJ"], "jurisprudence": ["REsp 1.421.409/DF", "REsp 1.452.660/ES", "REsp 1.517.973/PE", "REsp 1.543.267/SC", "REsp 1.545.959/SC", "REsp 1.550.166/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T01:06:11.578890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito da Criança e do Adolescente - 2025.pdf#page=200", "doc_key": "a8ef610fea61f345e21fe4767ce2212f"}'::jsonb, '{"materia": "Direito da Criança e do Adolescente"}'::jsonb, 'cp_iuris_2025', 'e2a8fc57c766102be215c5ee1b2a9c6e9c223f7218fb8820decab32ad57d950d'),
