  ('cpiuris2025::8bca1ee36096dcd86caa193cc21cac59', 'doutrina', 'cp_iuris', 'Direito da Criança e do Adolescente — Súmulas sobre Direito da Infância e Juventude', '## Súmulas sobre Direito da Infância e Juventude

Resumo das súmulas apresentadas, destacando a aplicabilidade de medidas socioeducativas e competência jurisdicional.

### Conceitos
- **Maioridade penal**: A idade acima da qual o indivíduo não é considerado menor de idade para os fins do direito penal.
- **Medidas socioeducativas**: São medidas aplicadas ao adolescente por meio de uma autoridade pública, com o objetivo de reeducação e reintegração social.
- **Competência jurisdicional**: A competência do juiz para processar e julgar um caso específico.
- **Desistência de provas**: O ato de renunciar a uma prova em um processo judicial.
- **Confissão do adolescente**: A declaração feita pelo adolescente sobre sua participação no ato infracional.
- **Paternidade**: A relação entre o pai e o filho, especialmente na relação de responsabilidade pela ação ou omissão do filho.
- **Prova de paternidade**: A prova necessária para comprovar a paternidade de um filho.

