  ('cpiuris2025::0de6a753bfbdfe1b1e3874d30e0f0f9a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Definição de Consumidor', '## Definição de Consumidor

O conceito de consumidor é definido como pessoa física que adquire produtos ou serviços, podendo também ser a empresa que fornece os mesmos.

### Conceitos
- **Consumidor**: pessoa física ou empresa que adquire produtos ou serviços
- **Fornecedor**: empresa que fornece produtos ou serviços
- **Internet**: canal de relações de consumo
- **Profissionais liberais**: pessoas físicas que exercem atividades profissionais
- **Equiparação**: conceito que permite a inclusão de pessoas físicas em determinadas situações jurídicas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre consumidor e fornecedor
- Importância do conceito de equiparação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:09:08.504718+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=4", "doc_key": "0de6a753bfbdfe1b1e3874d30e0f0f9a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '02d38521d1ffb1c6e02f013158002b46c86532e811c924f49366d0bb008cee7e'),
  ('cpiuris2025::0705df1b3efc8c468ea8a2d008fa47bb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Definição e Contextualização do CDC', '## Definição e Contextualização do CDC

O Direito do Consumidor é uma disciplina jurídica que visa proteger os consumidores de abusos cometidos por fornecedores de bens e serviços. O texto destaca a importância da definição do conceito de consumidor, inspiração constitucional e natureza jurídica do CDC.

### Conceitos
- **Vulnerabilidade do Consumidor**: A capacidade do consumidor de sofrer prejuízos econômicos ou físicos
- **Inversão do Ónus da Prova**: O dever do fornecedor de provar a não existência de dano ao consumidor
- **Defesa do Consumidor pelo Estado**: A proteção do consumidor por meio das leis e normas estatais
- **Harmonização**: A busca pela uniformidade e consistência nas regras e práticas comerciais
- **Boa-Fé Objetiva**: O dever do fornecedor de agir com honestidade e transparência em suas relações com o consumidor

### Referências legais
- Art. 50 da Lei nº 8.978/1996

### Dicas de prova
- Entenda a definição de vulnerabilidade do consumidor e como isso afeta a responsabilidade do fornecedor
- Conheça o princípio da inversão do ônus da prova e como ele se aplica às relações entre consumidores e fornecedores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 da Lei nº 8.978/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:09:41.940959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=4", "doc_key": "0705df1b3efc8c468ea8a2d008fa47bb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fad03cb99520e7adceafd2198b3938e1eb4e8d0e405863d3a7826ea7b717816e'),
  ('cpiuris2025::14b71441ae99e377ea0d530effa1ca4e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade e Excludentes de Nexo de Causalidade', '## Responsabilidade e Excludentes de Nexo de Causalidade

Discute a responsabilidade do consumidor por danos causados por produtos ou serviços, incluindo excludentes de nexo de causalidade.

### Conceitos
- **Danos ao Tempo**: Bem jurídico autônomo
- **Responsabilidade do profissional médico**: Obrigação de reparar os danos causados
- **Excludentes de Nexo de Causalidade**: Imunidades que excluem a responsabilidade pelo dano

### Referências legais
- Art. 18 da Lei nº 8.978/1996

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre danos ao tempo e danos morais
- Conheça as excludentes de nexo de causalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18 da Lei nº 8.978/1996"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T01:10:43.466552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=5", "doc_key": "14b71441ae99e377ea0d530effa1ca4e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c80739f40d82143bf3a879398c180d6e9e19d2fcce3d6bed7ba7767a779c6a88'),
  ('cpiuris2025::42f5b668b69c178f0f35f318752068a8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios Gerais do Direito do Consumidor', '## Princípios Gerais do Direito do Consumidor

São apresentados 16 princípios que regem a relação jurídica de consumo, abordando aspectos como transparência, segurança e reparação integral.

### Conceitos
- **Princípio da Transparência**: O dever de informar claramente ao consumidor sobre os termos do contrato ou serviço.
- **Princípio da Informação**: A obrigação de fornecer informações precisas e completas ao consumidor.
- **Princípio da Segurança**: O direito do consumidor à segurança em relação aos produtos e serviços oferecidos.
- **Princípio do Equilíbrio nas Prestações**: A necessidade de equilibrar as prestações oferecidas pelo fornecedor com as expectativas do consumidor.
- **Princípio da Reparação Integral**: O direito do consumidor à reparação integral em caso de vício ou defeito nos produtos ou serviços.
- **Princípio da Solidariedade**: A responsabilidade solidária dos fornecedores por danos causados ao consumidor.
- **Princípio da Interpretação Mais Favorável ao Consumidor**: O princípio de interpretação favorável ao consumidor em caso de dúvida sobre a interpretação do contrato.
- **Princípio da Reparação Objetiva**: A obrigação de reparar os danos causados ao consumidor, independentemente da culpa ou não.

### Referências legais
- Art. 50 da Lei nº 8.078/1990

### Dicas de prova
- Entenda a importância do princípio da transparência e como ele afeta a relação jurídica de consumo.
- Conheça as diferentes formas de reparação integral oferecidas pelo direito do consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.4 (2)", "page_number": 4, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:11:30.956378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=4", "doc_key": "42f5b668b69c178f0f35f318752068a8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f3e971113adf092207f17e8d811a621e666fd61dd366f0545e584fc9951b3681'),
  ('cpiuris2025::fc984ed5d90cd02cd35bed3295304edc', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Comerciais e Publicidade nas Relações de Consumo', '## Práticas Comerciais e Publicidade nas Relações de Consumo

Discute as regras gerais para práticas comerciais, incluindo a oferta, publicidade e solidariedade do fornecedor.

### Conceitos
- **Oferta**: Declaração feita pelo vendedor que se compromete a entregar um bem ou serviço ao consumidor.
- **Publicidade**: Mensagem enviada ao consumidor para promover um produto ou serviço.
- **Solidariedade do fornecedor**: Obrigação do fornecedor de pagar pelos atos dos prepostos ou representantes autônomos.
- **Venda por telefone e reembolso postal**: Método de venda que permite ao consumidor devolver um produto sem se deslocar.
- **Dever de prestar informações corretas e precisas**: Obrigação do vendedor de fornecer informações verdadeiras sobre o produto ou serviço.
- **Efeito vinculante da oferta publicitária**: A oferta feita por meio de publicidade é considerada vinculante para o consumidor.
- **Princípio da identificação**: O vendedor deve identificar-se claramente na publicidade para evitar confusão com outras empresas.
- **Princípio da veracidade**: A publicidade deve ser verdadeira e não enganosa

### Referências legais
- Art. 47 da Lei nº 8.078/1990

### Dicas de prova
- Entenda a distinção entre oferta e publicidade.
- Conheça as regras para solidariedade do fornecedor.
- Não confunda a venda por telefone com o reembolso postal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 47 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:11:41.738414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=5", "doc_key": "fc984ed5d90cd02cd35bed3295304edc"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2c583a1f57c67a5088f2b6418fe7d80aab0a19b609d2c7a05569b8c7606a210d'),
  ('cpiuris2025::0cbc8b0d9426d75d43bef1b4a8a789be', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas Abusivas - Art. 51 do CDC', '## Cláusulas Abusivas - Art. 51 do CDC

Regra para identificação e análise de cláusulas abusivas em contratos de consumo.

### Conceitos
- **Cláusula abusiva**: cláusula que coloca o consumidor em desvantagem exagerada
- **Responsabilidade do fornecedor**: fornecedor é responsável por cláusulas abusivas
- **Vinculação do fornecedor**: fornecedor não pode optar pela não execução de um contrato

### Referências legais
- Art. 51 do CDC

### Dicas de prova
- Diferenciar cláusulas abusivas das normais
- Análise da cláusula para identificação de cláusulas abusivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:13:22.164830+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=6", "doc_key": "0cbc8b0d9426d75d43bef1b4a8a789be"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7ec9aa074998dab184f0a6e9adc6bcf2f44404435b6efd498782ab502d731c81'),
  ('cpiuris2025::2e2b94d636514ed5f997ea7a0ccb80a0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Regras de Proteção ao Consumidor', '## Regras de Proteção ao Consumidor

São apresentadas regras para proteger os consumidores em diversas situações, incluindo repasse de informações depreciativas, inserção no mercado de produtos desacordos com normas técnicas e cobrança de dívidas.

### Conceitos
- **Transparência**: O dever do fornecedor de ser claro e transparente em suas práticas comerciais
- **Vinculação Contratual**: A obrigação do consumidor de cumprir as cláusulas contratuais estabelecidas
- **Princípio da Transparência**: O princípio que exige que os fornecedores sejam claros e transparentes em suas práticas comerciais

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Dicas de prova
- Entenda o conceito de transparência no contexto do Direito do Consumidor
- Identifique a importância da vinculação contratual para os consumidores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:13:49.234890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=6", "doc_key": "2e2b94d636514ed5f997ea7a0ccb80a0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c73470bf7ab2b186e9ce807fa9cda1a669d8ccfe5a8226696af1b303d24e2ff4'),
  ('cpiuris2025::c6030633fc738f1871fc2aa809a45c62', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios e Práticas Abusivas na Publicidade', '## Princípios e Práticas Abusivas na Publicidade

Discute os princípios da não abusividade, transparência e lealdade publicitária, além de práticas abusivas em espécie, como venda casada, recusa de contratar e produtos enviados sem solicitação prévia.

### Conceitos
- **Princípio da não abusividade**: Regra que proíbe ações publicitárias que sejam prejudiciais ao consumidor
- **Princípio da transparência da fundamentação**: Regra que exige clareza e precisão nas afirmações feitas pelas empresas em sua publicidade
- **Princípio da Lealdade Publicitária**: Regra que proíbe a manipulação de informações para influenciar a opinião do consumidor

### Referências legais
- Art. 47 da Lei nº 8.078/1990

### Dicas de prova
- Entenda o conceito de não abusividade e como ela se aplica à publicidade
- Identifique as regras de transparência e lealdade publicitária
- Conheça as práticas abusivas em espécie e como elas são regulamentadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 47 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:14:14.204029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=5", "doc_key": "c6030633fc738f1871fc2aa809a45c62"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3049c9931c25ddff4a5e93bf7aa748d99b27086d675b97d68b6fc56f85216ed0'),
  ('cpiuris2025::e52f70f1eaa1eed1e4c3ef2360f670d9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Superendividamento', '## Superendividamento

Regra que estabelece as regras para o superendividamento, incluindo conceitos e princípios a serem considerados.

### Conceitos
- **Conceito de Superendividamento**: Situação em que um consumidor se encontra em dívida com vários credores
- **Princípios do Superendividamento**: Regras que visam proteger o consumidor de situações de superendividamento

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a definição de superendividamento e os princípios que a regem.
- Conheça as diferentes sanções administrativas aplicáveis ao superendividamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:15:51.380775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=7", "doc_key": "e52f70f1eaa1eed1e4c3ef2360f670d9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3c9eca9d91ec4c317e4d9a580f153596bf3b10159eff77eb79c59ace3e4ce268'),
  ('cpiuris2025::ef566975a4d80b6e4058962d3955f5c3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas abusivas e contratos de consumo', '## Cláusulas abusivas e contratos de consumo

Trecho sobre cláusulas abusivas em contratos de consumo, incluindo prazos de carência e restabelecimento dos direitos do consumidor.

### Conceitos
- **Cláusula abusiva**: cláusula que viole os princípios do direito do consumidor
- **Prazo de carência**: período durante o qual o consumidor pode reavaliar a cláusula abusiva
- **Restabelecimento dos direitos do consumidor**: direito do consumidor de recuperar seus direitos após a impontualidade ou acordo com os credores

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a noção de cláusula abusiva e como ela afeta os direitos do consumidor
- Identifique o prazo de carência e sua importância para o consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T01:16:05.127043+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=7", "doc_key": "ef566975a4d80b6e4058962d3955f5c3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b16729755ffae47fdde5390a71a28fc448451c384e15e9c4ceea6eda97e2fa9a'),
  ('cpiuris2025::8abee9f93f81fde5dcb794944b3d37ee', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas abusivas no contrato', '## Cláusulas abusivas no contrato

São listadas cláusulas que podem ser consideradas abusivas para o consumidor, incluindo variação unilateral de preço, cancelamento unilateral do contrato e cobrança de custos de cobrança.

### Conceitos
- **Cláusula abusiva**: cláusula que prejudica os direitos do consumidor
- **Variação unilateral de preço**: mudança no preço sem aviso prévio ao consumidor
- **Cancelamento unilateral do contrato**: cancelamento do contrato pelo fornecedor sem aviso prévio ao consumidor
- **Cobrança de custos de cobrança**: cobrança dos custos de cobrança pela parte que não cobra
- **Modificação unilateral do contrato**: mudança no conteúdo ou qualidade do contrato sem aviso prévio ao consumidor
- **Renúncia do direito de indenização por benfeitorias necessárias**: renúncia do direito de indenização pela parte que realizou uma benfeitoria necessária

### Referências legais
- Art. 47 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a definição de cláusula abusiva e como ela é regulamentada pela lei.
- Identifique as cláusulas que podem ser consideradas abusivas para o consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 47 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T01:16:25.749548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=6", "doc_key": "8abee9f93f81fde5dcb794944b3d37ee"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '86f41fd329b4d6221043c07bf07e193ef3de3f7529f50b3f341b43ef17e5486e'),
  ('cpiuris2025::042885e08c14a31f4f4553ca75f9296a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Conceito e Natureza Jurídica do Direito do Consumidor', '## Conceito e Natureza Jurídica do Direito do Consumidor

O Direito do Consumidor é definido como o conjunto de normas e princípios que tratam da sociedade de consumo com o objetivo de promover a tutela integral, sistemática e dinâmica da parte vulnerável na relação consumerista.

### Conceitos
- **Composição**: normas e princípios
- **Objeto de Preocupação**: sociedade de consumo
- **Objetivo**: tutela integral, sistemática e dinâmica da parte vulnerável na relação consumerista

### Referências legais
- Art. 5º, XXXII, da Constituição Federal de 1988 (CF/88)
- Art. 170, V, da CF/88
- Art. 48 do Ato das Disposições Constitucionais Transitórias da CF/88
- Art. 24, VIII, da CF/88

### Dicas de prova
- Entenda a composição e objeto de preocupação do Direito do Consumidor.
- Conheça o objetivo do Direito do Consumidor e como ele se relaciona com a parte vulnerável na relação consumerista.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.8", "page_number": 8, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º, XXXII, da Constituição Federal de 1988 (CF/88)", "Art. 170, V, da CF/88", "Art. 48 do Ato das Disposições Constitucionais Transitórias da CF/88", "Art. 24, VIII, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:18:29.026352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=8", "doc_key": "042885e08c14a31f4f4553ca75f9296a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '1c5beaa71704c53cb962067cc0037cf2a5f4097bd9a1f2f0d682896586e7cc12'),
  ('cpiuris2025::ba27b16716d8d68c725eaf3370ee01ec', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Regras Gerais do Consumidor', '## Regras Gerais do Consumidor

Regras gerais que regem as relações entre consumidores e comerciantes, incluindo direitos coletivos, legitimados, estímulo à efetividade e competência.

### Conceitos
- **Direito Coletivo**: direito concedido a um grupo de pessoas
- **Legitimado**: parte que tem direito de agir em nome de outrem
- **Custas, Emolumentos, Despesas e Honorários**: despesas e honorários pagos pelo consumidor
- **Ação de Regresso do Comerciante**: ação que o comerciante pode iniciar contra o consumidor
- **Princípio da Publicidade**: princípio que exige a publicidade das regras e regulamentos

### Referências legais
- Art. 50 da Lei nº 8.978/1996
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Legitimidade dos consumidores

### Dicas de prova
- Entenda a noção de direito coletivo e seus limites
- Conheça as partes que podem ser legitimadas em uma ação do consumidor
- Aprenda a distinguir entre custas, emolumentos, despesas e honorários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 da Lei nº 8.978/1996", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Legitimidade dos consumidores"], "confidence": 0.8, "extracted_at": "2026-05-30T01:18:38.758511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=7", "doc_key": "ba27b16716d8d68c725eaf3370ee01ec"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b73210f8cacfedc8276b660f9adf03018943f61257bfaae77132e6aaaea32c20'),
  ('cpiuris2025::65bd1c9cb1e3378242cb5b6a1e674c2e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC e Microssistema Legislativo', '## Princípios do CDC e Microssistema Legislativo

O Código de Defesa do Consumidor é um microssistema legislativo que abrange normas de direito público e privado, material e processual, além de várias áreas do direito. Embora seja uma norma abrangente e sistemática, não esgota a matéria, que também pode ser extraída de outras fontes do direito.

### Conceitos
- **Microssistema Legislativo**: Um conjunto de leis que abordam um tema específico
- **Normas de Direito Público e Privado**: Regras que regem as relações entre o Estado e os cidadãos, ou entre as pessoas físicas e jurídicas
- **Direito Material e Processual**: Subdivisões do direito que abordam a substância das relações jurídicas e as formas de resolução delas
- **Áreas do Direito**: Categorias de direito que abordam temas específicos, como civil, penal, processual, administrativo, etc.

### Referências legais
- Art. 48 do ADCT

### Jurisprudência
- RE 123456
- Tema repetitivo: Microssistema Legislativo

### Dicas de prova
- Entenda a noção de microssistema legislativo e como ele se aplica ao Código de Defesa do Consumidor
- Identifique as áreas do direito que são abordadas pelo CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 48 do ADCT"], "jurisprudence": ["RE 123456", "Tema repetitivo: Microssistema Legislativo"], "confidence": 0.8, "extracted_at": "2026-05-30T01:19:22.478454+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=9", "doc_key": "65bd1c9cb1e3378242cb5b6a1e674c2e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6ae65fc9fd13e03b7ef78ca7c26d5c248bbd357ea271c8713b3aae6c02c6e356'),
  ('cpiuris2025::d0dd3b9d2f73749ce8011198cf571541', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Abordagem do CDC em relação à codificação e direitos', '## Abordagem do CDC em relação à codificação e direitos

O CDC se afasta da forma tradicional de codificação, focando na efetividade e interpretação constitucional das suas disposições.

### Conceitos
- **Direito Material**: Guia para eleição das normas do texto do CDC
- **Normas de Caráter Princípiológico**: Normas que compõem o texto do CDC, independentemente da sua natureza formal ou ramo jurídico

### Referências legais
- Art. 1º da Lei nº 8.978/1994

### Dicas de prova
- Entenda a abordagem do CDC em relação à codificação e direitos.
- Identifique o direito material como guia para eleição das normas do texto do CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1º da Lei nº 8.978/1994"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:20:19.811241+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=9", "doc_key": "d0dd3b9d2f73749ce8011198cf571541"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '43345e651fe3e58dec29cddf1e44c65da8002c685b6a1ff03cdbd3b2d61a2030'),
  ('cpiuris2025::7e26b5d42bb5fa63e82086217be3f585', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Normas de Ordem Pública e Interesse Social no CDC', '## Normas de Ordem Pública e Interesse Social no CDC

O CDC estabelece normas de proteção e defesa do consumidor, de ordem pública e interesse social, com características cogentes, obrigatórias e não admitindo renúncia prévia em prejuízo do consumidor.

### Conceitos
- **Normas de Ordem Pública e Interesse Social**: Regras que protegem o consumidor e são de interesse público
- **Cogência**: Obrigatórias, sem renúncia prévia em prejuízo do consumidor
- **Heteronomia**: Intervenção estatal no espaço da autonomia da vontade

### Referências legais
- Art. 1º do CDC
- Art. 48 das Disposições Transitorias da Constituição Federal

### Jurisprudência
- Súmula 381 do STJ

### Dicas de prova
- Entenda a noção de heteronomia e sua relação com a autonomia da vontade
- Conheça as características das normas de ordem pública e interesse social no CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1º do CDC", "Art. 48 das Disposições Transitorias da Constituição Federal"], "jurisprudence": ["Súmula 381 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T01:21:05.872675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=10", "doc_key": "7e26b5d42bb5fa63e82086217be3f585"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8175dc1d862fceedadcd98b170aed36df201ff5fe12f017de2a3b677b109476f'),
  ('cpiuris2025::42c55c36747d9c2aef75a3c199460212', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Força Obligatória dos Contratos', '## Princípio da Força Obligatória dos Contratos

O princípio da força obrigatória dos contratos é um princípio jurídico que afirma a importância das compromissões feitas pelas partes em uma relação contratual. No entanto, com a constitucionalização do direito privado e a intervenção do Estado nas relações contratuais, o princípio foi mitigado, mas não eliminado.

### Conceitos
- **Princípio da Força Obligatória dos Contratos**: Princípio que afirma a importância das compromissagens feitas pelas partes em uma relação contratual
- **Autonomia da Vontade**: Direito das partes de escolher livremente suas obrigações em relações contratuais
- **Pacta Sunt Servanda**: Princípio que afirma a importância da cumprimento das compromissas feitas pelas partes em uma relação contratual

### Referências legais
- Art. 50 do CDC

### Jurisprudência
- REsp nº 586316 / MG
- Súmula 346 STJ

### Dicas de prova
- Entenda a importância do princípio da força obrigatória dos contratos e como ele foi afetado pela constitucionalização do direito privado.
- Conheça as palavras-chave do Ministro Herman Benjamin no julgamento do REsp nº 586316 / MG.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 do CDC"], "jurisprudence": ["REsp nº 586316 / MG", "Súmula 346 STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T01:22:11.904573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=10", "doc_key": "42c55c36747d9c2aef75a3c199460212"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '25fd77a36a0ce3735ecb8b7510703ede051080b07ac3be8c6dc74c97a84b3ab0'),
  ('cpiuris2025::75258c191b66ed7e64b928e30d0b0d55', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC', '## Princípios do CDC

Os princípios do CDC são fundamentais para a proteção dos consumidores, incluindo a boa-fé objetiva, equilíbrio material e vedação do abuso de direito.

### Conceitos
- **boa-fé objetiva**: necessidade de honestidade e sinceridade nas negociações
- **equilíbrio material**: necessidade de equilibrar os direitos e deveres das partes
- **vedação do abuso de direito**: proibição de condutas que sejam descompassadas com a duração da relação

### Referências legais
- Art. 421 do Código Civil brasileiro
- Art. 2.035 do Código Civil brasileiro
- Art. 1º do CDC

### Jurisprudência
- Súmula 302 do STJ
- REsp nº 1073595/MG

### Dicas de prova
- Entenda a boa-fé objetiva e seu papel no CDC
- Identifique os limites das cláusulas contratuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 421 do Código Civil brasileiro", "Art. 2.035 do Código Civil brasileiro", "Art. 1º do CDC"], "jurisprudence": ["Súmula 302 do STJ", "REsp nº 1073595/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T01:22:47.878573+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=11", "doc_key": "75258c191b66ed7e64b928e30d0b0d55"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b36b10261fb77422cad0387a8db9c274703c5ac229e81d8c0706031e05baf857'),
  ('cpiuris2025::214cfaa993592704990aa3eb76b4beca', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Lei de função social e inconstitucionalidade', '## Lei de função social e inconstitucionalidade

O CDC é considerado uma lei de função social, o que significa que não pode ser abrogada ou derrogada por outros diplomas legais de igual hierarquia em detrimento dos direitos do consumidor.

### Conceitos
- **Lei de função social**: Lei que estabelece um peso normativo abaixo do qual é ilícito ir
- **Inconstitucionalidade**: Ação que visa anular uma lei ou ato administrativo por violar a Constituição Federal

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de lei de função social e sua relação com a inconstitucionalidade
- Identifique a hierarquia dos diplomas legais e como isso afeta a abrogabilidade do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T01:23:09.980339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=11", "doc_key": "214cfaa993592704990aa3eb76b4beca"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '76180b6d9abe2dd3e9e559c7a41d7fb038d7a2341c3a8636a2ee27a3b7bdd5cf'),
  ('cpiuris2025::2fdd48c61ae50cf907ab21c02ca88a3b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC e Retrocesso Social', '## Princípios do CDC e Retrocesso Social

O texto discute a possibilidade de existir um princípio da vedação do retrocesso em matéria consumerista, com base em acórdãos do STF. Além disso, analisa a aplicabilidade do CDC aos contratos que envolvem prestação de trato sucessivo.

### Conceitos
- **Retrocesso Social**: Modificação de lei que prejudique os direitos assegurados pelo Código de Defesa do Consumidor
- **Vedação do Retrocesso**: Princípio que proíbe a modificação de lei que prejudique os direitos assegurados pelo Código de Defesa do Consumidor
- **Irretroatividade das Leis**: Princípio que proíbe a aplicação de leis novas para retroceder a situações já existentes

### Referências legais
- Art. 178 da Constituição da República
- Convenção de Varsóvia e Montreal
- Lei de Introdução às Normas do Direito Brasileiro (LINDB)

### Jurisprudência
- RE 351750/RJ
- RE 636.331/RJ
- ADIs 5224, 5252, 5273 e 5978

### Dicas de prova
- Entenda a noção de retrocesso social e vedação do retrocesso em matéria consumerista
- Análise dos comandos do art. 5º, XXXVI, da CF/88 e do art. 6º da LINDB', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 178 da Constituição da República", "Convenção de Varsóvia e Montreal", "Lei de Introdução às Normas do Direito Brasileiro (LINDB)"], "jurisprudence": ["RE 351750/RJ", "RE 636.331/RJ", "ADIs 5224, 5252, 5273 e 5978"], "confidence": 0.8, "extracted_at": "2026-05-30T01:24:32.469608+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=12", "doc_key": "2fdd48c61ae50cf907ab21c02ca88a3b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '396924c72f29a40a27b9b94560a2bd822fd28e83dd35f5e7e900d12859487cb2'),
  ('cpiuris2025::529c9d2c541eb505befb9bb1e4cf1293', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Retroatividade da Lei do Consumidor', '## Retroatividade da Lei do Consumidor

A Lei do Consumidor não se aplica a contratos firmados antes de sua vigência, exceto em casos específicos como a Lei nº 14.181/2021.

### Conceitos
- **Retroatividade mínima**: Prazo temporal após o qual uma lei pode ser aplicada retroativamente aos contratos firmados antes dela.
- **Contrato pactuado antes da vigência da Lei do Consumidor**: Condição para a aplicação da Lei do Consumidor em um contrato.
- **Lei nº 14.181/2021**: Exceção à regra de retroatividade mínima, que permite a aplicação da lei aos efeitos produzidos após sua entrada em vigor.
- **Superendividamento**: Condição para a aplicação do art. 3º da Lei nº 14.181/2021.
- **Retroatividade mínima na legislação**: Situação em que a própria lei afirma sua retroatividade mínima.
- **Lei do Distrato Imobiliário (13.786/18)**: Exemplo de lei que não se aplica a contratos firmados antes de sua vigência.
- **Convenção de Montreal**: Convenção internacional que regulamenta os contratos de compras e vendas internacionais.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 555.906/SP; RE 204769/RS; ADI 493/DF; REsp 1.498.484

### Dicas de prova
- Entenda a distinção entre retroatividade mínima e retroatividade na legislação.
- Conheça as exceções à regra de retroatividade mínima, como a Lei nº 14.181/2021.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 555.906/SP; RE 204769/RS; ADI 493/DF; REsp 1.498.484"], "confidence": 0.8, "extracted_at": "2026-05-30T01:24:50.449466+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=12", "doc_key": "529c9d2c541eb505befb9bb1e4cf1293"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8fe684629d19b46669486e299ca10c309f5c65b386027dcb115dc91a99b14977'),
  ('cpiuris2025::09531949672360f7a10d28de4e37882a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Diálogo entre a TDF e outras leis', '## Diálogo entre a TDF e outras leis

A aplicação da TDF ocorre por meio de diálogos entre a lei geral (como o CC) e a lei especial (como o CDC), considerando coerência, complementaridade ou influências recíprocas.

### Conceitos
- **Diálogo Sistemático**: aplicação simultânea ou coordenada das duas leis
- **Coerência**: aplicação de uma lei como base conceitual para a outra
- **Complementaridade**: aplicação coordenada das duas leis, dependendo do campo de aplicação no caso concreto
- **Subsidiariedade**: aplicação da lei especial quando a lei geral não for suficiente

### Referências legais
- Art. 3 da Lei nº 8.078/1990 (TDF)

### Dicas de prova
- Entenda o conceito de diálogo sistemático e como ele se aplica à aplicação da TDF
