  ('cpiuris2025::c812cf2cd2257c7e57fcf0049a27fced', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Teoria do Diálogo das Fontes (TDF)', '## Teoria do Diálogo das Fontes (TDF)

A Teoria do Diálogo das Fontes busca garantir a Coerência Derivada entre diversas fontes legislativas, visando a Eficiência Funcional de suas disposições.

### Conceitos
- **Teoria do Diálogo das Fontes (TDF)**: Abordagem que busca garantir a coerência entre diversas fontes legislativas
- **Pluralismo Pós-Moderno**: Existência de fontes legislativas plúrimas, gerada por desenvolvimentos tecnológicos e massificação das relações
- **Coerência Derivada ou Restaurada**: Obtção da coerência entre diversas fontes legislativas para garantir a eficiência funcional de suas disposições
- **Eficiência Funcional**: Garantia de que as disposições das leis sejam aplicadas de forma eficaz e coordenada

### Referências legais
- Art. 2º da LINDB

### Dicas de prova
- Entenda a importância da TDF na aplicação do CDC
- Conheça o Pluralismo Pós-Moderno e sua relação com a TDF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º da LINDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:27:38.064900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=13", "doc_key": "c812cf2cd2257c7e57fcf0049a27fced"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a397efb648aa410997c107890bfa946e840db8c4e05f02a4d0f9bd114f6c7f37'),
  ('cpiuris2025::21b036f444666b97efc1ab278127eae3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC e Teoria da Defesa do Consumidor (TDF)', '## Princípios do CDC e Teoria da Defesa do Consumidor (TDF)

O texto destaca a importância dos princípios do CDC e a aplicação da TDF, que é baseada no art. 7º do CDC, para proteger os consumidores.

### Conceitos
- **Teoria da Defesa do Consumidor (TDF)**: teoria jurídica que busca proteger os direitos dos consumidores
- **Princípios do CDC**: princípios fundamentais do Código de Defesa do Consumidor
- **Tutela Coletiva**: proteção coletiva dos consumidores em relação a abusos no mercado de consumo
- **Distribuição do Ónus de Prova**: regras que determinam quem é responsável por provar uma alegação em um processo cível
- **Responsabilidades Decorrentes da Relação de Consumo**: obrigações e direitos dos consumidores e fornecedores em relação à relação de consumo
- **Teoria dos Contratos**: teoria jurídica que estuda a formação e o cumprimento das relações contratuais
- **Recursos Cíveis**: processos judiciais cíveis que envolvem disputas entre partes

### Referências legais
- Art. 7º, caput, do CDC

### Jurisprudência
- ADI n° 2.591/DF
- Súmula do STJ

### Dicas de prova
- Entenda a aplicação da TDF e seus princípios
- Conheça as regras de distribuição do ónus de prova em processos cíveis
- Aprenda sobre as responsabilidades decorrentes da relação de consumo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, caput, do CDC"], "jurisprudence": ["ADI n° 2.591/DF", "Súmula do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T01:28:44.142336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=14", "doc_key": "21b036f444666b97efc1ab278127eae3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dfd264477e98ee3a2bad23d92add1a306c05bdffedcf0562ec005efb0a16ae08'),
  ('cpiuris2025::e40f8a245dfaa4e724717298dc09466d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Diálogo das fontes no Direito do Consumidor', '## Diálogo das fontes no Direito do Consumidor

