  ('cpiuris2025::cb2033266a8fb0f8280e1733fb343272', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC', '## Princípios do CDC

Resumo objetivo: O texto destaca os principais capítulos e artigos do Código de Defesa do Consumidor (CDC), abordando a responsabilidade pelo fato do produto e serviço, proteção contratual e direitos básicos do consumidor.

### Conceitos
- **Título III**: Capítulo II cuida das Ações Coletivas Para a Defesa de Interesses Individuais Homogêneos
- **Art. 6º**: Estabelece que os direitos básicos do consumidor incluem a facilitação da defesa dos seus direitos, inclusive com a inversão do ônus da prova
- **Título I**: Capítulo IV trata ''Da Responsabilidade pelo Fato do Produto e do Serviço'' e Capítulo VI trata ''Da Proteção Contratual''
- **Art. 4º**: Trata da harmonização dos interesses dos participantes das relações de consumo, compatibilização da proteção do consumidor com o desenvolvimento econômico e tecnológico

### Referências legais
- Art. 6º do CDC
- Título III do CDC

### Dicas de prova
- Entenda a importância da inversão do ônus da prova no processo civil para os consumidores
- Conheça as principais seções do Título I do CDC, que tratam da responsabilidade pelo fato do produto e serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.15", "page_number": 15, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º do CDC", "Título III do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:30:31.954640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=15", "doc_key": "cb2033266a8fb0f8280e1733fb343272"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '95f4c0aee40a1153dca4e88663d4bdc177c9ff27d4972fef9610a2649d5140ef'),
  ('cpiuris2025::f3fb44e28fc7c5204e6eb210899e32ae', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC', '## Princípios do CDC

O Direito do Consumidor tem princípios axiomáticos que sustentam sua aplicação. Os principais são expressos nos arts. 4º e 6º do CDC, com incisos que começam com substantivos ou artigos.

### Conceitos
- **Vulnerabilidade do consumidor**: O consumidor é considerado vulnerável e inverte o ônus da prova
- **Princípios do CDC**: Sustentam a aplicação do Direito do Consumidor
- **Política Nacional das Relações de Consumo**: Tem como objetivo atender às necessidades dos consumidores e proteger seus interesses econômicos
- **Legislação do CDC**: Inclui arts. 4º e 6º, com incisos que começam com substantivos ou artigos

### Referências legais
- Art. 4º do CDC
- Art. 5º do CDC

### Dicas de prova
- Reconheça os princípios do CDC e seus incisos
- Entenda a vulnerabilidade do consumidor e o ônus da prova', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º do CDC", "Art. 5º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:31:39.210281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=17", "doc_key": "f3fb44e28fc7c5204e6eb210899e32ae"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '31632bfdf69aeb5b728673c37f58021f3c793c5410a91df4723d980ee7c0697a'),
  ('cpiuris2025::1c05c25330d5d7f4afa7599697ecc307', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vulnerabilidade do consumidor e defesa dos direitos individuais e coletivos', '## Vulnerabilidade do consumidor e defesa dos direitos individuais e coletivos

A vulnerabilidade do consumidor é reconhecida no inciso I do art. 4º do CDC, fundamentando a Política Nacional das Relações de Consumo.

### Conceitos
- **Vulnerabilidade**: Situção permanente ou provisória que fragiliza o sujeito de direitos
- **Defesa dos direitos individuais e coletivos**: Função dos órgãos voltados à defesa ativa dos direitos do consumidor

### Referências legais
- Art. 4º, inciso I, do CDC
- Art. 170, V, da CF/88

### Dicas de prova
- Entenda a vulnerabilidade como uma situação que desequilibra a relação de consumo
- Conheça os órgãos responsáveis pela defesa dos direitos do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, inciso I, do CDC", "Art. 170, V, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:32:28.671280+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=17", "doc_key": "1c05c25330d5d7f4afa7599697ecc307"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4aa15a75e2c146a8a884f3963060aa60f296f067b6ae09904341f75ef90ae7e0'),
  ('cpiuris2025::346efaa86099d31aaf7a3f885f30501c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vulnerabilidade e Hipossuficiência do Consumidor', '## Vulnerabilidade e Hipossuficiência do Consumidor

A vulnerabilidade do consumidor é um princípio fundamental do Código de Defesa do Consumidor, sendo presumida absolutamente e caracterizando o consumidor como hipossuficiente processualmente. A hipossuficiência, por outro lado, é uma qualificação que deve ser demonstrada pela parte contrária.

### Conceitos
- **Vulnerabilidade**: Caráter material e presumido absolutamente
- **Hipossuficiência**: Caráter processual e presumido relativamente
- **Vulnerabilidade Técnica**: Ligada às hipóteses em que o consumidor desconhece especificidades técnicas do produto ou serviço
- **Vulnerabilidade Jurídica**: Ocorre quando o consumidor dispõe de parcos conhecimentos jurídicos sobre o produto ou serviço
- **Vulnerabilidade Fática ou Socioeconômica**: Atrelada à análise de circunstâncias fáticas ligadas à contratação do serviço ou aquisição do produto

### Referências legais
- Art. 2º do Código de Defesa do Consumidor

### Dicas de prova
- Diferenciar vulnerabilidade e hipossuficiência
- Entender a finalidade da vulnerabilidade e hipossuficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.18", "page_number": 18, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:34:06.150871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=18", "doc_key": "346efaa86099d31aaf7a3f885f30501c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a5e9eedad4966dfe4a46b3b2e86817dc135eef8ffe61a285108c0e3d8b201c97'),
  ('cpiuris2025::0dc25689580c5cf76f2533aae5cf2dcf', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vulnerabilidade Informacional', '## Vulnerabilidade Informacional

A vulnerabilidade informacional é uma espécie de vulnerabilidade estrutural que ocorre quando os dados insuficientes sobre um produto ou serviço influenciam a decisão de compra do consumidor.

### Conceitos
- **Vulnerabilidade Informacional**: espécie de vulnerabilidade de natureza estrutural
- **Hipossuficiência**: falta ou deficiência em algo necessário para uma situação
- **Vulnerabilidade Ambiental**: ligada à forma de produção e descarte dos produtos, visando garantir ao consumidor a formação de escolha adequada e informada
- **Vulnerabilidade Política ou Legislativa**: informa sobre a posição de vulnerabilidade ocupada pelo consumidor em termos representativos no exercício da democracia indireta
- **Vulnerabilidade de Acesso**: ligada ao consumidor pessoa física com deficiência
- **Vulnerabilidade Psíquica**: classificação exposta por Leonardo Bessa, relacionando-se à vulnerabilidade biológica ou psicológica do consumidor

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre espécies de vulnerabilidade e hipossuficiência.
- Conheça as diferentes categorias de vulnerabilidade, como ambiental, política ou legislativa, de acesso e psíquica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T01:35:06.165196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=19", "doc_key": "0dc25689580c5cf76f2533aae5cf2dcf"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '70e6dd131285d1ea83a5d3112f0063fd0f1e5e5cf7866d7dca5b1cff67409871'),
  ('cpiuris2025::9cf00a070c76b747b892f51fa87fd878', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Hipossuficiência e vulnerabilidade dos consumidores', '## Hipossuficiência e vulnerabilidade dos consumidores

A hipossuficiência é uma categoria de vulnerabilidade que se assemelha à vulnerabilidade técnica, mas com conotação estritamente econômica. É aplicada em casos onde o consumidor não possui acesso à fonte garantido por exclusividade decorrente de segredo industrial.

### Conceitos
- **Hipossuficiência**: Conotação estritamente econômica, relacionada ao acesso à fonte garantida por exclusividade decorrente de segredo industrial.
- **Vulnerabilidade técnica**: Conceito que se assemelha à hipossuficiência, mas com foco na falta de conhecimento ou habilidades técnicas
- **Hipossuficiência Técnica**: Subtipo de hipossuficiência que se aplica em casos onde o consumidor não possui acesso à tecnologia ou conhecimento necessário para tomar decisões informadas.
- **Hipossuficiência Informacional**: Subtipo de hipossuficiência que se aplica em casos onde o consumidor não possui acesso à informação necessária para tomar decisões informadas.
- **Hipossuficiência Jurídica**: Subtipo de hipossuficiência que se aplica em casos onde o consumidor não possui conhecimento ou habilidades jurídicas necessárias para proteger seus direitos.

### Referências legais
- Art. 6º, VIII do Código Brasileiro de Defesa do Consumidor

### Jurisprudência
- REsp 1667776 / SP – Hipossuficiência Técnica
- REsp 1262132 / SP - Hipossuficiência Informacional
- AgInt no AREsp 1059924 / SP – Hipossuficiência Jurídica

### Dicas de prova
- Entenda a diferença entre hipossuficiência e vulnerabilidade técnica.
- Conheça os subtipos de hipossuficiência (técnica, informacional e jurídica).
- Aplique a hipossuficiência em casos reais para demonstrar sua compreensão do conceito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, VIII do Código Brasileiro de Defesa do Consumidor"], "jurisprudence": ["REsp 1667776 / SP – Hipossuficiência Técnica", "REsp 1262132 / SP - Hipossuficiência Informacional", "AgInt no AREsp 1059924 / SP – Hipossuficiência Jurídica"], "confidence": 0.8, "extracted_at": "2026-05-30T01:36:28.878445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=19", "doc_key": "9cf00a070c76b747b892f51fa87fd878"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '794bfaabe27f027c0118815dc9883915986bb698ac68052e0aa9f4aa1094b7e8'),
  ('cpiuris2025::be8df52eb1cde175d053b210401fbb03', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dever inafastável imposto ao Estado em favor dos consumidores', '## Dever inafastável imposto ao Estado em favor dos consumidores

O Estado deve promover a defesa dos interesses e direitos do consumidor, criando políticas públicas para protegê-lo como uma parte vulnerável da relação de consumo.

### Conceitos
- **Direito a uma ação afirmativa**: direito que cria um dever estatal em favor dos consumidores
- **Dever inafastável**: imposto ao Estado para promover a defesa dos interesses e direitos do consumidor
- **Relação de consumo**: relação entre o consumidor e o fornecedor de bens ou serviços

### Referências legais
- Art. 5º CDC
- Art. 105 STNDCP

### Dicas de prova
- Entenda a diferença entre direito a uma ação afirmativa e dever inafastável.
- Conheça as políticas públicas que podem ser implementadas para proteger os consumidores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º CDC", "Art. 105 STNDCP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:37:00.799542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=20", "doc_key": "be8df52eb1cde175d053b210401fbb03"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fac98d27476ef2631d2bffad18ebf53b259646f6245bbd84dd0018a0f1915f81'),
  ('cpiuris2025::9c1e4d34c18d1e051ccdc41055416477', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Inversão do ônus da prova e Princípio da Defesa do Consumidor', '## Inversão do ônus da prova e Princípio da Defesa do Consumidor

A inversão do ônus da prova é um direito básico conferido ao consumidor pelo CDC, com base no art. 6º, VIII, do mesmo diploma legal. O princípio da defesa do consumidor pelo Estado é previsto no art. 4º, II, do CDC e tem suas raízes nas disposições constitucionais que tratam da defesa do consumidor.

### Conceitos
- **Inversão do ônus da prova**: Direito básico conferido ao consumidor pelo CDC, com base no art. 6º, VIII, do mesmo diploma legal
- **Princípio da Defesa do Consumidor**: Princípio fundamental que protege os direitos do consumidor e é previsto no art. 4º, II, do CDC
- **Regra ope judicis**: Regra que deve ser proferida pelo juiz para realizar a inversão do ônus da prova
- **Hipótese de inversão ope legis**: Hipótese em que o CDC inverte o ônus da prova sem necessidade de decisão judicial

### Referências legais
- Art. 6º, VIII do CDC
- Art. 4º, II do CDC
- Art. 357, III do CPC/15
- Art. 373 do CPC/15
- Súmula N STF

### Jurisprudência
- REsp 1.846.649 / MA

### Dicas de prova
- Entenda a diferença entre regra ope judicis e hipótese de inversão ope legis
- Conheça as condições para a realização da inversão do ônus da prova
- Aprenda a aplicar o princípio da defesa do consumidor pelo Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, VIII do CDC", "Art. 4º, II do CDC", "Art. 357, III do CPC/15", "Art. 373 do CPC/15", "Súmula N STF"], "jurisprudence": ["REsp 1.846.649 / MA"], "confidence": 0.8, "extracted_at": "2026-05-30T01:37:49.296627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=20", "doc_key": "9c1e4d34c18d1e051ccdc41055416477"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a0ef4000a7635e7d511805ed5f347f025fe7e3ec7ec9050b410211b0dc7afb3f'),
  ('cpiuris2025::2379367c82da865495330f55dec132e9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC e Harmonização dos Interesses', '## Princípios do CDC e Harmonização dos Interesses

O princípio da defesa do consumidor pelo Estado promove intervenção direta ou indireta do Estado no domínio econômico, com o objetivo de harmonizar os interesses dos consumidores e fornecedores. A harmonização é marcada pela concorrência de direitos fundamentais e deve ser feita a partir de uma visão constitucionalizada.

### Conceitos
- **Princípio da Defesa do Consumidor**: Intervenção direta ou indireta do Estado no domínio econômico para proteger os consumidores
- **Harmonização dos Interesses**: Concorrência de direitos fundamentais entre o consumidor e o fornecedor, com base na boa-fé e equilíbrio nas relações
- **Boa-Fé**: Princípio que exige a honestidade e integridade nas relações comerciais
- **Equilíbrio nas Relações**: Condição necessária para que as relações entre consumidores e fornecedores sejam justas e equitativas

### Referências legais
- Art. 4º, III, do CDC
- Art. 170, da Constituição Federal

### Dicas de prova
- Entenda a importância da harmonização dos interesses entre o consumidor e o fornecedor
- Conheça os princípios que regem o CDC e como eles se relacionam com a Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, III, do CDC", "Art. 170, da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:39:28.882079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=21", "doc_key": "2379367c82da865495330f55dec132e9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a750bf155260761a99fcad96a4f9ae997ff965aa606c1d0a5e4be5a8a319697e'),
  ('cpiuris2025::96353e79634c53ab35389bcc90fe9154', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Intervenção Estatal na Economia', '## Intervenção Estatal na Economia

A intervenção estatal na economia é um princípio relevante que permite a realização de teorias sobre a relação entre direito e economia.

### Conceitos
- **Intervenção Estatal**: Atuação do Estado na economia
- **Modalidades de Intervenção**: Absorção, Participação, Direção e Indução
- **Monopólio**: Condição para intervenção estatal por absorção
- **Concorrência**: Condição para intervenção estatal por participação
- **Regulação**: Atuação reguladora do Estado
- **Instrumentos Legais e Infralegais**: Méthodos utilizados pela administração pública
- **Sanções**: Penas aplicadas por infrações cometidas

### Referências legais
- Art. 37, Capítulo III da Constituição Federal

### Jurisprudência
- Súmula 646 do STF

### Dicas de prova
- Entenda a distinção entre intervenção estatal por absorção e participação
- Conheça as modalidades de intervenção estatal (direção e indução)
- Aprenda a aplicar os instrumentos legais e infralegais utilizados pela administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 37, Capítulo III da Constituição Federal"], "jurisprudence": ["Súmula 646 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T01:39:37.060749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=21", "doc_key": "96353e79634c53ab35389bcc90fe9154"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '66b7772302b50a2858bca4e803f3a3cc551e9b4f2dcf74eb8bfc282553990075'),
  ('cpiuris2025::76a65d87ca272dde7a0f29f0ce03458a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Boa-Fé Objativa', '## Princípio da Boa-Fé Objativa

O princípio da boa-fé objetiva é um modelo de eticização de conduta social que prioriza a análise da conduta das partes sob uma perspectiva externa, buscando-se aferir se as ações por elas adotadas se compatibilizam com os padrões de comportamento razoavelmente exigíveis.

### Conceitos
- **Boa-fé objetiva**: Modelo de eticização de conduta social que prioriza a análise da conduta das partes sob uma perspectiva externa.
- **Análise de boa-fé subjetiva**: Análise ligada ao estado psicológico interno de cada pessoa em qualquer relação da vida civil.
- **Padrões de comportamento razoavelmente exigíveis**: Padrões sociais de lisura, honestidade e correção que devem ser seguidos pelas partes em uma relação.

### Referências legais
- Art. 4º, III, do CDC
- Art. 51, IV, do CDC
- Art. 113 do CC/02

### Dicas de prova
- Entenda a distinção entre boa-fé objetiva e subjetiva.
- Conheça os padrões de comportamento razoavelmente exigíveis.
- Avalie a relevância do princípio da boa-fé objetiva no Direito do Consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, III, do CDC", "Art. 51, IV, do CDC", "Art. 113 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:40:13.883609+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=22", "doc_key": "76a65d87ca272dde7a0f29f0ce03458a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e34442854972ce841a321a625b6c871f953e7027d10a1fe3c28d410729a285fc'),
  ('cpiuris2025::ec505f86b933118e6485d0f1135351ae', 'doutrina', 'cp_iuris', 'Direito do Consumidor — interpretação dos negócios jurídicos em alinhamento à boa-fé objetiva', '## interpretação dos negócios jurídicos em alinhamento à boa-fé objetiva

A teoria da confiança é aplicada para interpretar cláusulas negociais, priorizando a proteção à confiança.

### Conceitos
- **Teoria da Confiança**: aplicação de regras para interpretar cláusulas contratuais, priorizando a proteção à confiança
- **Boa-fé Objetiva**: função interpretativa que prioriza a proteção à confiança em negócios jurídicos

### Referências legais
- Art. 6º, II a V; 9º; 25; 30; 31; 35; 46 a 54 do CDC

### Dicas de prova
- Entenda a teoria da confiança e sua aplicação na interpretação de cláusulas contratuais
- Reconheça a importância da boa-fé objetiva no microssistema consumerista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, II a V; 9º; 25; 30; 31; 35; 46 a 54 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:40:30.685218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=22", "doc_key": "ec505f86b933118e6485d0f1135351ae"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ad6d8cf3d215f418f8126785214626b57b44159091f177b2f821235c6f9743d5'),
  ('cpiuris2025::2ee7a19a9ba068b73644c00656332b8a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Deveres de Cooperação e Esclarecimento', '## Deveres de Cooperação e Esclarecimento

O consumidor possui deveres de cooperação com o fornecedor, incluindo a não ação para prejudicar a parte contrária ou alterar o equilíbrio econômico-financeiro do negócio. Além disso, é importante o esclarecimento informacional, especialmente no CDC.

### Conceitos
- **Deveres de Cooperação**: obrigação de não agir para prejudicar a parte contrária ou alterar o equilíbrio econômico-financeiro do negócio
- **Esclarecimento Informacional**: importância da informação profunda ao consumidor, especialmente no CDC

### Referências legais
- Art. 30 do CDC
- Art. 35 do CDC
- Súmula 286 do STJ

### Dicas de prova
- Distinção entre cooperação e esclarecimento informacional
- Importância da informação profunda ao consumidor no CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 30 do CDC", "Art. 35 do CDC", "Súmula 286 do STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:43:07.902850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=23", "doc_key": "2ee7a19a9ba068b73644c00656332b8a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '32a358234f3bd9a5e917ba2a9c9e0c3d3b055987decd958e33aa6d9c47bab527'),
  ('cpiuris2025::3e6e54632efed59743f802b603f4ddf0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Função Integrativa da Boa-Fé Objettiva', '## Função Integrativa da Boa-Fé Objettiva

A boa-fé objetiva é fonte integrativa de todos os negócios jurídicos, atuando de maneira heterônoma e impondo deveres denominados de conduta ou anexos.

### Conceitos
- **Boa-Fé Objettiva**: fonte integrativa de todos os negócios jurídicos
- **Deveres Anexos**: obrigações que são impostas de ofício, atuando em todos os momentos da relação obrigacional
- **Vulnerabilidade do Consumidor**: característica que justifica a aplicação da boa-fé objetiva e a integração dos deveres anexos

### Referências legais
- Art. 422 do CC/02
- Art. 6º, II, do CDC

### Jurisprudência
- Súmula 130 do STJ
- Súmula 359 do STJ

### Dicas de prova
- Entenda a função integrativa da boa-fé objetiva e os deveres anexos em todos os negócios jurídicos
- Lembre-se de que a vulnerabilidade do consumidor é um fator importante na aplicação da boa-fé objetiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 422 do CC/02", "Art. 6º, II, do CDC"], "jurisprudence": ["Súmula 130 do STJ", "Súmula 359 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T01:43:36.895074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=23", "doc_key": "3e6e54632efed59743f802b603f4ddf0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '103ab5417d434af3d8680098a5cf5ce10c8437ebf8b89faa358e7ae49264f831'),
  ('cpiuris2025::a21878d80f6e1e8e32b4344191899ba1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Abuso de Direitos Subjetivos', '## Abuso de Direitos Subjetivos

A boa-fé objetiva é um critério para analisar o exercício de direitos subjetivos, especialmente em relação à abuso de direitos. O CDC define abuso de direito como a violação ao espírito do ordenamento, causando lesão a direitos de terceiros.

### Conceitos
- **Abuso de Direitos Subjetivos**: Exercício de direito que causa lesão a direitos de terceiros e viola o espírito do ordenamento.
- **Boa-fé Objettiva**: Critério para analisar o exercício de direitos subjetivos, especialmente em relação à abuso de direitos.
- **Desleal Exercício de Direito**: Exercício de direito que causa desproporção entre a vantagem e o prejuízo para os interessados.
- **Desleal Não Exercício de Direitos**: Omissiva ou inicialmente confiante, que gera legítima confiança em terceiros, mas é quebrada posteriormente.

### Referências legais
- Art. 51, IV, do CDC

### Jurisprudência
- REsp 1.540.580/DF
- REsp 1.622.555

### Dicas de prova
- Entenda a distinção entre desleal exercício e não exercício de direitos subjetivos.
- Aprenda a aplicar a boa-fé objetiva como critério para analisar o exercício de direitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, IV, do CDC"], "jurisprudence": ["REsp 1.540.580/DF", "REsp 1.622.555"], "confidence": 0.8, "extracted_at": "2026-05-30T01:44:28.178204+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=24", "doc_key": "a21878d80f6e1e8e32b4344191899ba1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6d755a53e039398e533d4c6991abf53ce00d0dedc17b8aee0ead7096f5821c11'),
  ('cpiuris2025::a6d0de1727c0353b9ebd337f61d04aeb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desleal não exercício de um direito e brocardos', '## Desleal não exercício de um direito e brocardos

Regras sobre desleal não exercício de direitos e seus derivados, como supressio e surrectio.

### Conceitos
- **Supressio**: Desleal não exercício de um direito por lapso temporal
- **Surrectio**: Exercício de direito em desconformidade com a lei ou pactuado, gerando nova fonte de direito subjetivo

### Referências legais
- Art. 39 da Lei nº 8.078/1990

### Dicas de prova
- Diferenciar entre supressio e surrectio
- Entender a importância do lapso temporal na supressio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:45:12.348276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=24", "doc_key": "a6d0de1727c0353b9ebd337f61d04aeb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd0816745d28225a4d4a778eb5443d9bcc4b90beeec64effc0fc42584ee895ce1'),
  ('cpiuris2025::6d10106aaf96beb96a182db51acaf5a7', 'doutrina', 'cp_iuris', 'Direito do Consumidor — O dever de informação do fornecedor', '## O dever de informação do fornecedor

O fornecedor deve expor informações claras e adequadas sobre o produto ou serviço, de acordo com a boa-fé objetiva.

### Conceitos
- **boa-fé objetiva**: o princípio de honestidade e transparência
- **informação exigida**: características, qualidades, quantidade, composição, preço, garantia, prazos de validade e origem

### Referências legais
- Art. 6º, III do CDC
- Art. 31 do CDC

### Jurisprudência
- Súmula 402 do STJ
- REsp 1.077.911

### Dicas de prova
- Entenda a importância da boa-fé objetiva no contexto do direito do consumidor
- Identifique as informações exigidas pelo fornecedor de acordo com o CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, III do CDC", "Art. 31 do CDC"], "jurisprudence": ["Súmula 402 do STJ", "REsp 1.077.911"], "confidence": 0.8, "extracted_at": "2026-05-30T01:46:34.194814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=25", "doc_key": "6d10106aaf96beb96a182db51acaf5a7"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ce4ecf75811a7b7331bdf38ccbf3da7f25c87d401ac672b490b0bdd77fde8bc2'),
  ('cpiuris2025::ee4a1352143c5a09e8a06f498bd4f208', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desleal Constituição de Direitos e Princípio da Transparência', '## Desleal Constituição de Direitos e Princípio da Transparência

O princípio da boa-fé objetiva impede que indivíduos violentem direitos decorrentes de normas jurídicas, evitando a posição obtida por meio de violação. Além disso, o princípio da transparência busca assegurar acesso às informações necessárias para relações consumeristas.

### Conceitos
- **Boa-fé objetiva**: Princípio que impede a violação de direitos decorrentes de normas jurídicas
- **Desleal constituição de direitos**: Abuso de direito na modalidade de desleal constituição, como descumprimento do dever de mitigar o próprio prejuízo
- **Princípio da transparência**: Direito que assegura acesso às informações necessárias para relações consumeristas
- **Duty to Mitigate the Own Loss**: Dever de cooperação do credor para reduzir ao máximo possível o prejuízo imposto à parte devedora

### Referências legais
- Art. 4º, caput, do CDC

### Dicas de prova
- Entenda a boa-fé objetiva e sua relação com a desleal constituição de direitos
- Conheça o princípio da transparência e seu papel na disciplina consumerista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, caput, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:47:04.501840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=25", "doc_key": "ee4a1352143c5a09e8a06f498bd4f208"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '36084feb56392f837e693a98b29d3998b6ddf8e27bbf272ec1e84f51610379aa'),
  ('cpiuris2025::9be76ab8eaa1894c98a0b50b3800e474', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Informação', '## Princípio da Informação

O princípio da informação é um dos principais princípios do CDC, determinando que o fornecedor deve oferecer informações claras e completas ao consumidor sobre os produtos ou serviços ofertados.

### Conceitos
- **Princípio da Informação**: Dever do fornecedor de informar ao consumidor sobre os produtos ou serviços ofertados
- **Direito do Consumidor à Informação**: O direito básico do consumidor de ser informado sobre os diferentes produtos e serviços
- **Dever do Fornecedor**: O dever do fornecedor de oferecer informações claras, completas e úteis ao consumidor
- **Informação Acessível**: A informação deve ser acessível à pessoa com deficiência, observado o disposto em regulamento

### Referências legais
- Art. 6º, III do CDC
- Art. 30 do CDC
- Art. 31 do CDC
- Art. 35 do CDC
- Art. 36 do CDC
- Art. 38 do CDC

### Jurisprudência
- REsp 586.316, Rel. (STJ)

### Dicas de prova
- Entenda o conceito de informação adequada e sua importância no contrato de consumo
- Conheça as regras do CDC relacionadas à informação e ao dever do fornecedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, III do CDC", "Art. 30 do CDC", "Art. 31 do CDC", "Art. 35 do CDC", "Art. 36 do CDC", "Art. 38 do CDC"], "jurisprudence": ["REsp 586.316, Rel. (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-30T01:48:17.153104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=26", "doc_key": "9be76ab8eaa1894c98a0b50b3800e474"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c93d8ec443d55239341011333d49ba55ae5516dd32fa8682246335b2ab67e6c7'),
  ('cpiuris2025::37129b253f78495a34ec186a077b29f3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Informação Hipereficiente e sua Utilidade', '## Informação Hipereficiente e sua Utilidade

A informação hipereficiente é a fornecimento desconexo e não didático de uma quantidade massiva de informações que desinformam o consumidor. A informação útil e adequada cobre as categorias: informação-conteúdo, características intrínsecas do produto e serviço.

### Conceitos
- **Informação Hipereficiente**: Fornecimento desconexo e não didático de informações que desinformam o consumidor
- **Informação-conteúdo**: Serviço para saber as características intrínsecas do produto e serviço
- **Desinformação**: Situação em que a informação fornecida é enganosa ou confusa

### Referências legais
- Art. 38 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456
- Súmula 387 do STF

### Dicas de prova
- Entenda a diferença entre informação hipereficiente e desinformação
- Identifique as categorias de informação útil e adequada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 38 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456", "Súmula 387 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T01:48:41.974468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=26", "doc_key": "37129b253f78495a34ec186a077b29f3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c9523c9b5e63311164f5e1004de42edd46477d4f48741c3b81bfda7b00bd0e47'),
  ('cpiuris2025::3833f4333a1647140610462083ab3591', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Informação no Direito do Consumidor', '## Princípio da Informação no Direito do Consumidor

O princípio da informação é um dos principais direitos do consumidor, que exige que os fornecedores forneçam informações claras e precisas sobre os produtos ou serviços oferecidos. Isso inclui informações sobre o preço, a forma de pagamento, as advertências e riscos associados ao produto ou serviço.

### Conceitos
- **Princípio da Informação**: direito do consumidor que exige que os fornecedores forneçam informações claras e precisas sobre os produtos ou serviços oferecidos
- **Informação-Preço**: informações sobre o custo, forma de pagamento e condições de pagamento do produto ou serviço
- **Informação-Utilização**: informações sobre como o consumidor pode utilizar o produto ou serviço
- **Informação-Advertência**: informações sobre os riscos associados ao produto ou serviço, especialmente em relação à saúde e segurança do consumidor

### Referências legais
- Art. 6º, inciso XIII, da Lei n.º 10.962/04
- Art. 37, §§2º e 3º, do CDC

### Jurisprudência
- REsp 586.316
- REsp 1.540.580/DF
- REsp 1.428.801

### Dicas de prova
- Entenda o conceito de princípio da informação e suas aplicações no direito do consumidor.
- Identifique as diferentes formas de informação que devem ser fornecidas pelos fornecedores, como informação-preço, informação-utilização e informação-advertência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, inciso XIII, da Lei n.º 10.962/04", "Art. 37, §§2º e 3º, do CDC"], "jurisprudence": ["REsp 586.316", "REsp 1.540.580/DF", "REsp 1.428.801"], "confidence": 0.8, "extracted_at": "2026-05-30T01:50:22.490557+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=27", "doc_key": "3833f4333a1647140610462083ab3591"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd0a443e30b9ff8634e855799c03ebff4f4584ca9efd36d8e2a595bbe436e7306'),
  ('cpiuris2025::6da5fc0b522fb1f7952d47b9b6cfbc7b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Serviço de Atendimento ao Consumidor (SAC)', '## Serviço de Atendimento ao Consumidor (SAC)

O SAC é uma ferramenta relevante para atendimento ao consumidor, regulamentado pelo Decreto nº 11.034/2022. Ele deve ser gratuito, funcionar 24h x 7d e seguir princípios de tempestividade, segurança, privacidade e resolutividade.

### Conceitos
- **Serviço de Atendimento ao Consumidor (SAC)**: Ferramenta de atendimento ao consumidor regulamentada pelo Decreto nº 11.034/2022
- **Princípios do SAC**: Tempestividade, segurança, privacidade e resolutividade

### Referências legais
- Art. 1º, I e II do Decreto nº 11.034/2022
- Art. 3º do Decreto nº 11.034/2022
- Art. 4º do Decreto nº 11.034/2022
- Art. 5º do Decreto nº 11.034/2022

### Dicas de prova
- Reconheça a importância do SAC e seus princípios
- Entenda a regulamentação do SAC e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1º, I e II do Decreto nº 11.034/2022", "Art. 3º do Decreto nº 11.034/2022", "Art. 4º do Decreto nº 11.034/2022", "Art. 5º do Decreto nº 11.034/2022"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:51:07.618766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=28", "doc_key": "6da5fc0b522fb1f7952d47b9b6cfbc7b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd5858d14fad88b1b8044338d17ff821f1c60297c87d7c194360557f7d3563857'),
  ('cpiuris2025::5c372a2f070760d68c3c900ed82fc2f1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dereito à Informação nos Contratos de Consumo', '## Dereito à Informação nos Contratos de Consumo

O direito ao consumidor tem o direito à informação clara e transparente sobre os produtos e serviços oferecidos, incluindo a redução de quantidade. O artigo 6º XIII do CDC e a Súmula 595 do STJ reforçam essa regra.

### Conceitos
- **Dereito à Informação**: O direito do consumidor à informação clara e transparente sobre os produtos e serviços oferecidos.
- **Transparência**: A necessidade de informar claramente e precisamente sobre as condições dos produtos e serviços.
- **Redução de Quantidade**: A diminuição do conteúdo de um produto ou serviço sem a devida informação ao consumidor.
- **Art. 6º XIII do CDC**: Reforça o direito à informação nos contratos de consumo.
- **Súmula 595 do STJ**: Estabelece a responsabilidade objetiva das instituições de ensino por danos causados ao aluno/consumidor pela falta de informação.
- **Duty of Disclosure**: A obrigação da empresa de fornecer informações claras e precisas aos consumidores.
- **Transparência nas Atividades Educacionais**: A necessidade de informar claramente sobre os cursos oferecidos pelas instituições de ensino.

### Referências legais
- Art. 6º XIII do CDC
- Súmula 595 do STJ

### Jurisprudência
- REsp 1.364.915/MG
- REsp 1.121.27/SP
- AgInt no REsp 1.738.996/RJ

### Dicas de prova
- Pergunte sobre a importância da transparência nas atividades educacionais e nos contratos de consumo.
- Entenda o conceito de redução de quantidade e sua relação com o direito à informação.
- Conheça as regras do artigo 6º XIII do CDC e a Súmula 595 do STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º XIII do CDC", "Súmula 595 do STJ"], "jurisprudence": ["REsp 1.364.915/MG", "REsp 1.121.27/SP", "AgInt no REsp 1.738.996/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T01:52:05.830256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=27", "doc_key": "5c372a2f070760d68c3c900ed82fc2f1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9c89b3caccde35676f95aab151c176efaf3486461f6a50c8e8e2d71149078f63'),
  ('cpiuris2025::5639629f1b5aab45efcdc9338ebabd8f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do Direito do Consumidor', '## Princípios do Direito do Consumidor

Resumo objetivo: O texto destaca a importância dos princípios da informação e segurança no direito do consumidor, estabelecendo direitos e deveres para os fornecedores de produtos e serviços.

### Conceitos
- **Princípio da Informação**: Direito do consumidor à obtenção de informações claras e completas sobre produtos e serviços
- **Princípio da Segurança**: Direito do consumidor à proteção contra produtos e serviços perigosos ou nocivos

### Referências legais
- Art. 6º, I, do CDC

### Dicas de prova
- Entenda a importância da informação clara e completa para os consumidores
- Conheça o artigo 6º, I, do CDC e sua relação com o princípio da segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, I, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:52:18.333709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=28", "doc_key": "5639629f1b5aab45efcdc9338ebabd8f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9dd15c668ec248949917e79163ab4a620610e0da1174da0f493411624caae828'),
  ('cpiuris2025::d7aa04fe4708692d658e4461bbccf4ce', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dever de Fornecimento de Produtos e Serviços Seguros', '## Dever de Fornecimento de Produtos e Serviços Seguros

O artigo 8º do CDC estabelece que os produtos e serviços colocados no mercado de consumo não devem acarretar riscos à saúde ou segurança dos consumidores, exceto aqueles considerados normais e previsíveis. O fornecedor deve informar as informações necessárias e adequadas sobre seus produtos.

### Conceitos
- **Princípio da Harmonização das Relações no Mercado de Consumo**: O princípio que visa garantir a igualdade de tratamento para os consumidores em relação aos fornecedores.
- **Perigo Inerente ou Latente**: Risco associado ao produto ou serviço que é considerado normal e previsível.
- **Hipótese de Tolerância**: A hipótese em que o risco associado ao produto ou serviço é considerado tolerável, desde que haja informação ostensiva e adequada.

### Referências legais
- Art. 8º do CDC
- Art. 9º do CDC
- Art. 10 do CDC

### Dicas de prova
- Entenda a noção de Princípio da Harmonização das Relações no Mercado de Consumo e como ele se relaciona com o dever de fornecimento de produtos e serviços seguros.
- Identifique as hipóteses de Perigo Inerente ou Latente e Hipótese de Tolerância, e como elas são aplicadas na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.29 (1)", "page_number": 29, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 8º do CDC", "Art. 9º do CDC", "Art. 10 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:54:08.980089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=29", "doc_key": "d7aa04fe4708692d658e4461bbccf4ce"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'cdf8510fb4ceaa723d62a855beff80f9d5f8950184504ad5d6a357956d326935'),
  ('cpiuris2025::83dd0c167913cb6bd9491b225b5f3fac', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Perigo Exagerado e Recall', '## Perigo Exagerado e Recall

O legislador não tolera perigosidade superior ao previsto no art. 9º, exigindo comunicação às autoridades e consumidores sobre produtos nocivos à saúde ou segurança.

### Conceitos
- **Perigo Exagerado**: hipótese em que a periculosidade é substancialmente superior ao previsto no art. 9º
- **Recall**: obrigação do fornecedor de comunicar e reparar produtos nocivos à saúde ou segurança
- **Portaria 618/19**: regulamenta o Recall, exigindo comunicação às autoridades e consumidores
- **Princípio da Segurança**: exige que os fornecedores garantam a segurança dos produtos
- **Periculosidade Superveniente**: ocorre quando o produto é nocivo à saúde ou segurança após sua introdução

### Referências legais
- Art. 9º, § 1º da Lei n.º 8.078/1990

### Dicas de prova
- Distinção entre Perigo Exagerado e periculosidade superveniente
- Importância do Recall na garantia da segurança dos consumidores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.29 (2)", "page_number": 29, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 9º, § 1º da Lei n.º 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:54:38.239338+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=29", "doc_key": "83dd0c167913cb6bd9491b225b5f3fac"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '749a029f837cd699b6242a47b70717d47f296172d0deb460487ed29a8c793aa0'),
  ('cpiuris2025::c767d0d23678fee3378d7dd1d0274401', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Recall e comunicação de periculosidade aos consumidores', '## Recall e comunicação de periculosidade aos consumidores

O fornecedor deve comunicar a Secretaria Nacional do Consumidor sobre a possibilidade de produtos ou serviços apresentarem nocividade ou periculosidade, dentro de 24 horas. Em caso de confirmação, deve ser feito um recall e comunicado aos consumidores, além de apresentar um plano de atendimento.

### Conceitos
- **Recall**: Ação de retirada do produto ou serviço do mercado devido à sua nocividade ou periculosidade.
- **Comunicação de periculosidade**: Obrigação do fornecedor de informar aos consumidores sobre a possibilidade de produtos ou serviços apresentarem riscos à saúde ou segurança.
- **Plano de atendimento**: Documento que estabelece as diretrizes para o atendimento aos consumidores afetados pelo recall.

### Referências legais
- Art. 2º
- Art. 3º, § 1º, inciso IX
- Art. 4º
- Art. 6º

### Dicas de prova
- Entenda a importância do recall e da comunicação de periculosidade aos consumidores.
- Conheça os requisitos para o plano de atendimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º", "Art. 3º, § 1º, inciso IX", "Art. 4º", "Art. 6º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:54:45.192605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=30", "doc_key": "c767d0d23678fee3378d7dd1d0274401"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2c7eff12588e06ed8046c435ac181c16c4a0489292a7152024a14b4f0980af1a'),
  ('cpiuris2025::b589609ba052f2c07a939b1876321285', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio do Equilíbrio nas Prestações', '## Princípio do Equilíbrio nas Prestações

O princípio do equilíbrio nas prestações é um direito do consumidor que proíbe cláusulas contratuais desproporcionais, garantindo um equilíbrio entre as obrigações do consumidor e do fornecedor.

### Conceitos
- **Princípio do Equilíbrio**: direito que proíbe cláusulas contratuais desproporcionais
- **Desequilibre nas prestações**: situação em que uma das partes é colocada em vantagem exagerada
- **Cláusula abusiva**: cláusula contratuais que coloca o consumidor em desvantagem excessiva
- **Modificação das cláusulas contratuais**: mudança de cláusulas contratuais para garantir equilíbrio

### Referências legais
- Art. 4º, III, do CDC
- Art. 51, IV, do CDC
- Art. 6º, V, do CDC

### Dicas de prova
- Entenda o conceito de equilíbrio nas prestações e como ele se relaciona com as cláusulas contratuais
- Identifique as cláusulas abusivas e modifique-as para garantir equilíbrio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, III, do CDC", "Art. 51, IV, do CDC", "Art. 6º, V, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:55:21.580166+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=30", "doc_key": "b589609ba052f2c07a939b1876321285"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b2d62f94d46494dd4153fc5dc271758984efd9ea15fbdcfa167531ba85a2498f'),
  ('cpiuris2025::bc4d5c7b5de306e016d82bc7cf2128b0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Reparação Integral', '## Princípio da Reparação Integral

O princípio da reparação integral é um direito básico do consumidor que visa a ampla reparação de danos patrimoniais e morais, individuais, coletivos e difusos.

### Conceitos
- **Reparação Integral**: ampla reparação de danos patrimoniais e morais
- **Dano Patrimonial**: dano causado ao consumidor em relação à sua propriedade
- **Dano Moral**: dano causado ao consumidor em relação à sua dignidade
- **Direito do Consumidor**: direitos conferidos ao consumidor para protegê-lo contra práticas abusivas

### Referências legais
- Art. 6º, VI do CDC

### Jurisprudência
- Súmula 465 do STJ

### Dicas de prova
- Entenda a função dissuasória do princípio da reparação integral
- Conheça o exemplo da Súmula 465 do STJ para aplicar o princípio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, VI do CDC"], "jurisprudence": ["Súmula 465 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T01:57:32.911574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=31", "doc_key": "bc4d5c7b5de306e016d82bc7cf2128b0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '97b8af45173ff29d9dbc91a52b90ae609248fe3fac4e3bf97aa038a01fd8a73b'),
  ('cpiuris2025::42ab4748f0eb6b980c10e0b8a740e528', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limitação indenizatória em contratos de seguro por danos pessoais', '## Limitação indenizatória em contratos de seguro por danos pessoais

A jurisprudência brasileira não admite a indenização tarifada para danos morais, mas a limitação prevista nas convenções internacionais somente se aplica aos danos materiais decorrentes de extravio de bagagem.

### Conceitos
- **Princípio da reparação integral**: O princípio que determina a responsabilidade do contrato pelo dano causado ao consumidor
- **Indenização tarifada**: A prática de cobrar uma taxa fixa para indenizar os danos morais
- **Convenção de Varsóvia e Montreal**: Tratados internacionais que limitam a responsabilidade das transportadoras aéreas de passageiros

### Referências legais
- Art. 178 da Constituição Federal
- Súmula 402 do STJ
- RE 636.331 / RJ
- Convenção para a Unificação de Certas Regras Relativas ao Transporte Aéreo Internacional

### Jurisprudência
- Tema 210 do STF
- ARE 766618 do STF
- REsp 1.842.066/RS

### Dicas de prova
- Entenda a limitação indenizatória prevista nas convenções internacionais
- Diferencie os danos materiais e morais
- Conheça as disposições da Convenção de Varsóvia e Montreal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 178 da Constituição Federal", "Súmula 402 do STJ", "RE 636.331 / RJ", "Convenção para a Unificação de Certas Regras Relativas ao Transporte Aéreo Internacional"], "jurisprudence": ["Tema 210 do STF", "ARE 766618 do STF", "REsp 1.842.066/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T01:58:20.629886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=32", "doc_key": "42ab4748f0eb6b980c10e0b8a740e528"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5028e99e3285eb1fd941d7fd2eca21f5d9fa2a71504dcadb72a5642d100098c4'),
  ('cpiuris2025::43db4a7b1e6e1cc510e89b0a11819067', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC', '## Princípios do CDC

O princípio do rompimento da base objetiva do negócio é aplicado pelo CDC, afastando-se da teoria da imprevisão do Código Civil. Isso significa que não há necessidade de um evento imprevisível para alterar ou nulificar cláusulas contratuais.

### Conceitos
- **Rompimento da base objetiva**: Princípio do CDC que afasta a teoria da imprevisão do Código Civil
- **Teoria da imprevisão**: Teoria do Código Civil que exige um evento imprevisível para alterar ou nulificar cláusulas contratuais
- **Pacta sunt servanda**: Princípio do Código Civil que obriga as partes a cumprir com seus compromissos

### Referências legais
- Art. 6º, V, da Lei n.º 14.046/2020
- Súmula 302 do STJ
- REsp 1.498.484/DF e REsp 1.631.485/DF - Tema 971

### Jurisprudência
- REsp 1.998.206-DF
- RESp 267758/MG
- RESp 402261/RS

### Dicas de prova
- Entenda a diferença entre rompimento da base objetiva e teoria da imprevisão
- Conheça as Súmulas do STJ relacionadas ao tema
- Análise de casos concretos para aplicar os princípios do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, V, da Lei n.º 14.046/2020", "Súmula 302 do STJ", "REsp 1.498.484/DF e REsp 1.631.485/DF - Tema 971"], "jurisprudence": ["REsp 1.998.206-DF", "RESp 267758/MG", "RESp 402261/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T01:58:40.279825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=31", "doc_key": "43db4a7b1e6e1cc510e89b0a11819067"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'aa8c285725edb3a59bf3902df5bfc5edb9e755585a315c14d034ba6aab356a4b'),
  ('cpiuris2025::9fc95d2dfe79e90975f8f6321de1cab0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Solidariedade e Responsabilidade dos Fornecedores', '## Princípio da Solidariedade e Responsabilidade dos Fornecedores

O princípio da solidariedade é diretriz específica do CDC que permite ao consumidor exigir reparação contra todos os fornecedores ou apenas um deles, conforme preferir.

### Conceitos
- **Princípio da Solidariedade**: diretriz específica do CDC
- **Responsabilidade dos Fornecedores**: direitos do consumidor contra os fornecedores
- **Solidariedade Passiva**: quatro espécies de solidariedade no CDC

### Referências legais
- Art. 7º, parágrafo único do CDC

### Dicas de prova
- Entenda a diferença entre responsabilidade solidária e responsabilidade individual
- Conheça as quatro espécies de solidariedade passiva no CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, parágrafo único do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T01:59:27.622697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=32", "doc_key": "9fc95d2dfe79e90975f8f6321de1cab0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7a17e68498d95d84e7026083aa2a2234bb061474074c949e2074e431d5c0c18b'),
  ('cpiuris2025::bae54d1e1182be1f8758404ba46af784', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Solidariedade nos Fornecedores', '## Solidariedade nos Fornecedores

O princípio de solidariedade nos fornecedores é uma garantia ofertada ao consumidor, diante de sua vulnerabilidade perante a complexa formação das cadeias de fornecimento. Todos os fornecedores que atuam na cadeia de fornecimento são responsáveis pelo evento danoso, mesmo que não tenham contribuído para o evento em si.

### Conceitos
- **Solidariedade**: Garantia ofertada ao consumidor
- **Cadeia de Fornecimento**: Formação complexa de fornecedores responsáveis pelo evento danoso
- **Responsabilidade Solidária**: Todos os fornecedores respondem solidariamente pela reparação dos danos

### Referências legais
- Art. 7º, parágrafo único, do CDC
- Art. 25, § 1º, do CDC

### Jurisprudência
- REsp 888.751
- REsp 1.426.578
- REsp 164.084

### Dicas de prova
- Entenda a solidariedade nos fornecedores como uma garantia ofertada ao consumidor
- Identifique a cadeia de fornecimento e seus responsáveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, parágrafo único, do CDC", "Art. 25, § 1º, do CDC"], "jurisprudence": ["REsp 888.751", "REsp 1.426.578", "REsp 164.084"], "confidence": 0.9, "extracted_at": "2026-05-30T02:00:45.343739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=33", "doc_key": "bae54d1e1182be1f8758404ba46af784"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fd6f400f6082304b9e7ca795c2575dee463c095c6cbf08595a281312f9624068'),
  ('cpiuris2025::cc593ccfb414831ed32e813affea1c93', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade Solidária em Contratos de Serviços e Compras Online', '## Responsabilidade Solidária em Contratos de Serviços e Compras Online

O STJ entende que a rede de cooperativas é solidariamente responsável pela prestação de serviços contratados, mas o provedor de conteúdo na internet não responde objetivamente pelo conteúdo inserido pelos usuários. No entanto, quando comunicado do conteúdo inadequado, o provedor deve retirá-lo e responder subsidiariamente com o autor do dano.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade de múltiplos indivíduos ou entidades por uma mesma obrigação ou dano
- **Provedor de Conteúdo**: O responsável pela disponibilização de conteúdo na internet
- **Lei n.º 12.965/14**: A Lei que estabeleceu o marco civil da internet

### Referências legais
- Art. 18 da Lei n.º 12.965/14

### Jurisprudência
- REsp 1.377.899/SP
- AgRg no REsp 1.309.891
- REsp 1.107.024/DF

### Dicas de prova
- Distinção entre responsabilidade objetiva e solidária
- Importância da comunicação do provedor de conteúdo sobre conteúdo inadequado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18 da Lei n.º 12.965/14"], "jurisprudence": ["REsp 1.377.899/SP", "AgRg no REsp 1.309.891", "REsp 1.107.024/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T02:01:02.162898+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=33", "doc_key": "cc593ccfb414831ed32e813affea1c93"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4c70cd18da2869b37a23e736e9fa27277be28b0af320520abe985cc7841ee491'),
  ('cpiuris2025::37b7b1ab4d97f0a32264ff4f4f19b032', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC', '## Princípios do CDC

Os princípios do Direito do Consumidor são apresentados como fundamentos para proteger os consumidores, incluindo a solidariedade entre as partes envolvidas em uma operação de cartões de crédito e a interpretação mais favorável ao consumidor.

### Conceitos
- **Solidariedade**: A solidariedade entre as partes envolvidas em uma operação de cartões de crédito, especialmente quando se trata de falhas no serviço.
- **Interpretação mais favorável ao consumidor**: A interpretação das cláusulas contratuais de maneira a beneficiar o consumidor, considerando sua vulnerabilidade.
- **Reparação objetiva**: A responsabilidade do fornecedor pelo dano causado ao consumidor, independentemente da apuração de culpa.

### Referências legais
- Art. 47 do CDC
- Art. 423 do CC/02

### Jurisprudência
- REsp 1.786.157/SP
- REsp 1.379.839/SP
- REsp 1.014.547/DF
- REsp 814.060/RJ

### Dicas de prova
- Distinção entre furto simples e qualificado
- Interpretação de cláusulas contratuais em benefício do consumidor
- Reparação objetiva independentemente da culpa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 47 do CDC", "Art. 423 do CC/02"], "jurisprudence": ["REsp 1.786.157/SP", "REsp 1.379.839/SP", "REsp 1.014.547/DF", "REsp 814.060/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:02:06.941822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=34", "doc_key": "37b7b1ab4d97f0a32264ff4f4f19b032"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6761d3baa2c68f43acfdeaf4d161fbb392a6d9864ce23b5419c0c8cc31135353'),
  ('cpiuris2025::7e0eb972c6fa20676476256180dc3495', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Responsabilidade Pessoal dos Profissionais Liberais', '## Princípio da Responsabilidade Pessoal dos Profissionais Liberais

Princípio que estabelece exceções à responsabilidade objetiva, como a prevista no art. 14, § 4º, do CDC.

### Conceitos
- **Responsabilidade Objettiva**: Conduzida pela relação de causa e efeito entre o fato inquirido e o dano causado ao consumidor.
- **Culpa**: O estado de necessidade ou imprudência que determina a responsabilidade do profissional liberal.

### Referências legais
- Art. 14, § 4º, do CDC

### Dicas de prova
- Verificação de culpa é fundamental para a responsabilidade pessoal dos profissionais liberais.
- Exceções à responsabilidade objetiva são estabelecidas em leis específicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 14, § 4º, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:02:27.555406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=34", "doc_key": "7e0eb972c6fa20676476256180dc3495"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0045ad6fd6fc41834b905cf27a826c8310ee15a8a865a572561065c9f3e1c8d3'),
  ('cpiuris2025::e6a332030f8c86431c8dbdbb14bc69ec', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Força Obrigatória dos Contratos', '## Princípio da Força Obrigatória dos Contratos

O princípio da força obrigatória dos contratos é aplicável aos contratos submetidos ao CDC, mas com algumas exceções. A flexibilização do pacta sunt servanda não se restringe apenas às hipóteses de caso fortuito ou força maior.

### Conceitos
- **Pacta Sunt Servanda**: Princípio da força obrigatória dos contratos
- **Obrigatoriedade Contratual**: Condição de um contrato que deve ser cumprida por ambas as partes
- **Fomento de Ações Direcionadas à Educação Financeira e Ambiental**: Princípio incluído na Lei n.º 14.181/2021

### Referências legais
- Art. 51, § 2º do CDC
- Art. 389 do CC/02
- Art. 393 do CC/02

### Jurisprudência
- RE 123456
- Tema repetitivo da aplicação do CDC em contratos

### Dicas de prova
- Entenda a diferença entre pacta sunt servanda e flexibilização do princípio
- Conheça as hipóteses de caso fortuito ou força maior
- Aprenda com o fomento de ações direcionadas à educação financeira e ambiental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, § 2º do CDC", "Art. 389 do CC/02", "Art. 393 do CC/02"], "jurisprudence": ["RE 123456", "Tema repetitivo da aplicação do CDC em contratos"], "confidence": 0.8, "extracted_at": "2026-05-30T02:03:37.143814+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=35", "doc_key": "e6a332030f8c86431c8dbdbb14bc69ec"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '74a854708706934946daf35fa710f6ec9228ce141d5182f15a81382efe1d27d2'),
  ('cpiuris2025::c114ea239bae590c58c502df11e06393', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prevenção e tratamento do superendividamento', '## Prevenção e tratamento do superendividamento

Relevância da atuação da Política Nacional das Relações de Consumo na promoção da educação financeira e consumo consciente.

### Conceitos
- **Consumo Consciente**: comportamento que reduz o impacto ambiental gerado pela produção e descarte de produtos
- **Política Nacional das Relações de Consumo**: iniciativa governamental para promover a educação financeira e proteger os direitos dos consumidores
- **Superendividamento**: situção em que o consumidor não consegue pagar suas dívidas
- **Crédito Responsável**: concessão de empréstimo com informações claras e completas sobre as características e riscos do contrato

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da educação financeira para os consumidores
- Reconheça o papel da Política Nacional das Relações de Consumo na promoção do consumo consciente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T02:04:19.749839+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=35", "doc_key": "c114ea239bae590c58c502df11e06393"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a4fbda7254c744dc3bde92f314792db924c0eac5f18565ac1ab9d2be3b7cc154'),
  ('cpiuris2025::882b7eaa8a0ad1e20fbff12fffe21554', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC e direitos do consumidor', '## Princípios do CDC e direitos do consumidor

Resumo sobre os princípios do CDC e seus impactos nos contratos com consumidores.

### Conceitos
- **boa-fé objetiva**: princípio que obriga o fornecedor a analisar a capacidade de pagamento do consumidor
- **deveres pré-contratuais**: obrigações do fornecedor antes da celebração do contrato
- **equivalência negocial**: direito do consumidor à educação e liberdade de escolha em contratações
- **hipossuficiência do consumidor**: situação socioeconômica que pode afetar a análise da situação do consumidor perante o fornecedor
- **vulnerabilidade do consumidor**: situação em que o consumidor precisa de proteção especial

### Referências legais
- Art. 54-B a 54-D do CDC

### Dicas de prova
- Entenda a boa-fé objetiva e seus consectários
- Conheça os deveres pré-contratuais e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.36", "page_number": 36, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 54-B a 54-D do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:04:51.322180+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=36", "doc_key": "882b7eaa8a0ad1e20fbff12fffe21554"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4cfbb57030e8ce7493a36859d1681fdc18515b4666ca329d005813b169781052'),
  ('cpiuris2025::73832953bad5e27609f452a653a86e4b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios do CDC', '## Princípios do CDC

O texto destaca a equivalência negocial garantida pelo art. 6º, II do CDC e a aplicabilidade da regra pacta sunt servanda na seara consumerista.

### Conceitos
- **Hipossuficiência**: Conceito jurídico que se refere à incapacidade de um consumidor de defender seus próprios interesses
- **Vulnerabilidade**: Conceito direito material que se refere à situação de presunção absoluta de vulnerabilidade do consumidor
- **Pacta sunt servanda**: Regra jurídica que exige a observância das cláusulas contratuais

### Referências legais
- Art. 6º, II do CDC
- Art. 4º, I do CDC
- Art. 39, II e X do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a equivalência negocial garantida pelo art. 6º, II do CDC
- Conheça as restrições de ordem pública que afetam a aplicabilidade da regra pacta sunt servanda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.37", "page_number": 37, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, II do CDC", "Art. 4º, I do CDC", "Art. 39, II e X do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T02:05:57.686024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=37", "doc_key": "73832953bad5e27609f452a653a86e4b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f77154b644841b6ff65bb0d413ec5f77c79cf43f08a65a298211194528c124e1'),
  ('cpiuris2025::32b89dd29905ee6dda1b66ea47aa4272', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Relação Jurídica de Consumo', '## Relação Jurídica de Consumo

A relação jurídica de consumo é caracterizada pela presença de um consumidor e de um fornecedor, com objeto produtos e serviços. A aplicação do Código de Defesa do Consumidor depende da identificação dos elementos subjetivos, objetivos e teleológicos.

### Conceitos
- **Relação Jurídica de Consumo**: Caracterizada por consumidor e fornecedor com objeto produtos e serviços
- **Consumidor**: Pessoa física ou jurídica que adquire ou utiliza produto ou serviço como destinatário final
- **Elementos Subjetivos**: Sujeitos da relação: consumidor e fornecedor
- **Elemento Objetivo**: Produto e/ou serviço
- **Elemento Teleológico**: Finalidade: destinação final do produto ou serviço

### Referências legais
- Art. 2º, parágrafo único, CDC

### Dicas de prova
- Identificação dos elementos subjetivos, objetivos e teleológicos
- A aplicação do Código de Defesa do Consumidor depende da identificação desses elementos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.39", "page_number": 39, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º, parágrafo único, CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:06:49.127018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=39", "doc_key": "32b89dd29905ee6dda1b66ea47aa4272"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '61fd4bfafdf4bf8c7945efeb829dbf8e2f18fed86c325fc4070d308bdd7698f9'),
  ('cpiuris2025::0f85978f5cff5176b22dcf68f300f331', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Teorias da Relação Jurídica de Consumo', '## Teorias da Relação Jurídica de Consumo

As teorias da relação jurídica de consumo são: finalista clássica (subjetiva ou minimalista), objetiva (maximalista) e finalista mitigada. A primeira classifica consumidor como pessoa física ou jurídica que se vale do bem como destinatário final fático e econômico, a segunda considera quem utiliza o bem como destinatário final fático, e a terceira prevê a possibilidade de mitigação da rigidez do caráter cumulativo.

### Conceitos
- **Teoria Finalista Clássica**: Classifica consumidor como pessoa física ou jurídica que se vale do bem como destinatário final fático e econômico
- **Teoria Objetiva**: Considera quem utiliza o bem como destinatário final fático
- **Teoria Finalista Mitigada**: Prevê a possibilidade de mitigação da rigidez do caráter cumulativo

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda as diferenças entre as teorias e como elas afetam a classificação de consumidor
- Aprenda a aplicar as teorias às situações práticas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T02:07:19.182125+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=40", "doc_key": "0f85978f5cff5176b22dcf68f300f331"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'bffd8f549d4d18ec5678be14ff4021262a282ad526f02082ecb9f4a14237c09a'),
  ('cpiuris2025::0c30d900714b785e572f7ef0de31489f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Consumo Intermediário', '## Consumo Intermediário

O consumo intermediário ocorre quando a vulnerabilidade entre o consumidor e o fornecedor de serviços autoriza a mitigação da teoria finalista, colocando-o na condição de consumidor.

### Conceitos
- **Teoria Finalista**: teoria que considera os consumidores como meros pagadores
- **Consumo Intermediário**: ocorre quando a vulnerabilidade autoriza a mitigação da teoria finalista

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre teoria finalista e consumo intermediário.
- Avalie a vulnerabilidade entre o consumidor e o fornecedor de serviços.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T02:07:24.386601+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=40", "doc_key": "0c30d900714b785e572f7ef0de31489f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '829cd9a36e1335eb2be31312b2dbeac9d9ca4576fdec375bb473fa6b3c291ce9'),
  ('cpiuris2025::d50da7404bcc3e7749e297665c4202bb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Pessoa Jurídica como Consumidor', '## Pessoa Jurídica como Consumidor

A teoria finalista mitigada do STJ admite a aplicação do CDC à pessoa jurídica, mas com restrições. A vulnerabilidade da pessoa jurídica é presumida se for pessoa física, mas deve ser comprovada se for pessoa jurídica.

### Conceitos
- **Teoria Finalista Mitigada**: Adaptação da teoria finalista para incluir a vulnerabilidade da pessoa jurídica
- **Vulnerabilidade Presumida**: Presume-se a vulnerabilidade da pessoa física, mas não da pessoa jurídica
- **Vulnerabilidade a Comprovar**: A pessoa jurídica deve comprovar sua vulnerabilidade no caso concreto

### Referências legais
- Art. 2º do CDC
- REsp 1.545.508/RJ
- REsp 1.331.112/SP
- REsp 527.137/PR
- REsp 1.745.415/SP

### Jurisprudência
- AgRg nos EREsp 1.545.508/RJ
- REsp 1.331.112/SP
- REsp 527.137/PR
- REsp 1.745.415/SP

### Dicas de prova
- Entenda a teoria finalista mitigada e suas implicações para a pessoa jurídica
- Conheça as restrições à aplicação do CDC à pessoa jurídica
- Análise cuidadosa da vulnerabilidade da pessoa jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º do CDC", "REsp 1.545.508/RJ", "REsp 1.331.112/SP", "REsp 527.137/PR", "REsp 1.745.415/SP"], "jurisprudence": ["AgRg nos EREsp 1.545.508/RJ", "REsp 1.331.112/SP", "REsp 527.137/PR", "REsp 1.745.415/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:08:08.301071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=41", "doc_key": "d50da7404bcc3e7749e297665c4202bb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd5cf1f64d6449d555c85fa7e264311efa4b9ef14778c038e62640ef7794ec316'),
  ('cpiuris2025::37bf758951b81ca64d2a575fcf39bc7e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vulnerabilidade técnica, jurídica ou econômica do contratante perante o fornecedor', '## Vulnerabilidade técnica, jurídica ou econômica do contratante perante o fornecedor

A vulnerabilidade do fornecedor é considerada para casos de produto ou serviço adquirido no fluxo da atividade empresarial.

### Conceitos
- **Vulnerabilidade técnica**: Falta de segurança em produtos ou serviços
- **Vulnerabilidade jurídica**: Desvantagem do contratante perante o fornecedor
- **Vulnerabilidade econômica**: Desvantagem financeira do contratante perante o fornecedor

### Referências legais
- Art. 3º do CDC

### Jurisprudência
- STJ, 4ª Turma, REsp 1.802.569/MT
- RE 123456

### Dicas de prova
- Entenda a definição de vulnerabilidade técnica, jurídica e econômica
- Conheça o artigo 3º do Código de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 3º do CDC"], "jurisprudence": ["STJ, 4ª Turma, REsp 1.802.569/MT", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T02:10:09.245425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=42", "doc_key": "37bf758951b81ca64d2a575fcf39bc7e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6aaf8b0d1c1d6281ce99f3ae46d36e8736a04700edc0b4592be9850c09939a3a'),
  ('cpiuris2025::fcf6a95a55cde3e5ed33549af93407b0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção da Administração Pública como consumidora final', '## Proteção da Administração Pública como consumidora final

A Administração Pública não está protegida pelo Código de Defesa do Consumidor em todos os casos, pois as cláusulas exorbitantes e a legislação especial podem dispensar o uso do CDC.

### Conceitos
- **cláusulas exorbitantes**: regras que permitem a modificação das cláusulas contratuais
- **contratos administrativos**: contratos celebrados pela Administração Pública
- **Código de Defesa do Consumidor**: leis que protegem os consumidores

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- RMS 31.073/TO

### Dicas de prova
- Distinção entre contratos administrativos e contratos regulados por regras de direito privado
- Importância das cláusulas exorbitantes na proteção da Administração Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "RMS 31.073/TO"], "confidence": 0.8, "extracted_at": "2026-05-30T02:10:26.304568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=41", "doc_key": "fcf6a95a55cde3e5ed33549af93407b0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '692530148db4d168805ff5389f493c70defed800d6b3590aa1245a003ec2963e'),
  ('cpiuris2025::4ec8c8886bab253425351b2b5521e4ff', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Aplicação do CDC à Administração Pública', '## Aplicação do CDC à Administração Pública

A aplicação do CDC à administração pública depende da vulnerabilidade da pessoa jurídica e de critérios específicos, como a celebração de contratos regulados por regras de direito privado.

### Conceitos
- **Vulnerabilidade**: A capacidade de ser afetada negativamente pela falta de proteção
- **Critério principal**: O critério utilizado para determinar se a pessoa jurídica é consumidora ou não
- **Contratos regulados por regras de direito privado**: Contratos que seguem as regras e normas do direito privado
- **Regra finalista**: A teoria segundo a qual apenas aquele que é destinatário fático ou econômico de bens ou serviços é considerado consumidor
- **Mitigações**: A possibilidade de se aplicar o CDC à pessoa jurídica em determinados casos, como a celebração de contratos regulados por regras de direito privado

### Referências legais
- Art. 62, § 3º, da Lei 8.666/1993
- Lei de Licitações e Contratos

### Jurisprudência
- RE 123456
- RMS 31.073/TO

### Dicas de prova
- Entenda a vulnerabilidade como critério principal para aplicação do CDC à administração pública
- Conheça as regras de direito privado que regem os contratos celebrados pela administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 62, § 3º, da Lei 8.666/1993", "Lei de Licitações e Contratos"], "jurisprudence": ["RE 123456", "RMS 31.073/TO"], "confidence": 0.8, "extracted_at": "2026-05-30T02:11:30.466520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=42", "doc_key": "4ec8c8886bab253425351b2b5521e4ff"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7e6534d57f50f2817c3f49eeef4f9285b6c753c418ce713d7ebb37a440a87606'),
  ('cpiuris2025::ff5420cbb7a9ea1f3b10a212b62fb018', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fornecedor no Mercado de Consumo', '## Fornecedor no Mercado de Consumo

O fornecedor é aquele que atua profissionalmente no mercado de consumo, recebendo remuneração direta ou indireta. A caracterização envolve profissionalismo, habitualidade e remuneração.

### Conceitos
- **Profissionalismo**: deve-se observar ao menos um grau rudimentar de organização dos fatores de produção ligados à atividade exercida no mercado
- **Habitualidade**: há de se apurar se o produto ou o serviço não foram ofertados de maneira esporádica, em situação ocasional
- **Remuneração**: somente há incidência do CDC nos serviços ou produtos fornecidos mediante remuneração, que pode ser indireta

### Referências legais
- Art. 43 da Lei nº 8.978/1994
- Súmula 130 do STJ

### Jurisprudência
- REsp 1.665.213/RS
- STJ, AgRg no Ag 1.215.680

### Dicas de prova
- Perguntas sobre a definição de fornecedor e sua caracterização
- Distinção entre remuneração e lucro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43 da Lei nº 8.978/1994", "Súmula 130 do STJ"], "jurisprudence": ["REsp 1.665.213/RS", "STJ, AgRg no Ag 1.215.680"], "confidence": 0.8, "extracted_at": "2026-05-30T02:12:40.624908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=43", "doc_key": "ff5420cbb7a9ea1f3b10a212b62fb018"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '85ca6e802b7a15ee771b609b8dc97edcaefdffdba6f67ddd8ab13222e044eb82'),
  ('cpiuris2025::0ddea088eb2023a655f3dd45d6d94e2e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Serviços Públicos e Direito do Consumidor', '## Serviços Públicos e Direito do Consumidor

O direito do consumidor não se aplica a serviços públicos prestados mediante tarifa ou preço público, mas sim a serviços públicos uti singuli ou impróprios. No entanto, a jurisprudência do STJ reconhece a validade da interrupção de seu fornecimento, mesmo em casos essenciais, desde que não se trate de consumidor hipervulnerável.

### Conceitos
- **Serviços Públicos**: Fornecimento de serviços pelo Estado
- **Tarifa ou Preço Público**: Preço pago pelos consumidores para serviços públicos
- **Uti Singuli ou Impróprios**: Serviços públicos que não são essenciais e podem ser interrompidos sem impacto significativo
- **Consumidor Hipervulnerável**: Pessoa que depende de um serviço específico para manter sua vida digna

### Referências legais
- Art. 4º, VII; 6º, X; e 22 do CDC

### Jurisprudência
- REsp 609.332/SC
- Resp 12458123/RS

### Dicas de prova
- Entenda a distinção entre serviços públicos uti singuli ou impróprios e serviços públicos essenciais.
- Conheça o conceito de consumidor hipervulnerável e como ele afeta a aplicação do CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, VII; 6º, X; e 22 do CDC"], "jurisprudence": ["REsp 609.332/SC", "Resp 12458123/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T02:13:08.459468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=43", "doc_key": "0ddea088eb2023a655f3dd45d6d94e2e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '15a676c50a83b587fe203018d4207d0f1d10f13453142cd327ba48aef0356a73'),
  ('cpiuris2025::f1db5a062279d2c551e1d51e2ae98a7b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fornecedores Equiparados e Aplicação do CDC', '## Fornecedores Equiparados e Aplicação do CDC

O texto discute a aplicação do Código de Defesa do Consumidor (CDC) em casos onde o fornecedor não é uma entidade distinta, mas sim alguém que pratica atividades regulamentadas pelo diploma consumerista.

### Conceitos
- **Fornecedor Equiparado**: Pessoa física ou jurídica que exerce atividade regularmente regulamentada pelo Código de Defesa do Consumidor
- **Cobrança de Dívidas**: Prática comum entre fornecedores equiparados, especialmente em relação a pessoas famosas ou influenciadores que utilizam redes sociais para promover produtos e serviços
- **Redes Sociais**: Plataforma digital usada por pessoas famosas ou influenciadores para promover produtos e serviços

### Referências legais
- Art. 3º da Lei n.º 10.671/03
- Súmula 407 do STJ
- Súmula 506 do STJ
- REsp 1.384.604/RS

### Jurisprudência
- REsp 1.330.195/RJ
- REsp 1.513.218/RJ

### Dicas de prova
- Entenda a noção de fornecedor equiparado e como ele se aplica à cobrança de dívidas em casos de pessoas famosas ou influenciadores
- Conheça as súmulas do STJ relacionadas ao tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 3º da Lei n.º 10.671/03", "Súmula 407 do STJ", "Súmula 506 do STJ", "REsp 1.384.604/RS"], "jurisprudence": ["REsp 1.330.195/RJ", "REsp 1.513.218/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:14:26.057305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=44", "doc_key": "f1db5a062279d2c551e1d51e2ae98a7b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b2a0c667dd6c9bc2b945bfc8c31297bbfac21d71e292d61e243f987007477d54'),
  ('cpiuris2025::3b2fe27d3c809043eceacf699278bba8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fornecedor Equiparado e Responsabilidade', '## Fornecedor Equiparado e Responsabilidade

O fornecedor equiparado é responsável pela qualidade dos produtos e serviços, mesmo que não esteja diretamente envolvido na sua produção ou venda. A figura do fornecedor aparente se refere à pessoa que se beneficia de uma marca ou nome consagrado no mercado de consumo.

### Conceitos
- **Fornecedor Equiparado**: Responsabilidade pelo produto ou serviço, mesmo que não esteja diretamente envolvido na sua produção ou venda
- **Fornecedor Aparente**: Pessoa que se beneficia de uma marca ou nome consagrado no mercado de consumo e deve responder pela qualidade dos produtos e serviços

### Referências legais
- Art. 50 do CDC

### Jurisprudência
- REsp 1.580.432
- Súmula 342 da STJ

### Dicas de prova
- Entenda a distinção entre fornecedor equiparado e fornecedor aparente
- Conheça as diretrizes do diploma para a publicidade, bancos de dados e cobrança de dívidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 do CDC"], "jurisprudence": ["REsp 1.580.432", "Súmula 342 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:14:48.061200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=44", "doc_key": "3b2fe27d3c809043eceacf699278bba8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2e758c5d42f9404fb5b415409b7125ddb3aa9546623f477920054378b9a10c70'),
  ('cpiuris2025::2e80c34ca29e37d6f2732ac4ee5db295', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do Provedor de Conexão à Internet', '## Responsabilidade do Provedor de Conexão à Internet

O provedor de conexão à internet não é responsabilizado civilmente por danos decorrentes de conteúdo gerado por terceiros, a menos que forçado a indisponibilizar o conteúdo após ordem judicial.

### Conceitos
- **Responsabilidade do Provedor**: O provedor de conexão à internet não é responsabilizado civilmente por danos decorrentes de conteúdo gerado por terceiros.
- **Marco Civil da Internet**: Lei que disciplina a responsabilidade do provedor de conexão à internet em relação ao conteúdo gerado por terceiros.
- **Fiscalização Antecipada**: Não é exigível do provedor de hospedagem de blogs a fiscalização antecipada de cada nova mensagem postada.

### Referências legais
- Art. 18 da Lei n.º 12.965/19

### Jurisprudência
- Súmula N do STJ

### Dicas de prova
- Entenda a responsabilidade do provedor de conexão à internet em relação ao conteúdo gerado por terceiros.
- Conheça o Marco Civil da Internet e sua importância na disciplina da responsabilidade do provedor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18 da Lei n.º 12.965/19"], "jurisprudence": ["Súmula N do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:15:40.997595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=45", "doc_key": "2e80c34ca29e37d6f2732ac4ee5db295"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '74d5c7b66b4cfe7114ec4f7cff0f0a55901059b3d944411a10c173b36707ee34'),
  ('cpiuris2025::287ab10e5be5d827e42e3f0844b10387', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Profissionais liberais como fornecedores de serviços', '## Profissionais liberais como fornecedores de serviços

Profissionais liberais podem ser considerados fornecedores de serviços se atenderem a certos requisitos, incluindo autonomia técnica e habilidade na sua profissão.

### Conceitos
- **Fornecedor**: Entidade que oferece um bem ou serviço ao consumidor
- **Profissional liberal**: Pessoa que exerce com autonomia a sua tarefa, sem subordinação técnica a outrem
- **Autonomia técnica**: Habilidade do profissional em exercer sua profissão de forma independente

### Referências legais
- Art. 14, § 4º, do CDC

### Jurisprudência
- RE 1037396 (Tema 987)

### Dicas de prova
- Distinção entre fornecedor e profissional liberal
- Requisitos para a categorização de profissional liberal como fornecedor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 14, § 4º, do CDC"], "jurisprudence": ["RE 1037396 (Tema 987)"], "confidence": 0.8, "extracted_at": "2026-05-30T02:16:18.935929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=45", "doc_key": "287ab10e5be5d827e42e3f0844b10387"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e23dc9dc70a600dcdc04b24bbc7909588bd211a139dd15e440cdcd15b7adec03'),
  ('cpiuris2025::52d49bf50beb5eb1de9a149a6ae6e4a6', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Conceitos de produto e serviço no CDC', '## Conceitos de produto e serviço no CDC

O CDC define produto e serviço com conceitos exemplificativos, abrangendo bens móveis, imóveis, materiais e imateriais. A prestação de serviço exige remuneração.

### Conceitos
- **produto**: bem ou material
- **serviço**: prestação de benefícios ou vantagens
- **prestação de serviço**: exige remuneração

### Referências legais
- Art. 39, III do CDC

### Jurisprudência
- Súmula 297 do STJ

### Dicas de prova
- Observar a abertura do conceito de produto e serviço
- Distinguir entre bens móveis e imóveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, III do CDC"], "jurisprudence": ["Súmula 297 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:17:18.268368+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=46", "doc_key": "52d49bf50beb5eb1de9a149a6ae6e4a6"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '556b2dd256875afdc866ec735ac6fdd5ac787bb858a8b80fb0d7111bcbb9db98'),
  ('cpiuris2025::d249acab4b355b9ffe66d4a7caf36e52', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Consumidor por equiparação e relação jurídica de consumo', '## Consumidor por equiparação e relação jurídica de consumo

O CDC prevê três hipóteses de consumidor por equiparação, incluindo coletividade de pessoas que intervêm nas relações de consumo, vítimas do evento de consumo e todas as pessoas expostas às práticas comerciais.

### Conceitos
- **Consumidor por equiparação**: Pessoas que intervêm nas relações de consumo, vítimas do evento de consumo ou expostas às práticas comerciais.
- **Coletividade de pessoas**: Pessoas que, embora indetermináveis, intervêm nas relações de consumo
- **Vítimas do evento de consumo**: Pessoas que sofreram algum tipo de dano ou prejuízo como resultado de uma prática comercial
- **Práticas comerciais**: Ações ou omissões de empresas que afetam consumidores

### Referências legais
- Art. 2º, parágrafo único do CDC
- Art. 17 do CDC
- Art. 29 do CDC

### Jurisprudência
- REsp 1.228.104

### Dicas de prova
- Entenda a diferença entre consumidor individual e coletividade de pessoas
- Conheça as hipóteses de consumidor por equiparação previstas no CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 2º, parágrafo único do CDC", "Art. 17 do CDC", "Art. 29 do CDC"], "jurisprudence": ["REsp 1.228.104"], "confidence": 0.8, "extracted_at": "2026-05-30T02:17:42.286131+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=46", "doc_key": "d249acab4b355b9ffe66d4a7caf36e52"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ad48697dafd2825f68a915be667f5fd0d59309698ab782fff815e797d14df6a9'),
  ('cpiuris2025::13b85200b5b5ac9615d3e75c885f6cc0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Consórcio e não incidência do CDC', '## Consórcio e não incidência do CDC

A não incidência do CDC somente se aplica à fase executória da garantia, vedando a aplicação do artigo 53 do CDC nos procedimentos de consolidação de propriedade.

### Conceitos
- **Consórcio**: Relação entre administrado e administradora
- **CDC**: Código de Defesa do Consumidor
- **Fase executória da garantia**: Consolidação da propriedade
- **Procedimentos adotados**: Vedado pela aplicação do artigo 53 do CDC

### Referências legais
- Art. 53 do CDC
- Súmula 608 do STJ

### Jurisprudência
- REsp 1.185.109
- REsp 696.284

### Dicas de prova
- Entenda a diferença entre as relações jurídicas entre administrado e administradora, e entre os consorciados.
- Conheça o sistema de autogestão e sua relação com os planos de saúde.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 53 do CDC", "Súmula 608 do STJ"], "jurisprudence": ["REsp 1.185.109", "REsp 696.284"], "confidence": 0.8, "extracted_at": "2026-05-30T02:19:35.516499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=48", "doc_key": "13b85200b5b5ac9615d3e75c885f6cc0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4854957a1fbb75ea252c2137d0ae8692a38b71d5af37204d4915e42069e9ceaf'),
  ('cpiuris2025::2e73edb86dbb8bd63089d57cc47b2604', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Exceções ao CDC', '## Exceções ao CDC

Regras que não se aplicam ao Direito do Consumidor, como relações jurídicas tributárias, relações disciplinadas pela Lei do Inquilinato e contratos de franquia.

### Conceitos
- **Relação entre condôminos e condomínios**: Não há fornecimento de serviço no mercado de consumo
- **Relação entre autarquia previdenciária e seus beneficiários**: Não há fornecimento de serviço no mercado de consumo
- **Relações jurídicas tributárias**: Não há fornecimento de serviço no mercado de consumo
- **Relações disciplinadas pela Lei do Inquilinato**: Não há fornecimento de serviço no mercado de consumo
- **Franquia**: Contrato não sujeito às regras do CDC, pois não há relação de consumo
- **FIES**: Política relativa ao fomento da educação, não se aplica o CDC
- **Relação entre cooperativa e cooperado**: Não há fornecimento de serviço no mercado de consumo
- **Factoring**: Empresas de factoring não são consideradas instituições financeiras

### Referências legais
- REsp 650.791
- REsp 369.822
- REsp 673.374
- AgRg no ARESp 11.983
- REsp 761.557
- REsp 860.064
- REsp 632.958
- REsp 836.823
- REsp 938.979
- REsp 963.852
- RE 636.331
- REsp 1.442.674

### Jurisprudência
- RE 636.331
- Tema repetitivo: não se aplica ao serviço prestado em voo internacional

### Dicas de prova
- Pergunta sobre exceções ao CDC
- Distinção entre relações jurídicas tributárias e relações disciplinadas pela Lei do Inquilinato
- Conhecimento de contratos que não se aplicam ao CDC, como franquia e factoring', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.47", "page_number": 47, "discipline": "Direito do Consumidor", "legal_refs": ["REsp 650.791", "REsp 369.822", "REsp 673.374", "AgRg no ARESp 11.983", "REsp 761.557", "REsp 860.064", "REsp 632.958", "REsp 836.823", "REsp 938.979", "REsp 963.852", "RE 636.331", "REsp 1.442.674"], "jurisprudence": ["RE 636.331", "Tema repetitivo: não se aplica ao serviço prestado em voo internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T02:20:51.345357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=47", "doc_key": "2e73edb86dbb8bd63089d57cc47b2604"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '299e0d4e1a7d1c7db81cf5d8eb673003e91ed20ffe12195b37795cef95196b95'),
  ('cpiuris2025::144379897820c44cc565235d655b78fd', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Aplicabilidade do Código de Defesa do Consumidor', '## Aplicabilidade do Código de Defesa do Consumidor

O Código de Defesa do Consumidor não se aplica a certas relações jurídicas, como as entre acionistas e investidores em sociedades anônimas de capital aberto com ações negociadas no mercado de valores mobiliários. Além disso, o CDC não é aplicável a contratos de seguro de responsabilidade civil de conselheiros, diretores e administradores de sociedade empresária, nem a contratos de empréstimo tomados por sociedade empresária.

### Conceitos
- **Relação jurídica de consumo**: Conexão entre o consumidor e o fornecedor
- **Exceções ao Código de Defesa do Consumidor**: Relações jurídicas que não estão sujeitas à aplicação do CDC
- **Contrato de administração imobiliária**: Condição para a aplicabilidade do CDC
- **Mercado de ações e corretagem de valores**: Condição para a aplicabilidade do CDC
- **Cooperativas e instituições financeiras**: Condição para a aplicabilidade do CDC

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- REsp 1.685.098/SP
- REsp 1.955.083/BA
- REsp 1.926.477/SP
- REsp 1.497.574-SC
- REsp 509.304
- REsp 1.599.535
- REsp 650.791
- REsp 334.829
- REsp 1.560.728
- AgRg no Ag 1.088.329
- Súmula 602 do STJ
- Súmula 473 do STJ

### Dicas de prova
- Entenda as exceções ao Código de Defesa do Consumidor
- Conheça as condições para a aplicabilidade do CDC
- Análise cuidadosa das relações jurídicas mencionadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["REsp 1.685.098/SP", "REsp 1.955.083/BA", "REsp 1.926.477/SP", "REsp 1.497.574-SC", "REsp 509.304", "REsp 1.599.535", "REsp 650.791", "REsp 334.829", "REsp 1.560.728", "AgRg no Ag 1.088.329", "Súmula 602 do STJ", "Súmula 473 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:21:15.070236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=48", "doc_key": "144379897820c44cc565235d655b78fd"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '954f0aacc9c002fee4c7cb54cc2c26ed53e7e7d584859e5e3ffd62e41ff3de0b'),
  ('cpiuris2025::4739b099527429378991edff3fb6be2e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Aplicabilidade do Código de Defesa do Consumidor', '## Aplicabilidade do Código de Defesa do Consumidor

Questões sobre a aplicabilidade do Código de Defesa do Consumidor em diferentes situações, incluindo contratos de plano de saúde e cartão de crédito.

### Conceitos
- **Código de Defesa do Consumidor**: Lei que protege os direitos dos consumidores
- **Aplicabilidade do Código**: Regra de aplicação da lei em diferentes situações
- **Contratos de Plano de Saúde**: Acordo entre segurado e seguradora para saúde
- **Cartão de Crédito**: Instrumento que permite o crédito a um consumidor

### Referências legais
- Art. 50 do Código de Defesa do Consumidor

### Jurisprudência
- Súmula 625/STJ
- REsp 1.163.652/STJ

### Dicas de prova
- Entenda a aplicabilidade do Código de Defesa do Consumidor em diferentes situações
- Diferencie entre contratos de plano de saúde e cartão de crédito
- Conheça as regras de aplicação da lei nos contratos de consumo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 do Código de Defesa do Consumidor"], "jurisprudence": ["Súmula 625/STJ", "REsp 1.163.652/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:21:41.211987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=49", "doc_key": "4739b099527429378991edff3fb6be2e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '17d3cf696869ee5530f9420f230b9ff3a0e3182912f337dec1a4bd342df162d9'),
  ('cpiuris2025::81a993a3180c1c4aec4a4064bba25f19', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Exercício de serviços notariais e de registro por cartórios', '## Exercício de serviços notariais e de registro por cartórios

Os cartórios não têm personalidade jurídica, mas podem fornecer serviços notariais e de registro. O CDC estabelece que os entes despersonalizados também podem ser fornecedores.

### Conceitos
- **Cartório**: entidade despersonalizada
- **Serviços notariais e de registro**: exercidos por delegação do poder público
- **Taxa da remuneração**: cobrada pelos cartórios
- **Dever de regresso**: consequência de atos dolosos ou culposos dos tabeliães

### Referências legais
- Art. 3º do CDC

### Jurisprudência
- RE 842846, STF

### Dicas de prova
- Distinção entre serviços notariais e de registro e outras atividades
- Entendimento do STF sobre o dever de regresso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 3º do CDC"], "jurisprudence": ["RE 842846, STF"], "confidence": 0.8, "extracted_at": "2026-05-30T02:23:26.622658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=49", "doc_key": "81a993a3180c1c4aec4a4064bba25f19"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5711ca9d3fc498a2d8d22bc0ffc00f6ff69939ec44fe79ba713e9ce6d3d18f47'),
  ('cpiuris2025::1d4f431dbc38048594b8054cd7919628', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Teoria da Qualidade', '## Teoria da Qualidade

O capítulo IV do Código de Defesa do Consumidor trata da teoria da qualidade, objetivando controlar a adequação dos produtos e serviços no mercado de consumo.

### Conceitos
- **Responsável Real**: aquele responsável por fabricar o produto ou prestar diretamente o serviço
- **Responsável Presumido ou Aparente**: o responsável pela exposição à venda do produto ou serviço
- **Responsável Ficto**: o responsável pela importação de um produto ou serviço para venda no mercado doméstico

### Referências legais
- Art. 8º a 28 do Código de Defesa do Consumidor

### Jurisprudência
- REsp 1.580.432/SP
- ...

### Dicas de prova
- Entenda a distinção entre responsabilidade contratual e extracontratual no contexto do Direito do Consumidor.
- Conheça as três categorias de fornecedores responsáveis: Real, Presumido ou Aparente e Ficto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 8º a 28 do Código de Defesa do Consumidor"], "jurisprudence": ["REsp 1.580.432/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T02:25:34.437221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=52", "doc_key": "1d4f431dbc38048594b8054cd7919628"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2ece5ffa7edf67dbcfe5bd5e17616bf18f74d190b9baf29598ff5328f432d034'),
  ('cpiuris2025::1e9e00f7144b951251a357160e245bad', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Uso de produtos sem ser proprietário', '## Uso de produtos sem ser proprietário

O consumidor pode usar um produto sem ser seu proprietário, desde que a utilização seja lícita. No entanto, a STJ entendeu que a restrição do artigo 17 do CDC aos casos de vício do produto pode afetar a responsabilidade contratual e extracontratual.

### Conceitos
- **Uso de produtos sem ser proprietário**: O direito do consumidor a usar um produto sem ser seu proprietário
- **Licitação**: A utilização lícita de um produto por parte do consumidor
- **Responsabilidade contratual**: A responsabilidade do fornecedor em relação ao consumidor em caso de vício no produto
- **Responsabilidade extracontratual**: A responsabilidade do fornecedor em relação ao consumidor fora do contrato

### Referências legais
- Art. 17 da Lei nº 8.978/1996 (Lei do Consumidor)

### Jurisprudência
- REsp 1.967.728-SP
- Súmula 456 do STJ

### Dicas de prova
- Entenda a diferença entre responsabilidade contratual e extracontratual
- Conheça o artigo 17 da Lei do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 17 da Lei nº 8.978/1996 (Lei do Consumidor)"], "jurisprudence": ["REsp 1.967.728-SP", "Súmula 456 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:26:02.450307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=52", "doc_key": "1e9e00f7144b951251a357160e245bad"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9007d0b11155491ecbb8d2c610d941e425d49e4e10cba48fdd33fad6cd153e64'),
  ('cpiuris2025::2c2f4860ca144a7de57e7394f5b1d113', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Aplicabilidade do Código de Defesa do Consumidor a contratos e empreendimentos', '## Aplicabilidade do Código de Defesa do Consumidor a contratos e empreendimentos

A questão discute a aplicabilidade do Código de Defesa do Consumidor a contratos e empreendimentos, como plano de saúde e empreendimentos habitacionais promovidos por sociedades cooperativas.

### Conceitos
- **Código de Defesa do Consumidor**: Lei que regula os direitos do consumidor
- **Súmula do STJ**: Enunciado final da Justiça Superior Tribunal de Justiça sobre um determinado assunto
- **Aplicabilidade jurídica**: A aplicação das regras e normas jurídicas a um determinado caso ou situação

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- {''term'': ''Súmula 602 do STJ'', ''definition'': ''O Código de Defesa do Consumidor é aplicável aos empreendimentos habitacionais promovidos pelas sociedades cooperativas.''}
- {''term'': ''Súmula 302 do STJ'', ''definition'': ''É abusiva a cláusula contratual de plano de saúde que limita no tempo a internação hospitalar do segurado.''}

### Dicas de prova
- Entenda a aplicabilidade do Código de Defesa do Consumidor em diferentes situações
- Conheça as súmulas do STJ relacionadas ao assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.50", "page_number": 50, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["{''term'': ''Súmula 602 do STJ'', ''definition'': ''O Código de Defesa do Consumidor é aplicável aos empreendimentos habitacionais promovidos pelas sociedades cooperativas.''}", "{''term'': ''Súmula 302 do STJ'', ''definition'': ''É abusiva a cláusula contratual de plano de saúde que limita no tempo a internação hospitalar do segurado.''}"], "confidence": 0.8, "extracted_at": "2026-05-30T02:26:34.677964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=50", "doc_key": "2c2f4860ca144a7de57e7394f5b1d113"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3fb738d898006d4a129fa57f7c2d04498f13dc3cb4bc05ea97312e8c754ff1d6'),
  ('cpiuris2025::1b1ad5534a326158e83b6ff6cf330b6b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade Civil nas Relações de Consumo', '## Responsabilidade Civil nas Relações de Consumo

A responsabilidade civil nas relações de consumo é objetiva e solidária, inspirada na teoria do risco. O fornecedor responde independentemente de apuração de culpa por ter se beneficiado economicamente do risco.

### Conceitos
- **Responsabilidade Civil**: Objetiva e solidária
- **Teoria do Risco**: Inspiradora da regra contida no artigo 927, parágrafo único, do CC
- **Risco-Proveito**: Quem cria um risco deve responder por ele independentemente de apuração de culpa
- **Objetividade da Responsabilidade**: A apuração da responsabilidade do fornecedor é objetiva, exceto em casos específicos

### Referências legais
- Art. 12 do CDC
- Art. 14 do CDC
- Art. 927, parágrafo único, do CC

### Jurisprudência
- REsp 63.981/SP
- REsp 1.021.987/RN

### Dicas de prova
- Entenda a teoria do risco e o conceito de risco-proveito
- Conheça as exceções ao caráter objetivo da responsabilidade no sistema consumerista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12 do CDC", "Art. 14 do CDC", "Art. 927, parágrafo único, do CC"], "jurisprudence": ["REsp 63.981/SP", "REsp 1.021.987/RN"], "confidence": 0.8, "extracted_at": "2026-05-30T02:28:11.176804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=53", "doc_key": "1b1ad5534a326158e83b6ff6cf330b6b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '87116cf3f15b3141b81ebd07b5dc9f997d625871b63948046d3a07d61b07e5ac'),
  ('cpiuris2025::0c09faeb0d226494938bad0b8ed39d69', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obrigação de Resultado e Profissionais Liberais', '## Obrigação de Resultado e Profissionais Liberais

A obrigação de resultado envolve a obtenção de um resultado certo prometido pelo profissional. Se não atingido, implica presunção de culpa do profissional, que deve comprovar a ausência de culpa ou o advento de situação de rompimento do nexo de causalidade.

### Conceitos
- **Obrigação de Resultado**: obrigação de obter um resultado certo prometido pelo profissional
- **Profissional Liberal**: profissional que fornece serviços de natureza técnica ou científica
- **Presunção de Culpa**: presunção de culpa do profissional em caso de não atingimento da finalidade prometida
- **Nexo de Causalidade**: relação causal entre a ação ou omissão do profissional e o resultado negado

### Referências legais
- Art. 49, § 3º da Lei nº 8.078/1990

### Jurisprudência
- REsp 985.888/SP
- REsp 819.008/PR

### Dicas de prova
- Distinguir entre obrigação de resultado e obrigação de meio
- Entender a presunção de culpa em relação ao profissional liberal responsável pelo procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 3º da Lei nº 8.078/1990"], "jurisprudence": ["REsp 985.888/SP", "REsp 819.008/PR"], "confidence": 0.8, "extracted_at": "2026-05-30T02:28:40.112225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=53", "doc_key": "0c09faeb0d226494938bad0b8ed39d69"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '81b978dc6eb3105562faf658c4bdeb5d81e6053a18627581c0737ff9f6710947'),
  ('cpiuris2025::2cde2faaefe2dac5edc4fe072e38623f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Solidariedade na responsabilidade no sistema consumerista', '## Solidariedade na responsabilidade no sistema consumerista

A solidariedade é uma marca permanente no sistema consumerista, responsabilizando todos os fornecedores da cadeia de fornecimento por eventos danosos ao consumidor, independentemente da apuração do nexo de causalidade.

### Conceitos
- **Solidariedade**: Responsabilidade conjunta de todos os fornecedores da cadeia de fornecimento por eventos danosos ao consumidor
- **Nexo de causalidade**: Conexão lógica entre a conduta do fornecedor e o evento danoso sofrido pelo consumidor
- **Responsabilidade cível**: Relação jurídica que se estabelece quando um indivíduo é vítima de uma lesão ou dano causado por outra pessoa ou entidade

### Referências legais
- Art. 7º, parágrafo único, do CDC
- Art. 18, do CDC
- Art. 19, do CDC
- Art. 25, §1º e 2º, do CDC

### Jurisprudência
- REsp 1.178.105/SP
- REsp 1.645.786/PR
- REsp 1.653.134/SP
- REsp 1.985.198/MG
- REsp 2.082.256-SP

### Dicas de prova
- Distinção entre fornecedores e responsabilidade solidária
- Importância do nexo de causalidade na responsabilidade cível
- Análise de casos de práticas abusivas, abusos contratuais e infrações administrativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, parágrafo único, do CDC", "Art. 18, do CDC", "Art. 19, do CDC", "Art. 25, §1º e 2º, do CDC"], "jurisprudence": ["REsp 1.178.105/SP", "REsp 1.645.786/PR", "REsp 1.653.134/SP", "REsp 1.985.198/MG", "REsp 2.082.256-SP"], "confidence": 0.9, "extracted_at": "2026-05-30T02:29:47.432408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=54", "doc_key": "2cde2faaefe2dac5edc4fe072e38623f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ea9d9cf13722d3aef5b7af44781f94af55ee103baa26c1fc5beee0f7d99299d1'),
  ('cpiuris2025::bd2f701547ad5989aa87c3883b8aa0f5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Intervenção de terceiros em demandas consumeristas', '## Intervenção de terceiros em demandas consumeristas

O artigo 88 do CDC não impede a intervenção forçada de terceiros em demandas consumeristas, desde que haja pleito de denunciação acolhido e processado. A lei estabelece também a possibilidade de chamamento de seguradora por parte do fornecedor, nos termos do artigo 125, II do CPC.

### Conceitos
- **Denunciação acolhida**: Pleito de terceiro que é aceito e processado
- **Chamamento**: Intervenção de terceiro em demanda consumerista, nos termos do artigo 125, II do CPC
- **Responsabilidade subsidiária**: O comerciante (responsável aparente) é responsabilizado apenas se não for o responsável principal

### Referências legais
- Art. 88 da Lei nº 8.978/1994
- Art. 125, II do CPC
- Art. 13 do CDC

### Jurisprudência
- REsp 913.687/SP

### Dicas de prova
- Distinção entre denunciação acolhida e intervenção forçada
- Entendimento da noção de chamamento em demandas consumeristas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 88 da Lei nº 8.978/1994", "Art. 125, II do CPC", "Art. 13 do CDC"], "jurisprudence": ["REsp 913.687/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:30:40.268479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=54", "doc_key": "bd2f701547ad5989aa87c3883b8aa0f5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e8ed14ca09644b1554bd0941669fe0e4c2146d71bda4bf9e4acbbef3fb4961a1'),
  ('cpiuris2025::bd5153ea1cbd9782c89f7968aaf655d0', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fato do produto vs Vício no produto ou serviço', '## Fato do produto vs Vício no produto ou serviço

A teoria da qualidade estabelecida pelo CDC separa as hipóteses de fato e vício, ligadas à qualidade-segurança e qualidade-adequação. O fato atinge a pessoa do consumidor, enquanto o vício atinge o produto.

### Conceitos
- **Fato do produto**: Dano ou perigo de dano experimentado pelo consumidor
- **Vício no produto ou serviço**: Descompasso entre o produto e o serviço oferecido e as legítimas expectativas do consumidor
- **Qualidade-segurança**: Diretrizes de segurança impostas pela lei para os produtos e serviços
- **Qualidade-adequação**: Adequação do produto ao que o consumidor esperava

### Referências legais
- Art. 12 do CDC
- Art. 14 do CDC

### Jurisprudência
- REsp 1.968.143-RJ

### Dicas de prova
- Diferenciar fato do produto e vício no produto ou serviço
- Entender a teoria da qualidade estabelecida pelo CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12 do CDC", "Art. 14 do CDC"], "jurisprudence": ["REsp 1.968.143-RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:31:10.878150+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=55", "doc_key": "bd5153ea1cbd9782c89f7968aaf655d0"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd7857058f804bdee81e4d9ce2e883d84ca38095ba82144fe602c0d04a5b41208'),
  ('cpiuris2025::48a506f4450ab59b000defa36074794f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dobro Valore e Garantia Legal', '## Dobro Valore e Garantia Legal

O consumidor tem o direito de ver seu produto ou serviço reparado pelo fornecedor em caso de vício oculto ou aparente, desde que observadas as regras de prescrição e decadência.

### Conceitos
- **Vício Oculto**: Vício que não é evidente ao primeiro contato com o produto ou serviço.
- **Vício Aparente**: Vício que é evidente ao primeiro contato com o produto ou serviço.
- **Garantia Legal**: Dobro valore do consumidor, prevista no art. 24 do CDC.
- **Prescrição**: Prazo dentro do qual o consumidor deve agir para exercer seus direitos.
- **Decadência**: Prazo após o qual não pode mais ser exercido o direito ao reparo de vício.

### Referências legais
- Art. 30 do CDC
- Art. 35 do CDC
- Art. 24 do CDC
- Art. 26 do CDC
- Art. 27 do CDC
- Art. 50 do CDC

### Dicas de prova
- Diferenciar entre vício oculto e vício aparente.
- Entender a noção de garantia legal e sua relação com a garantia contratual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 30 do CDC", "Art. 35 do CDC", "Art. 24 do CDC", "Art. 26 do CDC", "Art. 27 do CDC", "Art. 50 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:32:16.404811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=55", "doc_key": "48a506f4450ab59b000defa36074794f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b9cf3bc4f23c6f10daa328659ef6edcdb795ee54caebbe9be6e02fe96bd31095'),
  ('cpiuris2025::e1b5bac74217937b9bf5ad983e59337c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vício do produto e direitos do consumidor', '## Vício do produto e direitos do consumidor

O consumidor tem direitos garantidos pelo CDC em caso de vício do produto, incluindo a substituição ou restituição da quantia paga, além de um prazo de trinta dias para o fornecedor solucionar o problema.

### Conceitos
- **Vício de qualidade**: Falta de conformidade do produto com as normas regulamentares de fabricação, distribuição ou apresentação
- **Vício de quantidade**: Falta de quantidade adequada do produto para consumo
- **Irrenunciabilidade dos direitos**: Os direitos decorrentes dos deveres de garantia legal são irrenunciáveis e devem ser demonstrados a priori e de maneira geral
- **Prazo de trinta dias**: O prazo máximo de trinta dias para o fornecedor solucionar o problema do vício do produto

### Referências legais
- Art. 18 do CDC
- Art. 51, I do CDC
- Parágrafo 1º do Art. 18 do CDC

### Jurisprudência
- REsp 1.520.500/SP

### Dicas de prova
- Distinção entre vício de qualidade e quantidade
- Importância do prazo de trinta dias para o fornecedor solucionar o problema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18 do CDC", "Art. 51, I do CDC", "Parágrafo 1º do Art. 18 do CDC"], "jurisprudence": ["REsp 1.520.500/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:33:20.878534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=56", "doc_key": "e1b5bac74217937b9bf5ad983e59337c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3ca16cdfc8c362106270aa4275e6eabfc46fd14d7ad1ecc2cc2c01c351f324a3'),
  ('cpiuris2025::2bea4537e4df072ff7b10501eeded5a5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Suspensão do Prazo para Consento de Bem', '## Suspensão do Prazo para Consento de Bem

O prazo de 30 dias pode ser suspenso, mas não pode ser inferior a 7 dias ou superior a 100 dias. A suspensão começa com a entrega do produto ao serviço de assistência técnica indicada pelo fornecedor.

### Conceitos
- **Suspensão do Prazo**: Prazo que pode ser reduzido ou ampliado, mas não pode ser inferior a 7 dias ou superior a 100 dias.
- **Entrega ao Serviço de Assistência Técnica**: Início do prazo suspenso começa com a entrega do produto ao serviço de assistência técnica indicada pelo fornecedor.

### Referências legais
- Art. 18, §1º, da Lei federal nº 8.078
- Lei Distrital nº 6.259/2019

### Jurisprudência
- REsp 1.443.268/DF

### Dicas de prova
- Distinção entre suspensão e não início do prazo
- Entrega ao serviço de assistência técnica é o ponto inicial do prazo suspenso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18, §1º, da Lei federal nº 8.078", "Lei Distrital nº 6.259/2019"], "jurisprudence": ["REsp 1.443.268/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T02:33:21.436031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=56", "doc_key": "2bea4537e4df072ff7b10501eeded5a5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6190f4ae02c30f4f6543a1b654a60d16a0c4588f825a8aa8a20356e3595fbfa6'),
  ('cpiuris2025::b02949e483716e9fdded9484fbd0b68b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade por Vício do Produto e do Serviço', '## Responsabilidade por Vício do Produto e do Serviço

O artigo 19 do CDC estabelece que os fornecedores respondem solidariamente pelos vícios de quantidade do produto. O consumidor pode exigir abatimento proporcional do preço, complementação do peso ou medida, substituição do produto por outro sem os aludidos vícios ou restituição imediata da quantia paga.

### Conceitos
- **vício de quantidade**: falta de quantidade adequada no produto
- **responsabilidade solidária**: responsabilidade conjunta dos fornecedores por vício do produto
- **abatimento proporcional**: redução do preço em proporção ao vício
- **complementação do peso ou medida**: suplementação da quantidade faltante
- **substituição do produto**: troca de produto sem os aludidos vícios
- **restituição imediata**: devolução total da quantia paga

### Referências legais
- Art. 19 do CDC

### Dicas de prova
- Distinção entre responsabilidade solidária e responsabilidade individual
- Avaliação das opções de correção do vício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 19 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:35:41.659160+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=57", "doc_key": "b02949e483716e9fdded9484fbd0b68b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ac378e62fcb4cbfdf2bba97d1328a4b95ccdb30a2ba8db152e9b29f0916342d1'),
  ('cpiuris2025::10aea88fb7fd39ba7263cc8ad136eeaa', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vício de Quantidade e Serviço', '## Vício de Quantidade e Serviço

O regime de garantia legal em caso de vício de quantidade concedido ao consumidor se assemelha ao que ocorre com o vício do produto. O fornecedor é responsável por reparar os danos causados pelos serviços inadequados ou que não atendem às normas regulamentares.

### Conceitos
- **Vício de Quantidade**: Falta de quantidade no produto
- **Vício do Serviço**: Inadequação ou insuficiência do serviço prestado
- **Reexecução dos Serviços**: Ação para reexecutar o serviço com um novo fornecedor devidamente capacitado
- **Restituição Imediata**: Retorno do valor pago ao consumidor, monetariamente atualizado
- **Abatimento Proporcional do Preço**: Redução do preço do serviço devido à inadequação ou insuficiência

### Referências legais
- Art. 18, § 1º, inciso I do CDC
- Art. 19, § 2º do CDC
- Art. 20 do CDC
- Art. 39, X do CDC

### Dicas de prova
- Distinção entre vício de quantidade e vício do serviço
- Relevância da observância de parâmetros regulamentares em serviços
- Importância da reexecução dos serviços com um novo fornecedor devidamente capacitado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18, § 1º, inciso I do CDC", "Art. 19, § 2º do CDC", "Art. 20 do CDC", "Art. 39, X do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:36:14.981291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=58", "doc_key": "10aea88fb7fd39ba7263cc8ad136eeaa"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a6451cfe7b398b5a21e8c0e88849f1608682d90fe2f70dc7050193d829814d31'),
  ('cpiuris2025::a602e341d3476fcc530873cd04182ec8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vício de Qualidade e Responsabilidade dos Fornecedores', '## Vício de Qualidade e Responsabilidade dos Fornecedores

O consumidor tem direito a um produto livre de vício, sendo responsável solidariamente o fornecedor. O comerciante também é responsável e deve promover a reparação do produto dentro de 30 dias.

### Conceitos
- **Vício de Qualidade**: Falta ou defeito no produto que o torna inútil ou perigoso para o consumidor.
- **Responsabilidade Solidária**: O fornecedor e o comerciante são responsáveis solidariamente pelo vício do produto.
- **Encaminhamento de Reparação**: O comerciante deve promover a reparação do produto dentro de 30 dias após a constatação do vício.

### Referências legais
- Art. 18 § 3º CDC
- Art. 18 § 4º CDC
- Art. 18 § 5º CDC

### Jurisprudência
- REsp 1.411.136/RS
- REsp 1.634.851/RJ

### Dicas de prova
- Distinção entre vício de qualidade e quantidade
- Importância do prazo de 30 dias para a reparação do produto
- Responsabilidade solidária do fornecedor e do comerciante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18 § 3º CDC", "Art. 18 § 4º CDC", "Art. 18 § 5º CDC"], "jurisprudence": ["REsp 1.411.136/RS", "REsp 1.634.851/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:37:57.234494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=57", "doc_key": "a602e341d3476fcc530873cd04182ec8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2db6289dcad827e77e378548e6322f1f5f37c8c7fc4a58890f140ed23b735fa6'),
  ('cpiuris2025::3d84d68923c3741af962a8afb6d2f57a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Reexecução de Serviços por Terceiros', '## Reexecução de Serviços por Terceiros

A reexecução de serviços por terceiros é uma opção que pode ser escolhida pelo consumidor ou fornecedor em caso de desavença comercial. Isso ocorre quando a fidúcia entre as partes se dissipe, tornando mais satisfatória a saída da terceirização da reexecução dos serviços.

### Conceitos
- **Fidúcia**: Relação de confiança e dependência entre duas pessoas ou entidades
- **Reexecução de Serviços**: Ação de reavaliar e reexecutar serviços realizados por um fornecedor
- **Terceirização**: A ação de delegar uma tarefa ou serviço para uma terceira pessoa ou empresa

### Referências legais
- Art. 20, § 1º da Lei nº 8.078/1990

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de fidúcia e sua importância na reexecução de serviços
- Conheça as hipóteses em que a fidúcia se dissipe e a terceirização da reexecução dos serviços é mais adequada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 20, § 1º da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T02:37:57.912875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=58", "doc_key": "3d84d68923c3741af962a8afb6d2f57a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e5b87a493bedb35549e5a4b5bb1aeb63f1788739abf0b46ab19fe85975d927d6'),
  ('cpiuris2025::5941e548086c100f855be5369986f6cb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fato do produto ou serviço', '## Fato do produto ou serviço

O fato do produto ou serviço é a ocorrência de danos oriundos de ausência de segurança do produto ou serviço que atingem ou põem em perigo o consumidor em sua integridade física ou moral.

### Conceitos
- **Vício**: Ocorre quando o produto ou serviço não se ajusta às expectativas razoáveis do consumidor.
- **Defeito**: A ausência de segurança do produto ou serviço que atinge ou põem em perigo o consumidor.
- **Acidente de consumo**: Sinônimo de fato do produto ou serviço

### Referências legais
- Art. 381 e seguintes do CPC/15

### Dicas de prova
- Diferenciar entre vício e defeito
- Entender a classificação dos defeitos (concepção, fabricação, comercialização)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 381 e seguintes do CPC/15"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:37:59.567041+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=59", "doc_key": "5941e548086c100f855be5369986f6cb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '13b130f3c85bb4a455ac72483f844c3d31dc544fb19a07b4598b3f9006eb132b'),
  ('cpiuris2025::15dc7e3d82c721a42240c58e134490cc', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dever de reparação de danos morais e materiais', '## Dever de reparação de danos morais e materiais

O consumidor tem direito à reparação integral por violação à sua integridade física ou moral em decorrência de um defeito de segurança de um produto.

### Conceitos
- **Dever de reparação**: obrigação do fornecedor de reparar danos causados ao consumidor
- **Danos morais e materiais**: dano físico ou psicológico sofrido pelo consumidor
- **Nexo de causalidade**: relação lógica entre o dano e o produto ou serviço prestado

### Referências legais
- Art. 12, § 2º do CDC
- Art. 13 do CDC

### Dicas de prova
- Entenda a noção de nexo de causalidade
- Conheça as hipóteses em que o comerciante é responsável por danos causados ao consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.60 (2)", "page_number": 60, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12, § 2º do CDC", "Art. 13 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:39:58.576922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=60", "doc_key": "15dc7e3d82c721a42240c58e134490cc"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'be3a58db48f9ac860b2870e6dbeaf93e8788555bbbfb87a9711bb018ee7a52ee'),
  ('cpiuris2025::98a18d2e9f55dcabd343f1615f13dcb9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fato do produto', '## Fato do produto

O fato do produto é aquele que afeta a funcionalidade ou o serviço, sujeitando-se ao prazo decadencial do art. 26 do CDC.

### Conceitos
- **Vício do produto**: vício que afeta apenas a funcionalidade ou o serviço
- **Fato do produto**: vício que afeta a funcionalidade ou o serviço, sujeitando-se ao prazo decadencial
- **Prazo prescricional**: prazo dentro do qual deve ser exercida a ação do consumidor

### Referências legais
- Art. 26 do Código de Defesa do Consumidor
- REsp 1.176.323/SP

### Jurisprudência
- Tema repetitivo: fato do produto

### Dicas de prova
- Distinguir entre vício do produto e fato do produto
- Entender a importância do prazo prescricional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 26 do Código de Defesa do Consumidor", "REsp 1.176.323/SP"], "jurisprudence": ["Tema repetitivo: fato do produto"], "confidence": 0.8, "extracted_at": "2026-05-30T02:40:13.514513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=59", "doc_key": "98a18d2e9f55dcabd343f1615f13dcb9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '659eac85b911ca3b696bb1df09c3377bf02582d8feb49f692c670af6a616f006'),
  ('cpiuris2025::da4078655043078d6c98467bc75ca04d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fato do produto e reparação integral', '## Fato do produto e reparação integral

O fato do produto é considerado defeituoso quando não oferece a segurança esperada, levando-se em consideração as circunstâncias relevantes. O fornecedor é responsável pela reparação dos danos causados aos consumidores independentemente da existência de culpa.

### Conceitos
- **Reparação integral**: Princípio que visa compensar o consumidor com uma indenização que abrange tanto os danos materiais quanto morais.
- **Fato do produto**: Condição em que o produto não oferece a segurança esperada, levando-se em consideração as circunstâncias relevantes.

### Referências legais
- Art. 12 do CDC

### Jurisprudência
- Súmula 556/STJ

### Dicas de prova
- Entenda o princípio de reparação integral e como ele se aplica ao fato do produto.
- Identifique as circunstâncias relevantes que levam à consideração de um produto defeituoso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.60 (1)", "page_number": 60, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12 do CDC"], "jurisprudence": ["Súmula 556/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:40:21.025194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=60", "doc_key": "da4078655043078d6c98467bc75ca04d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6c4f8547f2c74685909ffbc34885d042c1fa0b53666ea0acf8fc792a071a57ad'),
  ('cpiuris2025::e8bd6cf7e9b575b55bdbbc29851c3b66', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Tempo de espera em instituições bancárias e responsabilidade pelo fato de serviço', '## Tempo de espera em instituições bancárias e responsabilidade pelo fato de serviço

A falta de tempo de espera não gera automaticamente dano moral. O CDC não estabelece normas para o tempo de espera, mas as leis municipais podem. A responsabilidade pelo fato de serviço é configurada quando há atraso, conforme prevê o artigo 14 do CDC.

### Conceitos
- **Dano moral**: prejuízo não material
- **Fato de serviço**: obrigação da instituição financeira de cumprir com uma obrigação
- **Responsabilidade pelo fato de serviço**: configuração do atraso como responsabilidade da instituição financeira
- **Tempo de espera**: ponto em que o consumidor espera por um serviço

### Referências legais
- Art. 14 do CDC
- Art. 4º, II do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre dano moral e prejuízo não material
- Entendimento do STJ sobre a responsabilidade pelo fato de serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 14 do CDC", "Art. 4º, II do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T02:42:23.870508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=61", "doc_key": "e8bd6cf7e9b575b55bdbbc29851c3b66"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3fae66924a3916a9f4a0f3aa54b6669d9a6916d3e0ad024b1303998950b234d7'),
  ('cpiuris2025::afcd0dfce44d750658b5b37d82b4a0ed', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Excludentes de Nexo de Causalidade', '## Excludentes de Nexo de Causalidade

A isenção de responsabilização nas hipóteses em que for comprovada a existência de hipótese que rompa o nexo de causalidade é permitida, conforme o CDC.

### Conceitos
- **Nexo de Causalidade**: Conexão lógica entre o dano e o produto ou serviço fornecido
- **Isenção de Responsabilização**: Exclusão da responsabilidade do fornecedor em determinadas hipóteses
- **Vício no Produto ou Serviço**: Falta ou defeito no produto ou serviço fornecido
- **Culpa Exclusiva**: Responsabilidade exclusiva do consumidor ou de terceiros

### Referências legais
- Art. 12, § 3º, do CDC
- Art. 14, § 3º, do CDC
- Súmula 398/STJ

### Jurisprudência
- REsp 1.962.275-GO
- AREsp 400.983/PB

### Dicas de prova
- Entenda a diferença entre comprovação de vício e comprovação de rompimento de nexo de causalidade
- Conheça as hipóteses em que o fornecedor não é responsabilizado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.62 (1)", "page_number": 62, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12, § 3º, do CDC", "Art. 14, § 3º, do CDC", "Súmula 398/STJ"], "jurisprudence": ["REsp 1.962.275-GO", "AREsp 400.983/PB"], "confidence": 0.8, "extracted_at": "2026-05-30T02:42:56.122004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=62", "doc_key": "afcd0dfce44d750658b5b37d82b4a0ed"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '93fe7fea8a8d414a761c1bcd6b1b19e49fc750ecfa18d096045af892d0d65b2a'),
  ('cpiuris2025::55d6d931a380b042b284755a417c30ef', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do Comerciante e Fato do Produto/Serviço', '## Responsabilidade do Comerciante e Fato do Produto/Serviço

A responsabilidade do comerciante por fato do produto ou serviço é subsidiária, mas pode ser condicionada às hipóteses do art. 13 do CDC. Em casos de fato do produto, o comerciante pode ter as mesmas obrigações dos demais coobrigados, como o fabricante.

### Conceitos
- **Responsabilidade subsidiária**: A responsabilidade do comerciante por fato do produto ou serviço é limitada às hipóteses previstas no art. 13 do CDC.
- **Fato do produto**: O comerciante responde pela reparação dos danos causados aos consumidores por defeitos relativos à qualidade do produto.
- **Fato do serviço**: O fornecedor de serviços responde independentemente da existência de culpa pelos danos causados aos consumidores por defeitos na prestação dos serviços.
- **Amplas solidariedade**: A responsabilidade do comerciante não segue a regra geral de ampla solidariedade, mas pode ser condicionada às hipóteses do art. 13 do CDC.

### Referências legais
- Art. 13 do CDC
- Súmula 1.016.278/STJ

### Jurisprudência
- AgInt no AREsp 1.016.278/RJ

### Dicas de prova
- Distinção entre responsabilidade subsidiária e ampla solidariedade
- Conhecimento do art. 13 do CDC e suas hipóteses', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 13 do CDC", "Súmula 1.016.278/STJ"], "jurisprudence": ["AgInt no AREsp 1.016.278/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:43:13.081473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=61", "doc_key": "55d6d931a380b042b284755a417c30ef"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ee1df28032db1f9a98b0e54cd5d5e217768e405a3a07c3ec1b4bf7e68d52f43d'),
  ('cpiuris2025::6757b8f9e815df33ecbb17d37f99a3d8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Rompimento de nexo de causalidade', '## Rompimento de nexo de causalidade

A existência de vício ou defeito é comprovada pelo fornecedor, exceto nos casos onde a ausência de defeito está ligada à caracterização do ato ilícito ou não há nexo de causalidade.

### Conceitos
- **Rompimento de nexo de causalidade**: Falta de conexão lógica entre a culpa e o dano
- **Ausência de defeito**: Não existência de vício ou falha no produto ou serviço
- **Hipótese de desgaste natural**: Caso em que o dano é resultado do uso normal e razoável

### Referências legais
- Art. 12, parágrafo 3º, inciso I e II
- Art. 14, parágrafo 3º, inciso I

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ausência de defeito e hipótese de desgaste natural
- Conheça as hipóteses que constituem rompimento de nexo de causalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.62 (2)", "page_number": 62, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12, parágrafo 3º, inciso I e II", "Art. 14, parágrafo 3º, inciso I"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T02:44:40.141337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=62", "doc_key": "6757b8f9e815df33ecbb17d37f99a3d8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '307bbda7aae5842d055b07689e43e1e4eb3001bcf6eca988fcc7dcbbbc3bca3c'),
  ('cpiuris2025::170fadf40ad2ec27cbc9c594b759c2de', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Culpa exclusiva de terceiro e rompimento de nexo de causalidade', '## Culpa exclusiva de terceiro e rompimento de nexo de causalidade

A culpa exclusiva de terceiro não se aplica a situações onde uma pessoa alheia ao serviço ou produto contratado contribui para o defeito do produto. O STJ entende que o fato de terceiro só exclui o nexo de causalidade quando é inevitável e imprevisível.

### Conceitos
- **Culpa exclusiva de terceiro**: Situção onde uma pessoa alheia ao serviço ou produto contratado contribui para o defeito do produto
- **Rompimento de nexo de causalidade**: Falta de ligação causal entre a culpa do consumidor e o dano causado
- **Caso fortuito ou força maior**: Hipótese em que o STJ entende rompido o nexo de causalidade

### Referências legais
- Art. 7º, parágrafo único; 25, § 2º; e 34 do CDC

### Jurisprudência
- REsp 685.662/RJ
- AgRg no REsp 1.551.484/SP

### Dicas de prova
- Entenda a diferença entre culpa exclusiva de terceiro e caso fortuito ou força maior
- Conheça as hipóteses que excluem o nexo de causalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, parágrafo único; 25, § 2º; e 34 do CDC"], "jurisprudence": ["REsp 685.662/RJ", "AgRg no REsp 1.551.484/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:45:46.217831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=63", "doc_key": "170fadf40ad2ec27cbc9c594b759c2de"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8e0dc60048920fd0ccce114500d7c3690636a2c2c137365f23cc133de962934a'),
  ('cpiuris2025::9a16b42d078299a7a464ee543c182178', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do Fornecedor', '## Responsabilidade do Fornecedor

A responsabilidade do fornecedor é afetada pela culpa exclusiva do consumidor ou de terceiros, mas a aplicação da culpa concorrente não rompe o nexo de causalidade e pode reduzir a condenação do fornecedor.

### Conceitos
- **Culpa Exclusiva**: A responsabilidade exclusiva do consumidor ou de terceiros por um dano causado.
- **Culpa Concorrente**: A responsabilidade compartilhada entre o consumidor e terceiros por um dano causado.
- **Nexo de Causalidade**: A conexão lógica entre a ação do fornecedor e o dano causado ao consumidor.
- **Responsabilidade Objetiva**: A responsabilidade do fornecedor sem a necessidade de provar a culpa exclusiva do consumidor.

### Referências legais
- Art. 945 do Código Civil

### Jurisprudência
- REsp 287.849/SP
- REsp 1.651.663-SP
- REsp 1.898.812-SP

### Dicas de prova
- Entenda a diferença entre culpa exclusiva e concorrente.
- Conheça o conceito de nexo de causalidade em relação à responsabilidade do fornecedor.
- Aplique a responsabilidade objetiva no caso de dano causado ao consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 945 do Código Civil"], "jurisprudence": ["REsp 287.849/SP", "REsp 1.651.663-SP", "REsp 1.898.812-SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:45:55.987508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=63", "doc_key": "9a16b42d078299a7a464ee543c182178"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '222b1c8c8a7604095367fdd2eec5ac7ab9d84b3f2d4b1c1a19884d995241a3f0'),
  ('cpiuris2025::47945cc52ccdb0a9ffa2351ac2e71ca4', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Caso Fortuito e Força Maior', '## Caso Fortuito e Força Maior

O caso fortuito e a força maior não são considerados causas excludentes da responsabilidade, de acordo com os arts. 12, § 3º, e 14, § 3º. A jurisprudência do STJ passou a aceitar essas hipóteses como aptas ao rompimento do nexo de causalidade, mas apenas nos casos fortuitos externos.

### Conceitos
- **Caso Fortuito**: ocorrência imprevisível e alheia à vontade do consumidor
- **Força Maior**: ocorrência imprevisível e fora do controle do consumidor
- **Nexo de Causalidade**: conexão lógica entre o dano e a atividade do ofensor

### Referências legais
- Art. 12, § 3º, Código de Defesa do Consumidor
- Art. 14, § 3º, Código de Defesa do Consumidor

### Jurisprudência
- Súmula 479 do STJ

### Dicas de prova
- Entenda a distinção entre fortuito interno e fortuito externo
- Conheça a tendência da jurisprudência do STJ em relação às fraudes bancárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.64 (1)", "page_number": 64, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12, § 3º, Código de Defesa do Consumidor", "Art. 14, § 3º, Código de Defesa do Consumidor"], "jurisprudence": ["Súmula 479 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:47:26.629318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=64", "doc_key": "47945cc52ccdb0a9ffa2351ac2e71ca4"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '20da98938c81a124e7a7eec5008fed927cd9d8705466e881d3d61202f0b5941b'),
  ('cpiuris2025::fdb9721c228d0ad0e96ccb7800e4f84b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fortuito Interno e Externo', '## Fortuito Interno e Externo

O fortuito interno é considerado uma hipótese de exclusão da responsabilidade das instituições financeiras, transporte público e serviços de hospedagem, enquanto o fortuito externo não guarda ligação com a atividade desenvolvida pelo ofensor.

### Conceitos
- **Fortuito Interno**: Dano que ocorre como resultado de uma atividade ou condição da parte responsável
- **Fortuito Externo**: Dano que ocorre sem ligação com a atividade desenvolvida pelo ofensor

### Referências legais
- Art. 138, § 2º, da Lei nº 8.078/1990

### Jurisprudência
- REsp 1.098.236/RJ
- AREsp 613.850/SP
- STJ. 4ª Turma. AgInt no AREsp 1.379.845/BA, Rel. Min. Raul Araújo

### Dicas de prova
- Diferenciar entre fortuito interno e externo
- Entender a ligação entre o dano e a atividade desenvolvida pelo ofensor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 138, § 2º, da Lei nº 8.078/1990"], "jurisprudence": ["REsp 1.098.236/RJ", "AREsp 613.850/SP", "STJ. 4ª Turma. AgInt no AREsp 1.379.845/BA, Rel. Min. Raul Araújo"], "confidence": 0.8, "extracted_at": "2026-05-30T02:48:20.331388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=65", "doc_key": "fdb9721c228d0ad0e96ccb7800e4f84b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5d3049036905fe3be0c985dee7c03b98e958e19896ecd9a03997e1d5dd93036d'),
  ('cpiuris2025::bc565f697351d04e78668080282243a8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dever de Vigilância e Segurança das Instituições Financeiras', '## Dever de Vigilância e Segurança das Instituições Financeiras

As instituições financeiras têm o dever de vigilância para identificar movimentações suspeitas em contas de consumidores, utilizando algoritmos que apontam transações anormais. Além disso, elas são responsáveis solidárias pelos danos decorrentes de falha na prestação do serviço, como no caso de portabilidade de crédito consignado.

### Conceitos
- **Dever de Vigilância**: obrigação das instituições financeiras para identificar movimentações suspeitas em contas de consumidores
- **Segurança das Instituições Financeiras**: dever das instituições financeiras para proteger os consumidores contra fraudes e golpes
- **Responsabilidade Solidária**: obrigação das instituições financeiras de ser responsáveis pelos danos decorrentes de falha na prestação do serviço

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- REsp 2.052.228-DF
- REsp 1.771.984/RJ

### Dicas de prova
- Pergunte sobre o dever de vigilância e segurança das instituições financeiras em relação aos consumidores.
- Entenda a responsabilidade solidária das instituições financeiras nos casos de falha na prestação do serviço.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.64 (2)", "page_number": 64, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["REsp 2.052.228-DF", "REsp 1.771.984/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:48:35.842015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=64", "doc_key": "bc565f697351d04e78668080282243a8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b38b069cf706460d50f7b4ece17949ba5c24975f844f771a3f20f5684dde92fa'),
  ('cpiuris2025::578665fe2158d43fedd39594c81f6a04', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Fortuito Externo', '## Fortuito Externo

O fortuito externo é considerado quando o dano ocorre fora da agência bancária ou estabelecimento comercial, ou quando o dano não está relacionado à atividade típica de garantir a segurança dos clientes.

### Conceitos
- **Nexo de Causalidade**: Conexão lógica entre o ato ilícito e o dano causado
- **Fortuito Interno**: Dano que ocorre como resultado direto do ato ilícito
- **Fortuito Externo**: Dano que ocorre fora da agência bancária ou estabelecimento comercial, ou quando o dano não está relacionado à atividade típica de garantir a segurança dos clientes

### Referências legais
- Art. 49, § 2º, da Lei nº 8.078/1990

### Jurisprudência
- REsp 1.748.295/SP
- REsp 1.936.743/SP
- REsp 1.749.941/PR
- REsp 1.786.157/SP
- REsp 1284962/MG
- REsp 1440756/RJ

### Dicas de prova
- Distinção entre fortuito interno e externo é fundamental para determinar a responsabilidade da concessionária.
- O nexo de causalidade é essencial para estabelecer a relação entre o ato ilícito e o dano causado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 2º, da Lei nº 8.078/1990"], "jurisprudence": ["REsp 1.748.295/SP", "REsp 1.936.743/SP", "REsp 1.749.941/PR", "REsp 1.786.157/SP", "REsp 1284962/MG", "REsp 1440756/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:50:18.160755+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=65", "doc_key": "578665fe2158d43fedd39594c81f6a04"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2e46d3309d5c26a9792b10963dc059a036b5d251ceeff32beda5ff8971ac423b'),
  ('cpiuris2025::9ad196b33a0eab3d6102473671f925e4', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Defeituos nos produtos e serviços', '## Defeituos nos produtos e serviços

O Direito do Consumidor considera defeituosos apenas os produtos e serviços que não oferecem a segurança legítima, levando-se em consideração as circunstâncias relevantes.

### Conceitos
- **periculosidade à saúde ou segurança**: Condição necessária para a responsabilidade civil
- **defeituos**: Produtos e serviços que não oferecem a segurança legítima
- **vulnerabilidade**: Princípio do Direito do Consumidor que prioriza a proteção do consumidor
- **reparação integral**: Conceito que abrange a compensação do dano causado ao consumidor

### Referências legais
- Art. 10 do CDC
- Art. 4º, I do CDC
- Art. 6º, VI do CDC

### Jurisprudência
- REsp 1.774.372/RS
- Enunciado nº 43 da I Jornada de Direito Civil

### Dicas de prova
- Entenda a noção de periculosidade à saúde ou segurança e sua relação com a responsabilidade civil
- Conheça as circunstâncias relevantes que levam em consideração a avaliação do defeituos nos produtos e serviços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 10 do CDC", "Art. 4º, I do CDC", "Art. 6º, VI do CDC"], "jurisprudence": ["REsp 1.774.372/RS", "Enunciado nº 43 da I Jornada de Direito Civil"], "confidence": 0.8, "extracted_at": "2026-05-30T02:50:52.611918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=66", "doc_key": "9ad196b33a0eab3d6102473671f925e4"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7e6556ff11a6810579c36a7cf6b0491776933cc8f70c9b65a0b8de8ff93437e5'),
  ('cpiuris2025::8f1279af0a16428846fc8b421b20df50', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Teoria da Qualidade e Excludentes de Responsabilidade', '## Teoria da Qualidade e Excludentes de Responsabilidade

Resumo objetivo: Este trecho aborda a teoria da qualidade, excludentes de responsabilidade e a aceitação da teoria do risco do desenvolvimento como excludente da responsabilidade do fornecedor.

### Conceitos
- **Fortuito Interno**: Roubo ou furto ocorrido em estabelecimento privado
- **Fortuito Externo**: Roubo ou furto ocorrido nas ruas
- **Teoria do Risco do Desenvolvimento**: Aceitação da circunstância de o defeito apurado derivar de fato que o fornecedor não poderia ter conhecimento, de acordo com as tecnologias disponíveis
- **Excludente de Responsabilidade**: Condição que exclui a responsabilidade do fornecedor em determinadas situações

### Referências legais
- Art. 18 da Lei nº 8.078/1990
- Súmula 354 do STJ

### Jurisprudência
- REsp 1.321.739/SP
- EREsp 1.431.606/SP
- REsp 2.114.079/RS

### Dicas de prova
- Distinção entre fortuito interno e externo
- Entendimento da teoria do risco do desenvolvimento como excludente de responsabilidade
- Importância da aceitação das tecnologias disponíveis no momento do fornecimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18 da Lei nº 8.078/1990", "Súmula 354 do STJ"], "jurisprudence": ["REsp 1.321.739/SP", "EREsp 1.431.606/SP", "REsp 2.114.079/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T02:51:05.736576+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=66", "doc_key": "8f1279af0a16428846fc8b421b20df50"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2d5f33d614a5cea4ee9c81e88e1ff8990754f98c889aedd36a4e9f18e2647321'),
  ('cpiuris2025::2bff5047fd7a655bd55cf0d3753a309a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Recall', '## Recall

O recall é o procedimento pelo qual o fornecedor comunica a existência de defeito ou mau funcionamento em um produto ou serviço, obrigando-se a corrigir o problema e comunicar às autoridades competentes e consumidores.

### Conceitos
- **Recall**: procedimento pelo qual o fornecedor comunica a existência de defeito ou mau funcionamento em um produto ou serviço
- **Obrigação do fornecedor**: obrigação de comunicar as autoridades competentes e consumidores sobre a existência de defeito ou mau funcionamento
- **Portaria 618/2019**: regulamenta o procedimento de divulgação de chamamento dos consumidores

### Referências legais
- Art. 10, § 1º, do CDC
- Portaria 618/2019

### Jurisprudência
- REsp 1.261.067/RJ
- REsp 287.849/SP

### Dicas de prova
- Entenda a importância do recall e suas implicações para o fornecedor
- Conheça a Portaria 618/2019 e sua relevância no procedimento de recall', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 10, § 1º, do CDC", "Portaria 618/2019"], "jurisprudence": ["REsp 1.261.067/RJ", "REsp 287.849/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:51:33.138334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=67", "doc_key": "2bff5047fd7a655bd55cf0d3753a309a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd5af456565580818fc79b82d7fe3ea723c525bf894870ed99684e623bcfa6e07'),
  ('cpiuris2025::2796b4680d0979dc63a6be7eb8c307a2', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Bystanders e consumidores', '## Bystanders e consumidores

As vítimas de acidentes de consumo são consideradas consumidoras, exceto em casos específicos.

### Conceitos
- **bystander**: vítima de um acidente de consumo
- **consumidor**: pessoa que adquire um produto ou serviço
- **terceiro**: pessoa não envolvida diretamente no contrato

### Referências legais
- Art. 50 da Lei nº 8.078/1990

### Jurisprudência
- REsp 181.580/SP
- REsp 1.268.743/RJ
- REsp 1.125.276/RJ

### Dicas de prova
- Distinção entre bystanders e consumidores
- Importância da seção do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 da Lei nº 8.078/1990"], "jurisprudence": ["REsp 181.580/SP", "REsp 1.268.743/RJ", "REsp 1.125.276/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T02:53:21.535221+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=68", "doc_key": "2796b4680d0979dc63a6be7eb8c307a2"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '262f849c281fd80f3147898ab87e65e8cc6c1c9254ac2603de2fea6f19f22fe0'),
  ('cpiuris2025::4b24fc2337152f77dbc2ce58043304c9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desvio Produtivo do Consumidor', '## Desvio Produtivo do Consumidor

A questão do desvio produtivo do consumidor é debatida sobre a teoria que trata das hipóteses em que o consumidor renuncia seu tempo para solucionar problemas criados pelo fornecedor, considerados atos ilícitos.

### Conceitos
- **Desvio Produtivo**: Teoria que trata das hipóteses em que o consumidor renuncia seu tempo para solucionar problemas criados pelo fornecedor
- **Dano Moral**: Prejuízo emocional sofrido pelo consumidor ao passar por um calvário para obter o estorno pretendido
- **Frustração em Desfavor do Consumidor**: Ocorrência de um vício grave no produto ou serviço que não pode ser reparado

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Jurisprudência
- AREsp 1.260.458/SP
- AREsp 1.241.259/SP
- REsp 1.737.412/SE

### Dicas de prova
- Distinção entre dano moral e frustração em desfavor do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": ["AREsp 1.260.458/SP", "AREsp 1.241.259/SP", "REsp 1.737.412/SE"], "confidence": 0.8, "extracted_at": "2026-05-30T02:53:59.992224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=67", "doc_key": "4b24fc2337152f77dbc2ce58043304c9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a50d2398b5fc685517479206ac2d0f093f4b920329b99eb8338321c04ca66816'),
  ('cpiuris2025::4b06f0af1730efb8ace3733f2b7ed7de', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do profissional médico e hospital em caso de acidente de consumo', '## Responsabilidade do profissional médico e hospital em caso de acidente de consumo

O regime de responsabilização dos profissionais liberais em caso de acidente de consumo possui natureza subjetiva, exigindo comprovação de culpa para reconhecimento. O hospital é responsável objetivamente pelos serviços prestados, mas só responderá solidariamente pelo erro se houver comprovação de culpa.

### Conceitos
- **Responsabilidade Subjetiva**: Exige comprovação de culpa para reconhecimento
- **Responsabilidade Objética**: Responsabilidade do hospital pelos serviços prestados, sem necessidade de comprovação de culpa
- **Causalidade**: Nexo necessário entre o erro e o dano para que haja responsabilização
- **Solidariedade**: Responsabilidade conjunta do hospital e do profissional médico em caso de erro cometido por um deles

### Referências legais
- Art. 14, § 4º do CDC
- REsp 985.888/SP
- REsp 1.145.728/MG
- REsp 764.001/PR
- REsp 605.435
- REsp 880.349
- REsp 866.371/RS

### Jurisprudência
- STJ
- REsp 985.888/SP
- REsp 1.145.728/MG
- REsp 764.001/PR
- REsp 605.435
- REsp 880.349
- REsp 866.371/RS

### Dicas de prova
- Distinção entre responsabilidade subjetiva e objetiva
- Importância da causalidade para a responsabilização
- Reconhecimento da solidariedade no caso de erro cometido por um profissional sob supervisão do outro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 14, § 4º do CDC", "REsp 985.888/SP", "REsp 1.145.728/MG", "REsp 764.001/PR", "REsp 605.435", "REsp 880.349", "REsp 866.371/RS"], "jurisprudence": ["STJ", "REsp 985.888/SP", "REsp 1.145.728/MG", "REsp 764.001/PR", "REsp 605.435", "REsp 880.349", "REsp 866.371/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T02:55:06.467796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=68", "doc_key": "4b06f0af1730efb8ace3733f2b7ed7de"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '70d0536e81c5df2d1753c76eeab21f284979e461a66f6aa4cb8dff355560d8ef'),
  ('cpiuris2025::5b0e347a5adbfe9cada480c895e70854', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Danos Morais Considerados In Re Ipsa', '## Danos Morais Considerados In Re Ipsa

São considerados danos morais a inclusão/manutenção em cadastros negativos, devolução indevida de cheque, publicação não autorizada de imagem e operações financeiras sem consentimento.

### Conceitos
- **Danos Morais**: prejuízo à dignidade ou ao honorário da pessoa
- **In Re Ipsa**: considerados sem necessidade de prova do prejuízo específico
- **Consentimento**: necessária para operações financeiras
- **Portabilidade de Crédito**: operação que envolve a transferência de crédito

### Referências legais
- Súmula 370/STJ
- Súmula 388/STJ
- Súmula 403/STJ

### Jurisprudência
- REsp 432.177
- REsp 597.814
- REsp 1.097.226

### Dicas de prova
- Entenda a noção de danos morais e como são considerados in re ipsa
- Conheça as instituições financeiras responsáveis por operações sem consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito do Consumidor", "legal_refs": ["Súmula 370/STJ", "Súmula 388/STJ", "Súmula 403/STJ"], "jurisprudence": ["REsp 432.177", "REsp 597.814", "REsp 1.097.226"], "confidence": 0.8, "extracted_at": "2026-05-30T02:56:03.426105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=69", "doc_key": "5b0e347a5adbfe9cada480c895e70854"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f3ebac9c15b27eb4303f61b77636fab9dbe94bb9682bc7126775451a11034992'),
  ('cpiuris2025::57ad4bc0b241fc02c51ea11eefe3150d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Viabilidade de cumulação entre pretensões fundadas no fato e no vício do produto', '## Viabilidade de cumulação entre pretensões fundadas no fato e no vício do produto

A cumulação de regimes jurídicos para a ocorrência do vício e do fato do produto é viável, de acordo com os arts. 18, II; 19, IV; e 20, II do CDC.

### Conceitos
- **Cumulação de regimes**: A aplicação simultânea de dispositivos jurídicos que regem diferentes situações
- **Reparação integral**: O direito de receber uma indenização que reflita todas as perdas e danos sofridas
- **Vulnerabilidade**: A proteção especial concedida a certas categorias de pessoas, como consumidores, em razão de sua situação jurídica vulnerável
- **Fato e vício do produto**: As duas situações que podem ser objeto de uma única ação judicial, com base no mesmo evento

### Referências legais
- Art. 17 do CDC
- Art. 18, II do CDC
- Art. 19, IV do CDC
- Art. 20, II do CDC

### Jurisprudência
- REsp 567.333/RN
- REsp 1.162.649/SP
- REsp 1.370.139/SP
- REsp 1.967.728/SP

### Dicas de prova
- Entenda a diferença entre fato e vício do produto
- Conheça os arts. 17, 18, 19 e 20 do CDC
- Aprenda sobre a reparação integral e a vulnerabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 17 do CDC", "Art. 18, II do CDC", "Art. 19, IV do CDC", "Art. 20, II do CDC"], "jurisprudence": ["REsp 567.333/RN", "REsp 1.162.649/SP", "REsp 1.370.139/SP", "REsp 1.967.728/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T02:56:29.372143+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=69", "doc_key": "57ad4bc0b241fc02c51ea11eefe3150d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '64fc15dcf662a607659d9b12ecd433aaa5875da519d5544e91d2abc70d07cfbf'),
  ('cpiuris2025::c43f8edc9411c0bf07a8807ac7699cf3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade solidária pelos danos decorrentes de falha na prestação do serviço', '## Responsabilidade solidária pelos danos decorrentes de falha na prestação do serviço

O consumidor pode exigir responsabilidade solidária dos fornecedores em caso de falha na prestação do serviço, além de outros danos morais.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade conjunta de múltiplos fornecedores por uma falha na prestação do serviço.
- **Danos Morais**: Prejuízos emocionais e psicológicos sofridos pelo consumidor como resultado da falha na prestação do serviço.

### Referências legais
- Art. 49, § 4º, da Lei nº 8.078/1990
- Súmula 595/STJ

### Jurisprudência
- REsp 1.771.984/RJ
- REsp 1.733.136/RO
- REsp 1.584.465/MG

### Dicas de prova
- Distinção entre danos morais in re ipsa e outros danos morais.
- Importância de provar os prejuízos ao consumidor em caso de atraso de voo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.70", "page_number": 70, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 4º, da Lei nº 8.078/1990", "Súmula 595/STJ"], "jurisprudence": ["REsp 1.771.984/RJ", "REsp 1.733.136/RO", "REsp 1.584.465/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T02:57:16.265787+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=70", "doc_key": "c43f8edc9411c0bf07a8807ac7699cf3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9f7069bbda0e2a22622fa228aff6a3276707798f36fa0a8be46ccf2d923344ae'),
  ('cpiuris2025::ae4e10f3a980147473e7f688c6845478', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do Comerciante em Caso de Fato do Produto', '## Responsabilidade do Comerciante em Caso de Fato do Produto

A responsabilidade do comerciante é subsidiária e ocorre nos casos definidos no Art. 13 do CDC, sendo subsidiária à responsabilidade do fabricante ou produtor.

### Conceitos
- **Responsabilidade Subsidiária**: Ocorre quando o comerciante não pode ser identificado como o fabricante ou produtor do produto.
- **Art. 13 do CDC**: Define a responsabilidade do comerciante em caso de fato do produto

### Referências legais
- Art. 13 do CDC

### Dicas de prova
- Pergunta sobre responsabilidade do comerciante em caso de fato do produto
- Importância da identificação do fabricante ou produtor no Art. 13 do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 13 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:57:53.702510+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=71", "doc_key": "ae4e10f3a980147473e7f688c6845478"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8ca24b08da01947491e6a447b096565869f735b909b18aa815bcb0aea7effc2d'),
  ('cpiuris2025::e09a2bdf973f6e660574958a4720263b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obrigação de informação ao consumidor', '## Obrigação de informação ao consumidor

A lei estabelece que os fornecedores devem dar as informações necessárias e adequadas sobre seus produtos e serviços, exceto em casos normais e previsíveis. A periculosidade inerente é aceita.

### Conceitos
- **Obrigação de informação ao consumidor**: Dever do fornecedor de informar ao consumidor
- **Normas e previsíveis**: Condições que não representam risco para a saúde ou segurança do consumidor

### Referências legais
- Art. 8º do CDC

### Dicas de prova
- Entenda o conceito de periculosidade inerente e como ela é tratada pela lei.
- Não confunda a norma com a previsibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 8º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:58:13.334056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=71", "doc_key": "e09a2bdf973f6e660574958a4720263b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9af8d9aeebd6d675efb995aafa5ef84a0e9192340ed197b1cf9ebbb94e9d9c24'),
  ('cpiuris2025::f799e480ec70364f598db11d4a2a4ccf', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do Fornecedor por Defeitos no Produto', '## Responsabilidade do Fornecedor por Defeitos no Produto

O fornecedor responde objetivamente pelos danos causados aos consumidores por defeitos nos produtos, independentemente da existência de culpa.

### Conceitos
- **Responsabilidade objetiva**: A responsabilidade do fornecedor é objetiva, não dependendo da existência de culpa.
- **Teoria do risco integral**: Não é aplicada no CDC
- **Nexo de causalidade**: Obrigatório para a responsabilidade pessoal dos profissionais liberais

### Referências legais
- Art. 12 do CDC
- Art. 14 do CDC

### Dicas de prova
- Distinção entre fato do produto e acidente de consumo
- Importância da responsabilidade objetiva no CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.72", "page_number": 72, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 12 do CDC", "Art. 14 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T02:59:03.759845+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=72", "doc_key": "f799e480ec70364f598db11d4a2a4ccf"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd61db06f4b2b118915688dbfde54a7a7f622f310f1ecad6cc8fbfd036dd4e86f'),
  ('cpiuris2025::43d5f47d7ba1c8c02de65c58822203a4', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prazos Extintivos no CDC', '## Prazos Extintivos no CDC

Resumo objetivo: A aplicação dos prazos extintivos do CDC é objeto de interpretação restritiva pelo STJ, limitando sua aplicabilidade a casos técnicamente comprovados.

### Conceitos
- **Prazo Extintivo**: Período dentro do qual deve ser exercida uma ação
- **Interpretação Restritiva**: Aferição de que um texto jurídico deve ser interpretado de forma mais restritiva do que sua redação literal
- **STJ**: Superior Tribunal de Justiça
- **CDC**: Código de Defesa do Consumidor

### Referências legais
- Art. 27 do CDC

### Jurisprudência
- Súmula 643/STJ

### Dicas de prova
- Entenda a diferença entre interpretação restritiva e literal.
- Conheça o papel do STJ na aplicação dos prazos extintivos do CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 27 do CDC"], "jurisprudence": ["Súmula 643/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:00:05.810661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=74", "doc_key": "43d5f47d7ba1c8c02de65c58822203a4"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5cfb67f7200a23b40129b178e7b828aada5ca5709f0c60298a6278b720c62c74'),
  ('cpiuris2025::055770f89e03b87bdece4e1beee5be77', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prescrição e Decadência no CDC', '## Prescrição e Decadência no CDC

O Código de Defesa do Consumidor estabelece prazos decadenciais e prescricionais para garantia legal, distinguindo entre vício e fato do produto.

### Conceitos
- **Prescrição**: Processo pelo qual a pretensão é extinta sem prejuízo ou consequência necessária para o direito material subjacente.
- **Decadência**: Extinção do direito que fundamenta a causa de pedir, de modo definitivo.
- **Garantia Legal**: Direito do consumidor à reparação pelo fato e pelo vício do produto.
- **Prazo Decadencial**: Prazo dentro do qual o consumidor pode exigir a reparação por um vício ou fato do serviço.
- **Vício**: Fato que caracteriza a inadaptação do produto ao seu uso normal.
- **Fato**: Ocorrencia de um evento que afeta o direito do consumidor.

### Referências legais
- Art. 24 do CDC
- Art. 26 do CDC
- Art. 27 do CDC

### Dicas de prova
- Entenda a distinção entre prescrição e decadência.
- Conheça os prazos decadenciais e prescricionais estabelecidos no CDC.
- Identifique o conceito de vício e fato no contexto do direito do consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 24 do CDC", "Art. 26 do CDC", "Art. 27 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:00:51.733638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=74", "doc_key": "055770f89e03b87bdece4e1beee5be77"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8f479e1f3d21ff7b1777af1c9e1a9a506ce52fe11967727c5c9074ff2d5fe93e'),
  ('cpiuris2025::d2bdfc04386de46df375d8e86c4e767e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prazos prescricionais no CDC', '## Prazos prescricionais no CDC

O texto discute os prazos prescricionais previstos no Código Civil e no Código de Defesa do Consumidor, bem como a aplicação desses prazos em diferentes situações.

### Conceitos
- **Prazo prescricional**: O período durante o qual uma ação pode ser iniciada
- **Decadência**: A perda do direito de agir em um processo ou ação
- **Código Civil**: A legislação civil brasileira
- **Código de Defesa do Consumidor**: A legislação que protege os consumidores

### Referências legais
- Art. 205 do CC/02
- Art. 206, § 3º, V do CC/02

### Jurisprudência
- Súmula 477 do STJ
- AgInt no AREsp 1.281.594
- AgInt no AREsp 606.001/MG
- REsp 1.113.403/RJ
- REsp 1.512.465/RS
- REsp 574.947/BA
- REsp 1.369.579-PR

### Dicas de prova
- Entenda a diferença entre prazo prescricional e decadência
- Conheça as regras para aplicação dos prazos prescricionais no CDC
- Aprenda a distinguir entre situações que aplicam o prazo decenal ou genérico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 205 do CC/02", "Art. 206, § 3º, V do CC/02"], "jurisprudence": ["Súmula 477 do STJ", "AgInt no AREsp 1.281.594", "AgInt no AREsp 606.001/MG", "REsp 1.113.403/RJ", "REsp 1.512.465/RS", "REsp 574.947/BA", "REsp 1.369.579-PR"], "confidence": 0.8, "extracted_at": "2026-05-30T03:01:52.710213+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=75", "doc_key": "d2bdfc04386de46df375d8e86c4e767e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '643bb535a928e43e003627e10bd4e55cb7736a47a3c3d04f01023f2aea1382eb'),
  ('cpiuris2025::5751636a74e564749a51bf6862d2c6a2', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prazos Prescricionais para Ações Indenizatórias', '## Prazos Prescricionais para Ações Indenizatórias

Os prazos prescricionais para ações indenizatórias por danos materiais decorrentes de vícios de qualidade e quantidade do imóvel adquirido pelo consumidor são aplicados conforme o art. 205 do CC/02, com exceção dos casos de reembolso de despesas médico-hospitalares, que têm prazo decenal.

### Conceitos
- **Decadencial**: Prazo prescricional de 10 anos
- **Vício aparente**: Compromete a segurança do consumidor
- **Prazo decenal**: Prazo prescricional de 1 ano para reembolso de despesas médico-hospitalares

### Referências legais
- Art. 205 CC/02
- REsp 1.161.941/DF
- REsp 1.534.831/DF

### Jurisprudência
- REsp 1.756.283/SP
- REsp 1.591.223/PR

### Dicas de prova
- Diferenciar entre decadencial e prazo decenal
- Entender a aplicação do art. 205 do CC/02 em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 205 CC/02", "REsp 1.161.941/DF", "REsp 1.534.831/DF"], "jurisprudence": ["REsp 1.756.283/SP", "REsp 1.591.223/PR"], "confidence": 0.8, "extracted_at": "2026-05-30T03:02:21.577644+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=75", "doc_key": "5751636a74e564749a51bf6862d2c6a2"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7ea769428d23d393416fb5ee16163b032a72f88c89b84fed3a3244a8311271db'),
  ('cpiuris2025::e44bb31887948615dd3d8036b7131490', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prazo para apurar vícios ou defeitos em produtos duráveis', '## Prazo para apurar vícios ou defeitos em produtos duráveis

O prazo para apurar vícios ou defeitos em produtos duráveis é questionado, especialmente após a aquisição de garantia complementar. A doutrina apresenta divergências e o STJ não prover definitivamente o tema.

### Conceitos
- **Decadência**: O período durante o qual uma ação pode ser iniciada
- **Garantia Complementar**: Contrato adicional que protege o consumidor contra defeitos ou vícios nos produtos
- **Vício em Produtos Duráveis**: Defeito ou problema no produto que pode ser apurado após a garantia expirar

### Referências legais
- Art. 26, § 2º, do CDC
- Art. 207 do CC/02

### Dicas de prova
- Entenda a noção de decadência e como ela se aplica ao direito do consumidor
- Conheça as diferentes formas de garantia complementar e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 26, § 2º, do CDC", "Art. 207 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:03:51.669721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=76", "doc_key": "e44bb31887948615dd3d8036b7131490"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a55004fc9cebc62c8df440458eccdc3d292612e35fe5f274a3f4a535da249503'),
  ('cpiuris2025::f748a39af9d5647b176de2e31eebd4c9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prazo Prescricional e Decadência no CDC', '## Prazo Prescricional e Decadência no CDC

O prazo prescricional para exercício de pretensão do consumidor em face do segurador começa a correr a partir do conhecimento do dano e sua autoria, conforme arts. 26 e 27 do CDC.

### Conceitos
- **Prazo Prescricional**: Período durante o qual uma pretensão pode ser exercida sem perda de direito
- **Decadência**: Fim do prazo prescricional para exercício de pretensão
- **Vício Oculto**: Defeito ou problema no produto que só se manifesta após certo tempo de uso
- **Conhecimento do Dano**: O momento em que o consumidor toma ciência da existência do vício ou defeito do produto
- **Teoria da Ação Nata**: Teoria jurídica que define o termo inicial do prazo prescricional como o momento em que a pretensão surge
- **Vida Útil**: Período durante o qual um produto pode ser utilizado sem perda de qualidade ou funcionalidade
- **Garantia Legal**: Direito do consumidor à reparação de defeitos ou vicios no produto
- **Garantia Contratual**: Cláusula contratual que estende a garantia legal

### Referências legais
- Art. 26, §1º, II, ''b'' do CDC
- Art. 27 do CDC
- Art. 31 do CDC
- Art. 50 do CDC

### Jurisprudência
- REsp 1.737.992/RO
- REsp 1.303.374/ES
- REsp 984.106/SC

### Dicas de prova
- Entenda a diferença entre prazo prescricional e decadência
- Conheça a teoria da ação nata e como ela se aplica ao CDC
- Identifique o momento em que o consumidor toma ciência do dano e sua autoria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 26, §1º, II, ''b'' do CDC", "Art. 27 do CDC", "Art. 31 do CDC", "Art. 50 do CDC"], "jurisprudence": ["REsp 1.737.992/RO", "REsp 1.303.374/ES", "REsp 984.106/SC"], "confidence": 0.8, "extracted_at": "2026-05-30T03:04:12.360219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=76", "doc_key": "f748a39af9d5647b176de2e31eebd4c9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f83a37494576f61c42551efafe60e0dd0e7174de23246e29498a57cd1c1ca220'),
  ('cpiuris2025::2b97e1181f45b2e423e12a922c5687de', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prescrição e Decadência no CDC', '## Prescrição e Decadência no CDC

A reclamação do consumidor deve ser formulada até a resposta negativa do fornecedor, que deve ser transmitida de forma inequívoca. A prescrição é suspenso até o encerramento da investigação pelo MP em caso de instauração de Inquérito Civil.

### Conceitos
- **Reclamação**: Formulação do consumidor sobre um vício ou defeito no produto ou serviço
- **Prazo decadencial**: Prazo dentro do qual o consumidor deve agir para exercer seus direitos
- **Prescrição**: Falta de ação ou inação do consumidor que vicia seu direito ao restituição do preço
- **Instauração de Inquérito Civil**: Ação processual que visa apurar os fatos de uma reclamação

### Referências legais
- Art. 26, § 2º do CDC
- Súmula 342 STJ

### Jurisprudência
- RE 123456
- Questão repetitiva ...

### Dicas de prova
- Distinção entre reclamação e ação civil
- Entendimento do STJ sobre a necessidade de formalidade para a reclamação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 26, § 2º do CDC", "Súmula 342 STJ"], "jurisprudence": ["RE 123456", "Questão repetitiva ..."], "confidence": 0.8, "extracted_at": "2026-05-30T03:04:17.153699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=77", "doc_key": "2b97e1181f45b2e423e12a922c5687de"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e3bad8c6857dc5e9ff86f62ad37b8987654a84a58b68d5b2c866ab4a8cda66f3'),
  ('cpiuris2025::c58e1f45450a88cbe6398d1ee48ecd78', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Prazo de decadência para reclamação de vícios do produto', '## Prazo de decadência para reclamação de vícios do produto

A questão refere-se ao início do prazo de decadência para a reclamação de vícios do produto, de acordo com o art. 26 do CDC.

### Conceitos
- **Prazo de decadência**: Período durante o qual não pode ser apresentada uma ação
- **Vícios do produto**: Defeitos ou irregularidades no produto que podem ser reclamados pelo consumidor
- **Garantia contratual**: Cláusula de garantia incluída em um contrato de compra e venda

### Referências legais
- Art. 26 do Código de Defesa do Consumidor

### Dicas de prova
- Entenda a diferença entre prazo de decadência e prazo de prescrição
- Conheça o art. 26 do CDC e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 26 do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:06:07.591149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=77", "doc_key": "c58e1f45450a88cbe6398d1ee48ecd78"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd7a6613c969b9a8756bfd0de3f7d0579618d9a74bbb4d2c3b232dbcf5b1ef908'),
  ('cpiuris2025::70e44d3584b6a4a24f81ec3a7ef77a71', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A pessoa jurídica é instituição relativamente recente, surgindo com o fenômeno da personificação de entes coletivos. A autonomia patrimonial é fundamental para a separação dos bens do(s) socio(s) dos bens da pessoa jurídica.

### Conceitos
- **Autonomia Patrimonial**: Princípio que separa os bens e obrigações da sociedade empresária dos bens e obrigações particulares dos sócios.
- **Pessoa Jurídica**: Instituição jurídica que surge com o fenômeno da personificação de entes coletivos
- **Separação Patrimonial**: Distinção entre bens e obrigações da sociedade empresária, não confundíveis com bens e obrigações particulares dos sócios.

### Referências legais
- Art. 1.234 do Código Civil
- Súmula 123 da STF

### Jurisprudência
- RE 456.789
- Tema repetitivo: Responsabilidade da sociedade empresária

### Dicas de prova
- Entenda a autonomia patrimonial e sua importância para a pessoa jurídica
- Conheça a distinção entre bens e obrigações da sociedade empresária e dos sócios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1.234 do Código Civil", "Súmula 123 da STF"], "jurisprudence": ["RE 456.789", "Tema repetitivo: Responsabilidade da sociedade empresária"], "confidence": 0.8, "extracted_at": "2026-05-30T03:06:48.329954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=80", "doc_key": "70e44d3584b6a4a24f81ec3a7ef77a71"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3a7f3102e11aaad7951d38ae5377f36a27a9546d48c1b925146883afe7130e3a'),
  ('cpiuris2025::2232d3ff275e8d6e887feda4e33cce70', 'doutrina', 'cp_iuris', 'Direito do Consumidor — PreSCRIÇÃO E DECADÊNCIA NO CDC', '## PreSCRIÇÃO E DECADÊNCIA NO CDC

Discute-se a precrição e decadência no Código de Defesa do Consumidor, destacando as hipóteses em que o consumidor pode exigir imediatamente alguma das alternativas do art. 18, §1º do CDC.

### Conceitos
- **Teoria finalista**: teoria que conceitua a pessoa do consumidor como destinatária final do produto ou serviço
- **Mitigação da teoria finalista**: modificação da teoria finalista para incluir pessoas não destinatárias, em situação de vulnerabilidade
- **Decadência do art. 26 do CDC**: prazo para reclamar vícios no produto ou serviço
- **Garantia contratual**: complementar à legal e conferida mediante termo escrito
- **Inversão do ônus da prova**: prevista no art. 6º, inciso VIII, do CDC

### Referências legais
- Art. 18, §3° do CDC
- Art. 50 do CDC
- Súmula nº 477 do STJ
- Tesoura nº 39 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Teoria finalista

### Dicas de prova
- Diferenciar entre teoria finalista e mitigação da mesma
- Entender a hipótese de decadência do art. 26 do CDC
- Conhecer a garantia contratual e sua relação com o Código', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.78", "page_number": 78, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18, §3° do CDC", "Art. 50 do CDC", "Súmula nº 477 do STJ", "Tesoura nº 39 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Teoria finalista"], "confidence": 0.8, "extracted_at": "2026-05-30T03:07:22.811240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=78", "doc_key": "2232d3ff275e8d6e887feda4e33cce70"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7ea75f77aea0da16ac498b5610e36ee2538eb7aa6bfaa09bced31327f1df3753'),
  ('cpiuris2025::0456ced65cc8e331f3ddc95bb88a73d4', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A personalidade jurídica é universal e estanque, separada do patrimônio dos sócios. Isso significa que os bens particulares dos sócios não podem ser executados por dívidas da sociedade.

### Conceitos
- **Personalidade Jurídica**: Universal e estanque, separada do patrimônio dos sócios
- **Patrimônio**: Bens e direitos que compõem a riqueza de uma pessoa jurídica
- **Sociedades**: Pessoas jurídicas que celebram um contrato de sociedade

### Referências legais
- Art. 1.024 do CCB
- Art. 795, do CPC

### Dicas de prova
- Entenda a diferença entre patrimônio e personalidade jurídica
- Conheça o artigo 1.024 do CCB e o artigo 795 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 1.024 do CCB", "Art. 795, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:08:05.496469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=80", "doc_key": "0456ced65cc8e331f3ddc95bb88a73d4"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a8ca611a2c0023073b3a8594a34fe42166a30fc2e9ed201d0fa2628f83b2de1a'),
  ('cpiuris2025::cf9812a99b7b59bb49bb432edc59734c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica é uma regra que permite o afastamento episódico do véu que separa o patrimônio pessoal do pertencente à pessoa jurídica, quando há fraude ou abuso de direito. A legislação brasileira optou por tratar essa temática de forma específica.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Regra que permite o afastamento episódico do véu que separa o patrimônio pessoal do pertencente à pessoa jurídica
- **Fraude ou Abuso de Direito**: Condição necessária para a aplicação da desconsideração da personalidade jurídica
- **Pessoa Jurídica**: Ente coletivo que pode ser responsabilizado por suas obrigações

### Referências legais
- Art. 49, § 4º, da Lei nº 9.512/1998

### Dicas de prova
- Entenda a distinção entre fraude e abuso de direito
- Conheça as regras que regem a desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 4º, da Lei nº 9.512/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:09:12.081408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=81", "doc_key": "cf9812a99b7b59bb49bb432edc59734c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '395554510741d1ecb4b34f3c947f50ba74620e42fa1f7b320932476c3c26e39b'),
  ('cpiuris2025::97410e8af6522fe0a14b5eb34a800644', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desconsideração da personalidade jurídica de sociedades', '## Desconsideração da personalidade jurídica de sociedades

O juiz pode desconsiderar a personalidade jurídica de uma sociedade quando há abuso de direito, excesso de poder ou violação da lei em detrimento do consumidor.

### Conceitos
- **Abuso da personalidade jurídica**: Desvio de finalidade ou confusão patrimonial
- **Desconsideração**: Atividade do juiz que elimina a personalidade jurídica de uma sociedade
- **Excesso de poder**: Oportunidade para o consumidor ser prejudicado por uma situação injusta

### Referências legais
- Art. 50 do Código Civil de 2002
- Art. 28 do CDC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de abuso da personalidade jurídica e como ela é caracterizada
- Conheça a regra da desconsideração e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 do Código Civil de 2002", "Art. 28 do CDC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T03:09:18.335275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=81", "doc_key": "97410e8af6522fe0a14b5eb34a800644"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '01e773604be0b13410cf47964bb8306fc7f83ba846d9475b96aa6670870be505'),
  ('cpiuris2025::36e47512f8960dc3587152402762ee0f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

A desconsideração da personalidade jurídica é um instituto que permite a responsabilização de uma pessoa jurídica por atos ilícitos cometidos por seus sócios ou administradores, especialmente em casos de má administração. A teoria maior exige desvio de finalidade ou confusão patrimonial, enquanto a teoria menor não exige fraude ou abuso de direito.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Instituto que permite a responsabilização de uma pessoa jurídica por atos ilícitos cometidos por seus sócios ou administradores.
- **Teoria Maior**: Exige desvio de finalidade ou confusão patrimonial para viabilizar a desconsideração da personalidade jurídica.
- **Teoria Menor**: Não exige fraude ou abuso de direito, basta demonstrar a inexistência de bens da pessoa jurídica aptos a saldar a dívida.

### Referências legais
- Art. 50 do Código Civil
- Lei n.º 13.874/2019

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre desvio de finalidade e confusão patrimonial.
- Conheça as teorias maior e menor de desconsideração da personalidade jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 50 do Código Civil", "Lei n.º 13.874/2019"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T03:10:42.153256+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=82", "doc_key": "36e47512f8960dc3587152402762ee0f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c0cf336bf0ef39be0271466a02ddd4692725d71b50272d67b7388c10c279c8d9'),
  ('cpiuris2025::a21b581c9183916f8a7b292bf61558bb', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vulnerabilidade e igualdade nas relações de consumo', '## Vulnerabilidade e igualdade nas relações de consumo

O princípio da vulnerabilidade promove a igualdade entre as partes na relação de consumo, visando a reparação integral do consumidor.

### Conceitos
- **Princípio da Vulnerabilidade**: Promove a igualdade entre as partes na relação de consumo
- **Igualdade Material**: Visa garantir que as partes tenham direitos e deveres semelhantes
- **Reparação Integral do Consumidor**: Visa reparar os danos causados ao consumidor

### Referências legais
- Art. 4º, I, do CDC

### Dicas de prova
- Entenda o princípio da vulnerabilidade e sua importância na relação de consumo
- Destaque a igualdade material entre as partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, I, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:10:53.293258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=82", "doc_key": "a21b581c9183916f8a7b292bf61558bb"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dd94d13723962400e7a831bfd2c84eeb9ef3c5bcae3cb9b808671db3231ccc25'),
  ('cpiuris2025::f61673c9984d0dc03db768a9a5dff1c9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Desconsideração da Personalidade Jurídica', '## Desconsideração da Personalidade Jurídica

O CDC admite a desconsideração da personalidade jurídica de ofício pelo juiz, especialmente quando há indícios de vulnerabilidade do consumidor e caráter de ordem pública das disposições consumeristas.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Procedimento pelo qual a pessoa jurídica é considerada como uma única entidade com o patrimônio e os débitos de suas partes integrantes.
- **Teoria Menor**: Teoria jurídica que permite a desconsideração da personalidade jurídica quando há indícios de responsabilidade direta de uma parte integrante pela dívida da pessoa jurídica.
- **Ordem Pública**: Caráter das disposições consumeristas que as torna obrigatórias e imutáveis para todos os cidadãos.

### Referências legais
- Art. 28 do CDC
- Art. 1º, caput, do CDC
- Art. 133 a 137 do NCPC

### Jurisprudência
- REsp. 279.273/SP
- REsp. 1.766.093/SP

### Dicas de prova
- Diferenciar entre desconsideração da personalidade jurídica de ofício e instauração do incidente processual
- Entender o caráter de ordem pública das disposições consumeristas
- Conhecer a Teoria Menor e sua aplicabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.83 (1)", "page_number": 83, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 28 do CDC", "Art. 1º, caput, do CDC", "Art. 133 a 137 do NCPC"], "jurisprudence": ["REsp. 279.273/SP", "REsp. 1.766.093/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T03:11:58.020801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=83", "doc_key": "f61673c9984d0dc03db768a9a5dff1c9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'bc1d3d7748634eb00796a34c85f8b0e6f5ce1b26e5d7c55ee1efae2cfddf6268'),
  ('cpiuris2025::4711fcdef79e7d1512060c8b078cebaa', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade das sociedades integrantes de grupos societários e controladas', '## Responsabilidade das sociedades integrantes de grupos societários e controladas

O § 5º do art. 28 do CDC não permite a responsabilização pessoal de administradores não sócios, salvo se demonstrada sua contribuição culposa para a prática de atos da administração. As sociedades integrantes dos grupos societários e as sociedades controladas são subsidiariamente responsáveis pelas obrigações decorrentes do Código.

### Conceitos
- **Responsabilidade das sociedades**: A responsabilidade de uma empresa por suas obrigações legais
- **Grupo societário**: Um grupo de empresas que compartilham interesses econômicos
- **Sociedade controlada**: Uma empresa que é controlada por outra empresa ou pessoa jurídica

### Referências legais
- Art. 28, § 5º do CDC
- STJ, 3ª Turma
- REsp 1.860.333/DF

### Jurisprudência
- REsp 1.900.843/DF

### Dicas de prova
- Entenda a distinção entre responsabilidade pessoal e responsabilidade da empresa
- Conheça o conceito de grupo societário e sociedade controlada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.83 (2)", "page_number": 83, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 28, § 5º do CDC", "STJ, 3ª Turma", "REsp 1.860.333/DF"], "jurisprudence": ["REsp 1.900.843/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T03:12:56.096472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=83", "doc_key": "4711fcdef79e7d1512060c8b078cebaa"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4e3ceb4e9a9baa8e914a3a8b2ec2ca7e993be3a9ec98a218b0eba00d1535b3cc'),
  ('cpiuris2025::68be62f53d972beeaf1c223ad1ecd394', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade Solidária entre Sociedades Consorciadas', '## Responsabilidade Solidária entre Sociedades Consorciadas

A responsabilidade solidária entre sociedades consorciadas é regulada pelo Código de Defesa do Consumidor (CDC) e deve ser interpretada de maneira restritiva, permitindo solidariedade apenas em relação às obrigações relativas ao consórcio.

### Conceitos
- **Consórcio**: Acordo entre sociedades para compartilhar riscos e responsabilidades
- **Sociedades Consorciadas**: Sociedades que celebram um acordo para compartilhar riscos e responsabilidades
- **Responsabilidade Solidária**: Obrigação de uma ou mais sociedades de responder por atos cometidos por outra(s)

### Referências legais
- Art. 7º, parágrafo único; Art. 25, § 2º; Art. 28, § 3º; Art. 278, § 1º; Art. 243, § 1º do CDC

### Jurisprudência
- REsp 1.635.637/RJ

### Dicas de prova
- Entenda o conceito de consórcio e suas implicações na responsabilidade solidária
- Interprete a regra do CDC de maneira restritiva, permitindo solidariedade apenas em relação às obrigações relativas ao consórcio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, parágrafo único; Art. 25, § 2º; Art. 28, § 3º; Art. 278, § 1º; Art. 243, § 1º do CDC"], "jurisprudence": ["REsp 1.635.637/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:13:18.479516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=84", "doc_key": "68be62f53d972beeaf1c223ad1ecd394"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b77f89ef8495b0c665687ec9e3b35f6e870b147223c97990649f1225a4af3f77'),
  ('cpiuris2025::ac16590ab952a2ebc3242a3632d2e449', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade das Sociedades em Relações de Consumo', '## Responsabilidade das Sociedades em Relações de Consumo

A questão discute a responsabilidade das sociedades em relações de consumo, com foco nas obrigações decorrentes do Código de Defesa do Consumidor. As sociedades coligadas e consorciadas têm diferentes níveis de responsabilidade.

### Conceitos
- **Responsabilidade Solidária**: A responsabilidade solidária é a responsabilidade conjunta de várias pessoas ou entidades por uma obrigação
- **Obrigações Decorrentes do CDC**: As obrigações decorrentes do Código de Defesa do Consumidor são as obrigações que os consumidores têm contra as empresas
- **Art. 28 §2° do CDC**: Estabelece que as sociedades integrantes dos grupos societários e as sociedades controladas são subsidiariamente responsáveis pelas obrigações decorrentes do Código
- **Art. 34 do CDC**: Estabelece que o fornecedor do produto ou serviço é solidariamente responsável pelos atos de seus prepostos ou representantes autônomos

### Referências legais
- Art. 28 §2° do CDC
- Art. 34 do CDC

### Jurisprudência
- RE 123456
- Tema repetitivo: Responsabilidade das Sociedades em Relações de Consumo

### Dicas de prova
- Entenda a distinção entre responsabilidade solidária e subsidiária
- Leia atentamente os arts. 28 §2° e 34 do CDC
- Conheça as obrigações decorrentes do Código de Defesa do Consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 28 §2° do CDC", "Art. 34 do CDC"], "jurisprudence": ["RE 123456", "Tema repetitivo: Responsabilidade das Sociedades em Relações de Consumo"], "confidence": 0.8, "extracted_at": "2026-05-30T03:14:53.854264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=85", "doc_key": "ac16590ab952a2ebc3242a3632d2e449"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b13028425e00ccf38fb496cb62e6aeef06fcdff67a4614741929ba44e60ccb23'),
  ('cpiuris2025::fa8a1d5fb2882d62d4b73b0f630eac63', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Equiparação de pessoas determináveis ou não às pessoas consumidoras', '## Equiparação de pessoas determináveis ou não às pessoas consumidoras

O artigo 29 do CDC equipara pessoas determináveis ou não expostas a práticas comerciais às pessoas consumidoras, ampliando o espectro protetivo do diploma consumerista.

### Conceitos
- **Equiparação**: Ampliação do espectro protetivo do CDC
- **Pessoas determináveis ou não**: Pessoas expostas a práticas comerciais
- **Consumidor**: Pessoa que toma contato com prática comercial
- **Práticas comerciais**: Atos de mercado

### Referências legais
- Art. 29 do CDC

### Jurisprudência
- RE 123456
- RMS 27.541/TO

### Dicas de prova
- Entenda a noção de consumidor e práticas comerciais
- Identifique o artigo que equipa pessoas determináveis ou não às pessoas consumidoras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 29 do CDC"], "jurisprudence": ["RE 123456", "RMS 27.541/TO"], "confidence": 0.8, "extracted_at": "2026-05-30T03:15:02.714362+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=87", "doc_key": "fa8a1d5fb2882d62d4b73b0f630eac63"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '87da2eddeef19b1a42b5905293ef82b78a4bb2aa2b5cf25035684573f1d26575'),
  ('cpiuris2025::5455be46c4f05bb137e2bb0e0c1220d9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade das Sociedades por Infrações do Código', '## Responsabilidade das Sociedades por Infrações do Código

As sociedades coligadas só respondem por culpa, enquanto as consorciadas são solidariamente responsáveis pelas obrigações decorrentes do Código. As sociedades integrantes dos grupos societários e as controladas são subsidiariamente responsáveis.

### Conceitos
- **Responsabilidade Solidária**: Obrigação compartilhada por duas ou mais pessoas
- **Culpa**: Responsabilidade por negligência ou dolo
- **Sociedades Coligadas**: Sociedades que respondem apenas por culpa
- **Sociedades Consorciadas**: Sociedades responsáveis solidariamente pelas obrigações do Código
- **Grupos Societários**: Grupo de empresas que compartilham uma estrutura societária
- **Sociedades Controladas**: Sociedade que é controlada por outra empresa

### Referências legais
- Art. 28, §2° do CDC

### Dicas de prova
- Distinção entre sociedades coligadas e consorciadas
- Entendimento do conceito de grupos societários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 28, §2° do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:15:12.314834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=85", "doc_key": "5455be46c4f05bb137e2bb0e0c1220d9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9e14265447d836449e60ec73ec6781357ecdc467856bb3c3d2f43ae25c040895'),
  ('cpiuris2025::61f3a7c2f34c0c6088c7a78b898e52b8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Comerciais Abusivas', '## Práticas Comerciais Abusivas

O consumidor tem direito a proteção legal em casos de práticas comerciais abusivas, independentemente da apuração de evento causal.

### Conceitos
- **práticas comerciais abusivas**: condutas que sejam prejudiciais ao consumidor
- **proteção legal**: direito do consumidor a buscar reparação por danos sofridos

### Referências legais
- Art. 41 da Lei nº 8.078/1990

### Jurisprudência
- RE 123456

### Dicas de prova
- distinção entre causalidade e ordem coletiva
- importância de proteger o consumidor independentemente do evento causador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 41 da Lei nº 8.078/1990"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T03:15:55.722685+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=87", "doc_key": "61f3a7c2f34c0c6088c7a78b898e52b8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b7bff1b6683929b9b379e25b392b394ea3605e2ffab5cddfb9b3bb385e8919b6'),
  ('cpiuris2025::1d6100b335e810796c6a0a8ee16235b3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

A publicidade nas relações de consumo deve ser interpretada de forma ampla para garantir a isonomia material aos consumidores, incluindo os fornecedores. O artigo 29 do CDC é fundamental nesse sentido.

### Conceitos
- **Isonomia Material**: Garantia de igualdade de tratamento para todos os consumidores
- **Vinculação da Oferta**: Dever do fornecedor de informar precisamente a oferta de produtos e serviços
- **Boa-Fé Objetiva**: Desejo de lealdade, cooperação, informação e transparência entre as partes

### Referências legais
- Art. 29 da Lei nº 8.978/1994
- Súmula 221 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Publicidade nas Relações de Consumo

### Dicas de prova
- Entenda a importância da isonomia material nos contratos de consumo.
- Conheça os requisitos para que uma oferta seja considerada vinculante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.88 (1)", "page_number": 88, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 29 da Lei nº 8.978/1994", "Súmula 221 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Publicidade nas Relações de Consumo"], "confidence": 0.8, "extracted_at": "2026-05-30T03:16:10.374825+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=88", "doc_key": "1d6100b335e810796c6a0a8ee16235b3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '04cf713be48e5b87dda3ad30eef21380518ed42d895306e76233fbd3af1fcba3'),
  ('cpiuris2025::2dd98d8d2022fc9a2e0aa7049163ea3a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obrigação de Informação ao Consumidor', '## Obrigação de Informação ao Consumidor

O fornecedor deve apresentar informações úteis ao consumidor sobre o produto ou serviço, incluindo características, uso, preço e riscos.

### Conceitos
- **Princípio da Informação**: obrigação de informação desdobrada em 4 categorias
- **Informação-conteúdo**: características intrínsecas do produto e do serviço
- **Informação-utilização**: modo como o consumidor usará o produto ou do serviço
- **Informação-preço**: custos, formas e condições de pagamento
- **Informação-advertência**: riscos do produto ou do serviço

### Referências legais
- Art. 4º, caput, do CDC; Art. 6º, III, do CDC

### Jurisprudência
- REsp 586.316 (STJ)

### Dicas de prova
- Entenda o princípio da informação e suas categorias
- Destaque as características importantes do produto ou serviço', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, caput, do CDC; Art. 6º, III, do CDC"], "jurisprudence": ["REsp 586.316 (STJ)"], "confidence": 0.8, "extracted_at": "2026-05-30T03:18:10.500035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=89", "doc_key": "2dd98d8d2022fc9a2e0aa7049163ea3a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3eb1c541a7d771d37720b5c108e62e421935325356dd7bdfdce21c6264326519'),
  ('cpiuris2025::40a2df42e8b4003c0ba3bc3814612567', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Oferta Irretratável no Direito do Consumidor', '## Oferta Irretratável no Direito do Consumidor

A oferta publicitária é irretratável se atende aos requisitos de ser razoavelmente precisa e obrigar o fornecedor a contratar com o consumidor que se proponha a atender seus termos.

### Conceitos
- **Oferta Irretratável**: oferta publicitária que é razoavelmente precisa e obriga o fornecedor a contratar com o consumidor
- **Puffing**: exagero facilmente perceptível em uma oferta publicitária
- **Requisitos da Oferta Irretratável**: razoabilidade e obrigatoriedade para o fornecedor contratar com o consumidor

### Referências legais
- Art. 4º, VI do CDC

### Jurisprudência
- REsp 1.770.411-RJ
- REsp 1.105.422/MG

### Dicas de prova
- Distinção entre oferta publicitária e oferta que integra contrato
- Importância da razoabilidade na oferta irretratável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.88 (2)", "page_number": 88, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, VI do CDC"], "jurisprudence": ["REsp 1.770.411-RJ", "REsp 1.105.422/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T03:18:26.864892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=88", "doc_key": "40a2df42e8b4003c0ba3bc3814612567"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ddce0297cd76b2761b63802abbcf425076aac06f1a7ad87c0399c10563e83359'),
  ('cpiuris2025::fee8670a7f3a15536c17fb239f55b238', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vinculação das Ofertas e Dever de Informações Corretas', '## Vinculação das Ofertas e Dever de Informações Corretas

O consumidor tem direitos em caso de recusa de cumprimento de oferta, incluindo o direito à tutela específica, aceitação de produto equivalente ou rescisão do contrato. Além disso, os fornecedores devem fornecer informações corretas e precisas sobre os produtos ou serviços oferecidos.

### Conceitos
- **Vinculação das Ofertas**: Condição em que a oferta de um fornecedor é vinculante para todos os demais fornecedores do grupo
- **Dever de Informação**: Obrigação dos fornecedores de fornecer informações corretas e precisas sobre seus produtos ou serviços
- **Tutela Específica**: Direito do consumidor a exigir o cumprimento forçado da obrigação
- **Aceitação de Produto Equivalente**: Oportunidade do consumidor de aceitar outro produto ou prestação de serviço equivalente à oferta recusada
- **Rescisão do Contrato**: Direito do consumidor de rescindir o contrato e receber a restituição de quantia eventualmente antecipada, monetariamente atualizada, e as perdas e danos

### Referências legais
- Art. 35 do CDC
- Art. 31 do CDC

### Jurisprudência
- REsp 1.309.981/SP
- REsp 1.794.991/SE

### Dicas de prova
- Entenda a diferença entre vinculação das ofertas e dever de informação
- Conheça os direitos do consumidor em caso de recusa de cumprimento de oferta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 35 do CDC", "Art. 31 do CDC"], "jurisprudence": ["REsp 1.309.981/SP", "REsp 1.794.991/SE"], "confidence": 0.8, "extracted_at": "2026-05-30T03:19:21.977565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=89", "doc_key": "fee8670a7f3a15536c17fb239f55b238"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '988848204a74166143011df14c4acf273aba7754fac12c7a67758d44eec4d6a2'),
  ('cpiuris2025::76b48a61d40516b63307e499a69f5df5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Obsolescência Programada e Durabilidade Adequada', '## Obsolescência Programada e Durabilidade Adequada

A obsolescência programada viola a Política Nacional das Relações de Consumo e representa ofensa à boa-fé objetiva, além de violar a durabilidade adequada.

### Conceitos
- **Obsolescência Programada**: Prática que força o consumidor a adquirir novas versões de um produto ou serviço
- **Durabilidade Adequada**: Condição necessária para a realização do contrato de consumo
- **Política Nacional das Relações de Consumo**: Lei que regula as relações entre consumidor e fornecedor

### Referências legais
- Art. 4º, II, ''d'' do CDC

### Jurisprudência
- REsp 984.106/SC

### Dicas de prova
- Distinção entre prática de obsolescência programada e descumprimento do dever de informação
- Reconhecimento da violação à Política Nacional das Relações de Consumo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, II, ''d'' do CDC"], "jurisprudence": ["REsp 984.106/SC"], "confidence": 0.8, "extracted_at": "2026-05-30T03:20:17.818240+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=90", "doc_key": "76b48a61d40516b63307e499a69f5df5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '64c72f290074bf8135195a865deae517e4174cafbf03305a3838468c585b6485'),
  ('cpiuris2025::5fd2984900929b38342e771f10141d64', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Ofertas de peças de reposição e responsabilidade pós-contratual', '## Ofertas de peças de reposição e responsabilidade pós-contratual

A lei exige que fabricantes e importadores assegurem a oferta de componentes e peças de reposição até que cessem a fabricação ou importação do produto. O descumprimento pode estar ligado à prática abusiva de obsolescência programada.

### Conceitos
- **Dever de informação**: Obrigação de informar eventual diminuição de conteúdo em embalagens
- **Prática abusiva de obsolescência programada**: Redução intencional da vida útil de um bem ou serviço para forçar o consumidor a adquirir novas versões
- **Defeito de adequação**: Falta de conformidade com as expectativas legítimas do consumidor
- **Boa-fé objetiva**: Princípio que norteia as relações contratuais e exige a honestidade e transparência das partes

### Referências legais
- Art. 32 do CDC
- Art. 13, XXI do Decreto n.º 2.181/97
- Art. 18 do CDC

### Jurisprudência
- REsp 1.364.915/MG
- REsp 1.067.530/SP
- REsp 1.788.075/DF

### Dicas de prova
- Entenda a distinção entre o dever de informação e a responsabilidade pós-contratual
- Conheça as diretrizes da Lei n.º 10.962/04 sobre ofertas online', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 32 do CDC", "Art. 13, XXI do Decreto n.º 2.181/97", "Art. 18 do CDC"], "jurisprudence": ["REsp 1.364.915/MG", "REsp 1.067.530/SP", "REsp 1.788.075/DF"], "confidence": 0.8, "extracted_at": "2026-05-30T03:21:09.141947+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=90", "doc_key": "5fd2984900929b38342e771f10141d64"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0595a8064611037271b7811c8d84b865913d5ed037353faff044a82e98a6c184'),
  ('cpiuris2025::709d84196ae50ba8468effc0c269cf71', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

O consumidor tem direitos garantidos pelo CDC, incluindo a transparência na publicidade e a responsabilidade do fornecedor pelos atos dos prepostos ou representantes autônomos.

### Conceitos
- **Transparência**: Dever que decorre do princípio da transparência, permitindo a adequada identificação do fornecedor quando do recebimento do produto.
- **Responsabilidade do Fornecedor**: O fornecedor é solidariamente responsável pelos atos de seus prepostos ou representantes autônomos

### Referências legais
- Art. 18, § 1º, do CDC
- Art. 33, do CDC
- Art. 34, do CDC
- Decreto n.º 6.523/2008
- Lei Geral de Proteção de Dados Pessoais (LGPD) - Lei n.º 13.709/2018

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre publicidade onerosa e gratuita
- Importância da transparência na publicidade
- Responsabilidade do fornecedor pelos atos dos prepostos ou representantes autônomos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 18, § 1º, do CDC", "Art. 33, do CDC", "Art. 34, do CDC", "Decreto n.º 6.523/2008", "Lei Geral de Proteção de Dados Pessoais (LGPD) - Lei n.º 13.709/2018"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T03:21:43.365735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=91", "doc_key": "709d84196ae50ba8468effc0c269cf71"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c8bfdd13a35a369e4c280f1a36d4ad8a8013c5f3ad619797c5688007abc131fd'),
  ('cpiuris2025::d4b9eba28da99a018db93a06b947f81f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Vulnerabilidade do consumidor na relação consumerista', '## Vulnerabilidade do consumidor na relação consumerista

A vulnerabilidade do consumidor deve prevalecer em relação a acordos ou estruturas formais entre fornecedores.

### Conceitos
- **Preposto**: Pessoa que presta serviço ou realiza atividade por conta e sob direção de outrem.
- **Representante Autônomo**: Pessoa física ou jurídica que atua sem relação empregatícia, mas representa o fornecedor de maneira não eventual.

### Referências legais
- Art. 710 a 721 do CC/02

### Dicas de prova
- Distinção entre preposto e representante autônomo
- Importância da vulnerabilidade do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 710 a 721 do CC/02"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:21:50.021312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=91", "doc_key": "d4b9eba28da99a018db93a06b947f81f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '043e93c46b99f6b95933600f13278424eed37bd4e52d418b067fbc4e2fa73e69'),
  ('cpiuris2025::13acc4fab2b2a496ddfed12859045d2d', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Rescisão de Contrato e Direitos do Consumidor', '## Rescisão de Contrato e Direitos do Consumidor

O consumidor tem direito a rescindir o contrato com o fornecedor, alternativamente à sua escolha, e pode receber restituição monetária atualizada e perdas e danos.

### Conceitos
- **Rescisão de Contrato**: Ação do consumidor para extinguir um acordo ou contrato
- **Direito à Restituição**: O direito do consumidor a receber uma indenização pela rescisão do contrato
- **Perdas e Danos**: Consequências financeiras e materiais que o consumidor sofreu devido à rescisão do contrato

### Referências legais
- Art. 35, III do CDC

### Dicas de prova
- Distinção entre perdas e danos cumulativas e direito à restituição
- Reparação integral no caso de rescisão do contrato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 35, III do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:23:24.961176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=92", "doc_key": "13acc4fab2b2a496ddfed12859045d2d"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0ce060129f6c53110b9eae770a6892161533acdb0ac1bab16eefe54bf8954c54'),
  ('cpiuris2025::bbb8aa280bf0260d53a767b1b626f4f6', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

O fornecedor deve adotar práticas comerciais condizentes com as regras existentes no sistema jurídico de proteção ao consumidor. O consumidor pode rescindir o contrato e pleitear restituição se o fornecedor recusar cumprimento à oferta.

### Conceitos
- **representação comercial autônoma**: Ato realizado por uma pessoa que não está diretamente ligada ao fornecedor, mas representa seus interesses.
- **teoria da aparência**: Teoria que estabelece que todo ato praticado por uma pessoa que razoavelmente se evidenciar como representante de um determinado fornecedor diante do consumidor deve vincular tal fornecedor.
- **boa-fé objetiva**: Princípio que exige que as partes agam com honestidade e sinceridade em suas relações comerciais.

### Referências legais
- Art. 34 do CDC

### Jurisprudência
- STJ - AREsp 1.220.381/DF
- Edcl no AgInt

### Dicas de prova
- Distinção entre representação comercial autônoma e teoria da aparência.
- A importância da boa-fé objetiva na proteção ao consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 34 do CDC"], "jurisprudence": ["STJ - AREsp 1.220.381/DF", "Edcl no AgInt"], "confidence": 0.8, "extracted_at": "2026-05-30T03:23:34.321813+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=92", "doc_key": "bbb8aa280bf0260d53a767b1b626f4f6"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2a4aca4cac77032c2a9831f453e9047541b020b42ffd2a07899958977a88316b'),
  ('cpiuris2025::2c8cd7a86b3ac324affcbcde4f9e4bb7', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

A publicidade assume dimensão importante na sociedade contemporânea e foi objeto de preocupação do legislador durante a elaboração do CDC. O Decreto 2.181/97 conceitua publicidade como veiculação de mensagem para promover produtos ou serviços disponibilizados no mercado de consumo.

### Conceitos
- **Publicidade**: veiculação de mensagem para promover produtos ou serviços
- **Propaganda**: informação ou comunicação difundida com fim ideológico, religioso, político, econômico ou social
- **Publicidade institucional**: promove o fornecedor de produtos ou serviços em si
- **Publicidade promocional**: busca incrementar e expandir a venda de um produto ou serviço específico

### Referências legais
- Art. 14, § 4º do Decreto 2.181/97
- Lei Geral de Proteção de Dados Pessoais (LGPD) - Lei n.º 13.709/2018

### Dicas de prova
- Reconheça a diferença entre publicidade e propaganda
- Entenda o conceito de publicidade institucional e promocional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 14, § 4º do Decreto 2.181/97", "Lei Geral de Proteção de Dados Pessoais (LGPD) - Lei n.º 13.709/2018"], "jurisprudence": [], "confidence": 0.9, "extracted_at": "2026-05-30T03:24:13.441153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=94", "doc_key": "2c8cd7a86b3ac324affcbcde4f9e4bb7"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '32c8681fd542cc965093c69a0feb0a9d39491192c24b4db276e87a0f98c6cbb0'),
  ('cpiuris2025::511e641fcab57747ebc2495575f13a46', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Responsabilidade do veiculador de publicidade', '## Responsabilidade do veiculador de publicidade

O responsável por veicular a mensagem publicitária deve obter e guardar dados técnicos que corroborem as afirmações feitas na peça de promoção.

### Conceitos
- **Responsabilidade do veiculador**: Dever de obter e guardar dados técnicos que corroborem as afirmações publicitárias
- **Mensagem publicitária**: Promoção comercial

### Referências legais
- Art. 73 do Código de Defesa do Consumidor

### Dicas de prova
- Distinção entre responsabilidade e garantia
- Importância da obtenção e guarda de dados técnicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 73 do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:25:27.905166+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=95", "doc_key": "511e641fcab57747ebc2495575f13a46"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '5b225bcd71c0add7f4935bedbd7ccf8dae22b33167793b73ed0e8fb48245fa91'),
  ('cpiuris2025::16552e6a4da68618003f20427e74ed2f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

A publicidade nas relações de consumo é regulamentada pelo Código de Defesa do Consumidor, visando proteger os consumidores contra práticas abusivas e enganosas.

### Conceitos
- **Código de Defesa do Consumidor**: Lei que regula as relações entre o consumidor e o fornecedor de bens e serviços.
- **Publicidade enganosa**: A publicidade que não é precisa, completa ou verdadeira, com o objetivo de induzir o consumidor a tomar uma decisão errada.
- **Relações de consumo**: As relações entre o consumidor e o fornecedor de bens e serviços.
- **Fornecedores**: As pessoas jurídicas que oferecem produtos ou serviços aos consumidores.
- **Consumidores**: As pessoas físicas que adquirem produtos ou serviços.

### Referências legais
- Art. 37 do Código de Defesa do Consumidor

### Dicas de prova
- A publicidade enganosa é considerada uma prática abusiva e pode ser responsabilizada pelo consumidor.
- O fornecedor deve garantir que a publicidade seja precisa, completa e verdadeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 37 do Código de Defesa do Consumidor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:25:44.124792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=94", "doc_key": "16552e6a4da68618003f20427e74ed2f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b7a4ae63da8097f4b488595ff6a6e8b9b09e0252313b2ae395d3b5b4d413aa4a'),
  ('cpiuris2025::da1ea75c17ae2c4ecf24e573b0c15c31', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípios da Publicidade', '## Princípios da Publicidade

Os princípios da publicidade são estabelecidos para garantir a honestidade e a transparência das informações publicitárias. Eles incluem a vinculação contratual, a veracidade, a não abusividade e a transparência da fundamentação.

### Conceitos
- **Vinculação contratual**: O princípio que estabelece que a mensagem publicitária vincula o anunciante
- **Veracidade**: A diretriz de que toda informação utilizada em campanha publicitária deve estar integralmente comprometida com a verdade
- **Não abusividade**: O princípio que proíbe a publicidade com informações falsas ou enganosas
- **Transparência da fundamentação**: A obrigação do fornecedor de manter os dados fáticos e técnicos para informação dos consumidores

### Referências legais
- Art. 36, parágrafo único, do CDC
- Art. 37, § 1º, do CDC

### Dicas de prova
- Entenda a diferença entre puffing e teaser
- Aproveite a analogia entre o merchandising e a publicidade para entender melhor o princípio da vinculação contratual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 36, parágrafo único, do CDC", "Art. 37, § 1º, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:26:06.579930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=95", "doc_key": "da1ea75c17ae2c4ecf24e573b0c15c31"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fb9efea9a2ed077ee20535a1b5ee515b585e1d702bbfe84704db1859cdedda8a'),
  ('cpiuris2025::c0bb7951b8e8cb253cde71fb0b6bdf35', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da Lealdade Publicitária', '## Princípio da Lealdade Publicitária

O princípio da lealdade publicitária é um princípio do Direito do Consumidor que visa coibir práticas desleais de marketing, especialmente em relação à publicidade comparativa. Ele exige que os anunciantes sejam éticos e transparentes em suas práticas de marketing.

### Conceitos
- **Lealdade Publicitária**: Princípio do Direito do Consumidor que visa coibir práticas desleais de marketing
- **Publicidade Comparativa**: Anúncio que compara produtos de concorrentes
- **Objetividade e Veracidade**: Regras para anúncios publicitários que devem ser seguidas para garantir a objetividade e veracidade do conteúdo

### Referências legais
- Art. 4º, VI, do CDC
- Art. 32 do Código Brasileiro de Autorregulação Publicitária

### Jurisprudência
- REsp 1.668.550/RJ
- REsp 1.377.911/SP

### Dicas de prova
- Entenda a importância da lealdade publicitária no Direito do Consumidor
- Conheça as regras de objetividade e veracidade para anúncios publicitários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, VI, do CDC", "Art. 32 do Código Brasileiro de Autorregulação Publicitária"], "jurisprudence": ["REsp 1.668.550/RJ", "REsp 1.377.911/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T03:27:59.234525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=96", "doc_key": "c0bb7951b8e8cb253cde71fb0b6bdf35"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0248daa7c7a0279cacc6cc6034aca39472488b1b0dd3a0fa33dabbda819ef0cf'),
  ('cpiuris2025::e4cecc2ca54c42d874fa2ab4b56b49a3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade Enganosa e Abusiva', '## Publicidade Enganosa e Abusiva

A publicidade enganosa é proibida pelo art. 37, caput, do CDC, sendo considerada qualquer informação ou comunicação publicitária falsa ou capaz de induzir erro no consumidor.

### Conceitos
- **Publicidade Enganosa**: informação ou comunicação publicitária falsa ou capaz de induzir erro no consumidor
- **Falsidade da Informação**: inexacibilidade das informações veiculadas na publicidade
- **Indução do Consumidor**: capacidade da publicidade enganosa de induzir o consumidor a cometer erro de julgamento
- **Má Utilização de Práticas Publicitárias**: uso inadequado de práticas publicitárias para fins lucrativos
- **Vedação Peremptória**: proibição absoluta e irreversível de práticas consideradas desconformes ao microssistema consumerista
- **Microssistema Consumerista**: conjunto de direitos e deveres dos consumidores
- **Práticas Publicitárias**: expedientes utilizados para promover produtos e serviços

### Referências legais
- Art. 37, caput, do CDC

### Jurisprudência
- RE 123456
- AgInt nos EDcl no REsp 1.770.411-RJ

### Dicas de prova
- Distinção entre publicidade enganosa e abusiva
- Falsidade da informação e sua capacidade de induzir erro
- Importância do microssistema consumerista na vedação peremptória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 37, caput, do CDC"], "jurisprudence": ["RE 123456", "AgInt nos EDcl no REsp 1.770.411-RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:28:20.514704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=96", "doc_key": "e4cecc2ca54c42d874fa2ab4b56b49a3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a78d46ecd284c4cb0edfa4da3e0986211253f1956df7f8c1c635af82437281d2'),
  ('cpiuris2025::a4f36f0dc98785f0fc11ce0f40b54ac7', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

A publicidade é considerada enganosa por omissão quando não for informado sobre dado essencial do produto ou serviço. O fornecedor deve prestar a informação para evitar danos ao consumidor.

### Conceitos
- **Enganosidade**: Omissão de informação essencial que pode causar dano ao consumidor
- **Fornecedor**: Pessoa responsável por fornecer o produto ou serviço
- **Consumidor**: Pessoa que contrata o produto ou serviço
- **Informação obrigatória**: Dado essencial que deve ser informado ao consumidor
- **Publicidade discriminatória**: Anúncio que discrimina características pessoais do consumidor

### Referências legais
- Art. 37 § 2º, Lei nº 8.078/1990
- Súmula 457 do STJ

### Jurisprudência
- REsp 1.261.824/SP
- REsp 1.802.787/SP
- REsp 1057483/SP
- REsp 1428801/RJ
- REsp 1552550/SP
- REsp 447.303
- REsp 1.342.899/RS

### Dicas de prova
- Entenda a noção de enganosidade e sua relação com o fornecedor e o consumidor
- Identifique as formas de publicidade discriminatória e suas consequências legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 37 § 2º, Lei nº 8.078/1990", "Súmula 457 do STJ"], "jurisprudence": ["REsp 1.261.824/SP", "REsp 1.802.787/SP", "REsp 1057483/SP", "REsp 1428801/RJ", "REsp 1552550/SP", "REsp 447.303", "REsp 1.342.899/RS"], "confidence": 0.8, "extracted_at": "2026-05-30T03:28:20.942424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=97", "doc_key": "a4f36f0dc98785f0fc11ce0f40b54ac7"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b85a84c9a369337d8cd272ad710c0b21c6e1bcbbe020201299e2e6d076f05451'),
  ('cpiuris2025::73f37d9cb027b27092c39168e1d1c7e1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade Enganosa ou Abusiva', '## Publicidade Enganosa ou Abusiva

A publicidade enganosa ou abusiva visa desfazer os malefícios causados por informações falsas, exigindo que a contrapropaganda destaque claramente o equívoco e informação verdadeira.

### Conceitos
- **Contrapropaganda**: reclamação feita em resposta à publicidade enganosa ou abusiva
- **Abusividade**: conduta que se caracteriza pela disseminação de informações falsas ou enganosas
- **Informação verdadeira**: informação correta e precisa apresentada para contrariar a publicidade enganosa ou abusiva
- **Fornecedor**: pessoa jurídica que oferece produtos ou serviços ao consumidor

### Referências legais
- Art. 56 do CDC
- Art. 67 a 69 do CDC

### Dicas de prova
- Destacar a finalidade principal de art. 56 do CDC
- Identificar o equívoco e informação verdadeira na contrapropaganda', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 56 do CDC", "Art. 67 a 69 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:30:24.141815+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=98", "doc_key": "73f37d9cb027b27092c39168e1d1c7e1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9911ad8d1730f4faa51c394a9a049a38e5cd9f42a5e0ba2a682011d7da9df4b4'),
  ('cpiuris2025::d9a6d5efbbc1732cef4c595045a5a26c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

O art. 38 estabelece o ônus da prova da veracidade e correção da informação ou comunicação publicitária, cabendo a quem as patrocina. A contrapropaganda é a principal consequência para o descumprimento de vedações contra publicidade abusiva ou enganosa.

### Conceitos
- **Enganosidade**: Ocorrência de enganosidade ou abusividade em um contrato
- **Abusividade**: Prática de publicidade que causa dano ao consumidor
- **Ônus da prova**: A responsabilidade de provar a veracidade e correção de informações publicitárias
- **Contrapropaganda**: Divulgação de informações para desfazer o malefício de uma publicidade enganosa ou abusiva

### Referências legais
- Art. 38 do CDC
- Art. 36, parágrafo único do CDC
- Art. 60 do CDC

### Jurisprudência
- REsp 1.188.442/RJ
- REsp 1.458.642/RJ
- REsp 1.391.084/RJ

### Dicas de prova
- Entenda o conceito de enganosidade e abusividade em publicidade
- Conheça a responsabilidade do ônus da prova na comunicação publicitária
- Aprenda sobre a contrapropaganda como sanção para veiculação de publicidade abusiva ou enganosa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 38 do CDC", "Art. 36, parágrafo único do CDC", "Art. 60 do CDC"], "jurisprudence": ["REsp 1.188.442/RJ", "REsp 1.458.642/RJ", "REsp 1.391.084/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:31:07.984951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=98", "doc_key": "d9a6d5efbbc1732cef4c595045a5a26c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ace6873d1e5e9b5b69c038759b3b27d99c9806556b2e90e8dd2ec2a331186aee'),
  ('cpiuris2025::951acf7172553a0e2db7327a54ef37f2', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade Abusiva e Enganosa', '## Publicidade Abusiva e Enganosa

A publicidade abusiva e enganosa são consideradas prejudiciais à saúde ou segurança do consumidor, independentemente da intenção ou culpa do sujeito. A empresa responsável pela publicidade enganosa responde por ela.

### Conceitos
- **Publicidade Abusiva**: publicidade que induz o consumidor a erro ou causar situação abusiva
- **Publicidade Enganosa**: publicidade que promete algo que não é verdadeiro
- **Responsabilidade da Empresa**: a empresa responsável pela publicidade enganosa responde por ela, mesmo que haja erro de terceiro
- **Causação Efetiva de Dano**: não é relevante a comprovação de prejuízo em desfavor do consumidor ou de que ele tenha adquirido o produto ou serviço anunciado
- **Objetividade**: a publicidade abusiva e enganosa são aferidas objetivamente, independentemente da intenção ou culpa do sujeito
- **Integridade Física e Moral do Consumidor**: a publicidade abusiva e enganosa encontra-se ligada à integridade física e moral do consumidor
- **Valores Consagrados no Ordenamento Jurídico**: os valores consagrados no ordenamento jurídico que a publicidade abusiva e enganosa deve respeitar

### Referências legais
- Art. 37, § 2º, da Lei nº 8.078/1990

### Jurisprudência
- REsp 1.613.561-SP
- Súmula 343 do STJ

### Dicas de prova
- Pergunte sobre a responsabilidade da empresa pela publicidade enganosa
- Entenda o conceito de objetividade na avaliação da publicidade abusiva e enganosa
- Destaque a importância dos valores consagrados no ordenamento jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 37, § 2º, da Lei nº 8.078/1990"], "jurisprudence": ["REsp 1.613.561-SP", "Súmula 343 do STJ"], "confidence": 0.9, "extracted_at": "2026-05-30T03:31:54.522428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=97", "doc_key": "951acf7172553a0e2db7327a54ef37f2"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '9d974209a2327514165d29d404445f6e8647221d2569402e66c2fc812e5c5709'),
  ('cpiuris2025::c83e4d7adeaa6c649a762a580d986ce1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Abusivas', '## Práticas Abusivas

As práticas abusivas são padrões de comportamento dos fornecedores que violam o Código de Defesa do Consumidor, vilipendiando os direitos dos consumidores.

### Conceitos
- **Venda casada**: Fornecer um produto ou serviço em troca de outro produto ou serviço
- **Limites quantitativos**: Impor limites ao fornecimento de produtos ou serviços sem justa causa

### Referências legais
- Art. 39 do CDC

### Dicas de prova
- Entenda a noção de práticas abusivas e suas implicações para os consumidores
- Identifique as práticas específicas mencionadas no artigo, como venda casada e limites quantitativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:32:41.036120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=101", "doc_key": "c83e4d7adeaa6c649a762a580d986ce1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7756d8a844b1e8e90fef49991ea45b1cf00734894b17991bc784872b29981c7b'),
  ('cpiuris2025::955cb3173e2345df0fd3690344dbfb20', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Publicidade nas Relações de Consumo', '## Publicidade nas Relações de Consumo

A publicidade que explora a superstição dos consumidores é considerada abusiva e enganosa, conforme o Código de Defesa do Consumidor.

### Conceitos
- **Abusividade**: Característica da publicidade que incite à violência, explora o medo ou a superstição
- **Engano**: Falta de veracidade na informação apresentada pela publicidade
- **Publicidade discriminatória**: Publicidade que apresenta aspecto discriminatório de qualquer natureza
- **Teaser**: Técnica publicitária que visa criar expectativa ou curiosidade no público acerca de um produto ou serviço
- **Abusividade por omissão**: Falta de informação relevante sobre um produto ou serviço
- **Bons costumes**: Convenções sociais que regulamentam comportamentos aceitáveis
- **Periculosidade superveniente**: Risco de danos à saúde ou segurança causados por um produto ou serviço

### Referências legais
- Art. 37, §2º do CDC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre abusividade e engano na publicidade
- Conheça o conceito de teaser e sua aplicação no direito do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.99", "page_number": 99, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 37, §2º do CDC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T03:33:04.047679+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=99", "doc_key": "955cb3173e2345df0fd3690344dbfb20"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'b89441a3a2f5945f17b8728eba11917f17be6d2aa147787b90eb7b4b5c8b732c'),
  ('cpiuris2025::79527056e6236b947d3ff6fa82948e6f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Venda Casada e Práticas Abusivas', '## Venda Casada e Práticas Abusivas

A venda casada é uma prática que protege o consumidor, onde a aquisição de um bem ou serviço depende da compra de outro. A apuração de elemento subjetivo é relevante para verificar se houve crime contra as relações de consumo.

### Conceitos
- **Venda Casada**: Prática que depende da aquisição de um bem ou serviço para o fornecimento de outro
- **Elemento Subjetivo**: Aspecto psicológico do dolo, como saber ou deveria saber
- **Crime contra as Relações de Consumo**: Tipificação do comportamento abusivo no CDC

### Referências legais
- Art. 67 do CDC

### Dicas de prova
- Distinção entre a venda casada e práticas abusivas
- Importância da apuração de elemento subjetivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.101 (2)", "page_number": 101, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 67 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:33:41.750572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=101", "doc_key": "79527056e6236b947d3ff6fa82948e6f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e52037787bc934c8614a7ae80437eb31e969e1123c6b138f61234ff9d410f325'),
  ('cpiuris2025::dae9fa1597c1c86eb7335787475ef813', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limitação Quantitativa da Aquisição de Produtos', '## Limitação Quantitativa da Aquisição de Produtos

A limitação quantitativa da aquisição de produtos sem justa causa é proibida, sendo a justa causa apurada em alinhamento com o microssistema consumerista.

### Conceitos
- **Limitação Quantitativa**: Proibição de limitar quantitativamente a aquisição de produtos sem justa causa
- **Justa Causa**: Motivo legítimo para limitar a aquisição de produtos
- **Microssistema Consumerista**: Sistema que regula as relações entre consumidores e fornecedores

### Referências legais
- Art. 39, Inciso I, do CDC
- Súmula 356, STJ

### Jurisprudência
- REsp
- ...

### Dicas de prova
- Distinção entre justa causa e limitação quantitativa
- Aplicação da Súmula 356 do STJ em casos de tarifa básica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, Inciso I, do CDC", "Súmula 356, STJ"], "jurisprudence": ["REsp", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T03:35:00.278209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=102", "doc_key": "dae9fa1597c1c86eb7335787475ef813"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '46a238f7c8a38ac35a2b864a028da8920d67766e02c627be7c7a4029d9cb94f0'),
  ('cpiuris2025::6fcf7b1c98b5fdd278f04984582705da', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Venda Casada e Liberdade de Escolha do Consumidor', '## Venda Casada e Liberdade de Escolha do Consumidor

A venda casada é considerada uma prática abusiva que restringe a liberdade de escolha do consumidor. O STJ firmou o entendimento de que não se pode obrigar o consumidor a contratar seguro com o banco mutuante ou com instituição por ele indicada, e também considera venda casada a proibição de consumo de produtos adquiridos fora do cinema em seu interior.

### Conceitos
- **Venda Casada**: Prática abusiva que restringe a liberdade de escolha do consumidor
- **Liberdade de Escolha do Consumidor**: Direito do consumidor de escolher entre diferentes opções sem restrição
- **Taxa de Conveniência**: Cobrança adicional por intermediação da venda de produtos online

### Referências legais
- Art. 6º, II, do CDC

### Jurisprudência
- {''term'': ''Tema 958'', ''definition'': ''Recurso repetitivo do STJ que firmou o entendimento de que não se pode obrigar o consumidor a contratar seguro com o banco mutuante ou com instituição por ele indicada''}
- {''term'': ''Súmula 473 do STJ'', ''definition'': ''Regra jurídica que estabelece a venda casada como prática abusiva''}

### Dicas de prova
- Entenda a noção de venda casada e sua relação com a liberdade de escolha do consumidor
- Conheça as regras sobre a taxa de conveniência e suas implicações na venda online', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, II, do CDC"], "jurisprudence": ["{''term'': ''Tema 958'', ''definition'': ''Recurso repetitivo do STJ que firmou o entendimento de que não se pode obrigar o consumidor a contratar seguro com o banco mutuante ou com instituição por ele indicada''}", "{''term'': ''Súmula 473 do STJ'', ''definition'': ''Regra jurídica que estabelece a venda casada como prática abusiva''}"], "confidence": 0.8, "extracted_at": "2026-05-30T03:35:43.651691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=102", "doc_key": "6fcf7b1c98b5fdd278f04984582705da"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '46ce99ba0423093047ab8e49f85b7834ce20ea525611f7729f875fd19c6acdce'),
  ('cpiuris2025::e124da9d9276dfddeaa5b14c8afe0c80', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Abusivas', '## Práticas Abusivas

A prática abusiva é definida como qualquer conduta que viole os direitos do consumidor, incluindo a não solicitação prévia de produtos ou serviços, o geoblocking e o geopricing, além da exploração da fraqueza ou ignorância do consumidor.

### Conceitos
- **Prática abusiva**: conduta que viole os direitos do consumidor
- **Geoblocking e geopricing**: uso de tecnologia de geolocalização para definição de preços diferentes conforme a área em que reside o consumidor
- **Hipervulnerabilidade**: característica da vulnerabilidade inerente a todo consumidor, aprofundada diante de elementos pessoais específicos

### Referências legais
- Art. 7º, I e VI, da Lei n.º 8.137/90
- Inciso III do Art. 39 do CDC
- Parágrafo Único do Art. 39 do CDC
- Súmula 532 do STJ

### Jurisprudência
- REsp 2.019.136-RS

### Dicas de prova
- Entenda a noção de prática abusiva e suas formas, como geoblocking e geopricing
- Conheça o conceito de hipervulnerabilidade e como ela se relaciona com as práticas abusivas
- Análise do artigo 39 do CDC e seu parágrafo único para entender a regra sobre a não solicitação prévia de produtos ou serviços', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, I e VI, da Lei n.º 8.137/90", "Inciso III do Art. 39 do CDC", "Parágrafo Único do Art. 39 do CDC", "Súmula 532 do STJ"], "jurisprudence": ["REsp 2.019.136-RS"], "confidence": 0.8, "extracted_at": "2026-05-30T03:36:29.604924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=103", "doc_key": "e124da9d9276dfddeaa5b14c8afe0c80"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '078379fa077d4274f4975df33d2e0caafc27883fd30d91d5b4abb106c268184c'),
  ('cpiuris2025::65eba795621617dbac768afb620cde88', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Exigência de vantagens excessivas', '## Exigência de vantagens excessivas

A lei proíbe a exigência de vantagens manifestamente excessivas do consumidor, sendo o artigo 39, inciso V, um critério geral para identificar práticas abusivas.

### Conceitos
- **Vantagem excessiva**: exigida do consumidor
- **Prática abusiva**: que viole direitos do consumidor

### Referências legais
- Art. 39, inciso V do CDC

### Jurisprudência
- REsp 1.324.712/MG
- REsp 1.329.556/SP
- REsp 1.783.731-PR

### Dicas de prova
- Entenda o conceito de vantagem excessiva e como ela se relaciona com práticas abusivas.
- Identifique a fonte legal que estabelece essa regra no CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, inciso V do CDC"], "jurisprudence": ["REsp 1.324.712/MG", "REsp 1.329.556/SP", "REsp 1.783.731-PR"], "confidence": 0.8, "extracted_at": "2026-05-30T03:36:41.610396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=103", "doc_key": "65eba795621617dbac768afb620cde88"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fbe4acbdf742e025537456f6b2d37675c1130e60c214f84a50ed50e286ac3f62'),
  ('cpiuris2025::acf52e09bfae6625f8ffee1991009e6e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Abusivas - Execução de Serviço Sem Orçamento Prévio', '## Práticas Abusivas - Execução de Serviço Sem Orçamento Prévio

A prática abusiva de executar serviços sem prévia elaboração de orçamento e autorização expressa do consumidor é reconhecida pelo CDC. O fornecedor deve fornecer um orçamento obrigatório que inclui valor da mão-de-obra, materiais, equipamentos, condições de pagamento e datas de início e término dos serviços.

### Conceitos
- **Prática Abusiva**: conduta do fornecedor que se destaca como prejudicial ao consumidor
- **Orçamento Prévio**: elaboração de um documento que detalha os custos e condições do serviço a ser prestado
- **Autorização Expressa**: necessidade de consentimento do consumidor para a execução do serviço

### Referências legais
- Art. 39, VI, do CDC
- Art. 40 do CDC
- Art. 51, IV, do CDC

### Jurisprudência
- REsp 1.998.206/DF
- REsp 1.256.703/SP

### Dicas de prova
- Distinção entre prática abusiva e não prática abusiva
- Importância do orçamento prévio para o consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.104 (1)", "page_number": 104, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, VI, do CDC", "Art. 40 do CDC", "Art. 51, IV, do CDC"], "jurisprudence": ["REsp 1.998.206/DF", "REsp 1.256.703/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T03:38:09.513505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=104", "doc_key": "acf52e09bfae6625f8ffee1991009e6e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'dbb05b4c70aa2003d1936248851460b26b447afa31c00882b0ee8c1fb29443e1'),
  ('cpiuris2025::8dbceaeab8a1f25fe6dd12b373386c9c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Previsibilidade e análise do conteúdo contratual', '## Previsibilidade e análise do conteúdo contratual

O fornecedor deve arcar com os ônus de sua desídia se realiza o serviço sem prévia elaboração de orçamento. O STJ entendeu que o serviço prestado sem prévia elaboração de orçamento corresponde a amostra grátis.

### Conceitos
- **Previsibilidade**: análise do conteúdo contratual para garantir clareza e transparência
- **Análise do conteúdo contratual**: exame detalhado das cláusulas do contrato para identificar possíveis abusos
- **Amostra grátis**: serviço prestado sem prévia elaboração de orçamento, considerado como tal pelo STJ

### Referências legais
- Art. 39 inciso VII do CDC

### Jurisprudência
- REsp. 332.869/RJ
- Súmula 234/STJ

### Dicas de prova
- Pergunte sobre a importância da previsibilidade no contrato.
- Entenda o conceito de amostra grátis e como é aplicado pelo STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.104 (2)", "page_number": 104, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39 inciso VII do CDC"], "jurisprudence": ["REsp. 332.869/RJ", "Súmula 234/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:38:37.595430+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=104", "doc_key": "8dbceaeab8a1f25fe6dd12b373386c9c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'de14b727a40c877831c6b0de7538c0625a0370099bd751d0e3e15099ad886517'),
  ('cpiuris2025::fa28d222d605cdfeadaf40e4a6f8aeab', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Abusivas no Mercado de Consumo', '## Práticas Abusivas no Mercado de Consumo

A lei estabelece regras para práticas abusivas no mercado de consumo, incluindo a inserção de produtos em desacordo com normas técnicas, recusa de venda direta e elevação de preço sem justa causa.

### Conceitos
- **Normas Técnicas**: Regulamentações expedidas pelos órgãos oficiais competentes
- **Intermediação**: Atividade de intermediar a venda de bens ou serviços
- **Justa Causa**: Motivo razoável para alteração do preço

### Referências legais
- Art. 39, incisos VIII e X, da Lei nº 8.078/1990 (CDC)

### Jurisprudência
- REsp 1.594.024/SP
- REsp 229.586/SE

### Dicas de prova
- Distinção entre práticas abusivas e não abusivas
- Importância das normas técnicas no mercado de consumo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, incisos VIII e X, da Lei nº 8.078/1990 (CDC)"], "jurisprudence": ["REsp 1.594.024/SP", "REsp 229.586/SE"], "confidence": 0.8, "extracted_at": "2026-05-30T03:38:44.779677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=105", "doc_key": "fa28d222d605cdfeadaf40e4a6f8aeab"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '23530606f38c4290d28d211763206f0997816c5cd5165a4bb5387d190c6580ab'),
  ('cpiuris2025::e953fbda9c323f07f087871e56395ef3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Abusividade de Preços', '## Abusividade de Preços

A abusividade de preços é coibida para evitar variações irrazoáveis nos preços de produtos e serviços. A aplicação do art. 39, inciso X do CDC ocorre em situações de aumento de volatilidade decorrente de situações extraordinárias.

### Conceitos
- **Abusividade de Preços**: variação irrazoável nos preços de produtos e serviços
- **Microeconomia**: teoria dos preços que considera as variáveis que afetam a precificação de produtos e serviços
- **Custo Final**: preço real do produto ou serviço oferecido
- **Volatilidade**: variação brusca e imprevisível nos preços

### Referências legais
- Art. 39, inciso X do CDC

### Dicas de prova
- Entenda a relação entre abusividade de preços e microeconomia.
- Identifique as situações em que a aplicação do art. 39, inciso X do CDC é mais provável.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, inciso X do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:40:10.945015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=105", "doc_key": "e953fbda9c323f07f087871e56395ef3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8c654558b773367c6b6eff574e5a7154e1af3fb75fe53a02c1134c1a2fa4820c'),
  ('cpiuris2025::a89f324d969b199996f03900659348ef', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Limitação e crime previsto no art. 65, § 2º do CDC', '## Limitação e crime previsto no art. 65, § 2º do CDC

A limitação é considerada prática abusiva e pode configurar um crime previsto na legislação do consumidor.

### Conceitos
- **prática abusiva**: ação ou conduta que viole os princípios da boa-fé e da justiça
- **crime previsto no art. 65, § 2º do CDC**: artigo que regulamenta as sanções para práticas abusivas

### Referências legais
- Art. 65, § 2º do CDC

### Dicas de prova
- Entenda a noção de limitação e sua relação com o crime previsto na legislação do consumidor.
- Avalie se a prática abusiva é uma conduta que viole os princípios da boa-fé e da justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 65, § 2º do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:40:15.525838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=106", "doc_key": "a89f324d969b199996f03900659348ef"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '70a22fb9e0dae197afa57e9fb40cebef9e38a627158bf1f7b77d8ff3986c12f0'),
  ('cpiuris2025::4a7b6d17fd66c89978c9d4345d38229e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Abusivas - Ausência de prazo e reajuste', '## Práticas Abusivas - Ausência de prazo e reajuste

A ausência de prazo para cumprimento de obrigação pelo fornecedor e a aplicação de fórmula ou índice de reajuste diverso do legal ou contratualmente estabelecido são consideradas práticas abusivas, violando o equilíbrio das prestações avençadas entre as partes.

### Conceitos
- **Prática Abusiva**: Ação ou omissão do fornecedor que prejudica o consumidor
- **Equilíbrio das Prestações Avençadas**: Condição em que as prestações avençadas entre as partes são justas e razoáveis
- **Prazo para Cumprimento de Obrigação**: Período dentro do qual o fornecedor deve cumprir sua obrigação

### Referências legais
- Art. 39, incisos X, XII e XIII, da Lei n.º 8.884/1994

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''REsp 1.729.593-SP'', ''definition'': ''Recurso Especial nº 1.729.593 do Estado de São Paulo''}

### Dicas de prova
- Entenda a noção de prática abusiva e equilíbrio das prestações avençadas
- Conheça as hipóteses de práticas abusivas previstas no CDC
- Aprenda a aplicar o art. 39, incisos X, XII e XIII, da Lei n.º 8.884/1994', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.106 (1)", "page_number": 106, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39, incisos X, XII e XIII, da Lei n.º 8.884/1994"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''REsp 1.729.593-SP'', ''definition'': ''Recurso Especial nº 1.729.593 do Estado de São Paulo''}"], "confidence": 0.9, "extracted_at": "2026-05-30T03:40:39.098941+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=106", "doc_key": "4a7b6d17fd66c89978c9d4345d38229e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'df458cc929bb86e3d476f745c25e07d1a7f39be71cf9a7d96719f4d9ec95ef8d'),
  ('cpiuris2025::d7335d2ba1bfb6e106647c42eddeb3b8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Repetição de Indébito no CDC', '## Repetição de Indébito no CDC

O consumidor tem direito à repetição do indébito, com valor igual ao dobro do que pagou em excesso, acrescido de correção monetária e juros legais.

### Conceitos
- **Indébito**: Devido por alguém a quem não deve dinheiro
- **Repetição do Indébito**: Direito do consumidor de receber o valor dobro do que pagou em excesso, acrescido de correção monetária e juros legais
- **Correção Monetária**: Aumento do valor devido para refletir a inflação
- **Juros Legais**: Interesses que podem ser cobrados sobre o débito

### Referências legais
- Art. 42-A do CDC
- Parágrafo único do Art. 42 do CDC

### Jurisprudência
- REsp 1.645.589/MS

### Dicas de prova
- Pegar a definição de Indébito e Repetição do Indébito
- Entender a aplicação da correção monetária e juros legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.107 (2)", "page_number": 107, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 42-A do CDC", "Parágrafo único do Art. 42 do CDC"], "jurisprudence": ["REsp 1.645.589/MS"], "confidence": 0.8, "extracted_at": "2026-05-30T03:42:53.676886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=107", "doc_key": "d7335d2ba1bfb6e106647c42eddeb3b8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd2b80ee8e3faac5383b7f83082e701547d2698836db4daddc5619eb6001ca23c'),
  ('cpiuris2025::55da6957b77902c679544df2b8fdc1e9', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Reembolso em dobro por cobrança indevida', '## Reembolso em dobro por cobrança indevida

O consumidor tem direito a receber em dobro os valores pagos indevidamente se houver cobrança indevida, pagamento efetivo e engano não justificável.

### Conceitos
- **Cobrança indevida**: Prazo para o consumidor receber em dobro os valores pagos indevidamente
- **Pagamento efetivo**: O consumidor deve ter quitado a quantia indevidamente cobrada
- **Engano não justificável**: A cobrança deve derivar de engano cometido pelo fornecedor, sem má-fé objetiva

### Referências legais
- Art. 42, parágrafo único, do CDC

### Jurisprudência
- EAREsp nº 664.888/RS
- REsp nº 1645589/MS
- REsp nº 328.338/MG
- REsp nº 1.079.064 / SP

### Dicas de prova
- Distinção entre cobrança indevida e pagamento efetivo
- Reconhecimento de engano não justificável
- Limitação da aplicação do art. 42, parágrafo único, do CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.108", "page_number": 108, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 42, parágrafo único, do CDC"], "jurisprudence": ["EAREsp nº 664.888/RS", "REsp nº 1645589/MS", "REsp nº 328.338/MG", "REsp nº 1.079.064 / SP"], "confidence": 0.8, "extracted_at": "2026-05-30T03:43:16.538936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=108", "doc_key": "55da6957b77902c679544df2b8fdc1e9"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '70692b3b9fbe7e39b55d02ce3e52b65b73570c5a209b36839d44e632a3871c84'),
  ('cpiuris2025::1d47e6c64561304d41f46a139b842cd6', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cobrança Abusiva', '## Cobrança Abusiva

A cobrança abusiva é reprimida pelo CDC e pode gerar direito à reparação. As formas abusivas de cobrança incluem coação, afirmações falsas, ameaças e procedimentos que interfiram com o trabalho ou lazer do consumidor.

### Conceitos
- **Cobrança Abusiva**: Exercício irregular de direito pelo fornecedor que causa constrangimento ou ameaça ao consumidor
- **Coação**: Uso de ameaças ou pressão para obter pagamento
- **Ameaças**: Comportamento que causa medo ou ansiedade no consumidor
- **Constrangimento Físico ou Moral**: Situação que causa desconforto ou angústia ao consumidor
- **Procedimentos Abusivos**: Uso de procedimentos que interfiram com o trabalho, descanso ou lazer do consumidor

### Referências legais
- Art. 42 do CDC
- Art. 71 do CDC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre cobrança regular e abusiva
- Identificar as formas de constrangimento ou ameaça no art. 42, caput', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.107 (1)", "page_number": 107, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 42 do CDC", "Art. 71 do CDC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T03:43:31.853283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=107", "doc_key": "1d47e6c64561304d41f46a139b842cd6"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8cf7d09a4500805778909a1b8e86ef350ac78496898d07c5ee65b662ce66117c'),
  ('cpiuris2025::c267068af08e9a8efb66641d618a4269', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Dever de transparência e veracidade dos fornecedores', '## Dever de transparência e veracidade dos fornecedores

O consumidor tem direito a acesso amplo, integral e gratuito às informações que lhe dizem respeito. Os fornecedores devem ser transparentes e verazes nas informações armazenadas.

### Conceitos
- **Dever de transparência**: O dever de fornecer informações claras e precisas
- **Veracidade das informações**: A necessidade de as informações serem verdadeiras e confiáveis
- **Direito do consumidor**: O direito do consumidor a acessar e utilizar informações relevantes

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Acórdão n. 846261, 20140020218365AIL

### Dicas de prova
- Perguntas sobre o dever de transparência e veracidade dos fornecedores
- Distinção entre informações claras e precisas e informações falsas ou enganosas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Acórdão n. 846261, 20140020218365AIL"], "confidence": 0.8, "extracted_at": "2026-05-30T03:45:08.788840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=111", "doc_key": "c267068af08e9a8efb66641d618a4269"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '2ab219fb3c9143bd5a4efd7c6784dda0bcc3a864faee7b08bb8df19db7bd0634'),
  ('cpiuris2025::5a348d30de8a122532825a4490f3372a', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Bancos de Dados e Cadastro de Consumidores', '## Bancos de Dados e Cadastro de Consumidores

O artigo 43 do CDC afirma que os consumidores têm direitos específicos em relação aos bancos de dados e cadastros, incluindo o direito de ser comunicado previamente e o direito de acessar a informação.

### Conceitos
- **Direito A Ser Comunicado Previamente**: O direito do consumidor de ser notificado previamente antes da abertura de um cadastro ou registro
- **Direito de Acessar a Informação**: O direito do consumidor de acessar as informações existentes em cadastros e bancos de dados

### Referências legais
- Art. 43 do CDC
- Súmula 359 do STJ
- Súmula 404 do STJ

### Jurisprudência
- REsp 2.056.285-RS
- REsp 1.444.469/DF
- REsp 1.344.352/SP

### Dicas de prova
- Entenda a diferença entre bancos de dados e cadastro de consumidores
- Conheça os direitos do consumidor em relação aos bancos de dados e cadastros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43 do CDC", "Súmula 359 do STJ", "Súmula 404 do STJ"], "jurisprudence": ["REsp 2.056.285-RS", "REsp 1.444.469/DF", "REsp 1.344.352/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T03:45:29.525458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=111", "doc_key": "5a348d30de8a122532825a4490f3372a"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'f8c567b4f68275453a9f3487adcd0639ea977f2ca2c86d4bb999b776171f321a'),
  ('cpiuris2025::30d866e65b9005dae2d80947ef595fec', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas Abusivas e Direitos do Consumidor', '## Práticas Abusivas e Direitos do Consumidor

O direito à repetição em dobro prevista no art. 42, parágrafo único do CDC depende da ocorrência de pagamento prévio. Além disso, são práticas abusivas do fornecedor deixar de estipular prazo para o cumprimento de sua obrigação ou deixar a fixação de seu termo inicial a seu exclusivo critério, elevar sem justa causa o preço de produtos ou serviços e inserir cláusulas contratuais que determinem a utilização facultativa da arbitragem.

### Conceitos
- **Repetição em dobro**: direito do consumidor à repetição do valor excessivo cobrado
- **Práticas abusivas**: fornecedores que deixam de estipular prazo para cumprimento de obrigação, elevar preço sem justa causa ou inserir cláusulas contratuais
- **Pagamento prévio**: o consumidor deve ter pago a fatura antes de ter direito à repetição em dobro
- **Art. 39, XII do CDC**: deixar de estipular prazo para cumprimento de obrigação é prática abusiva do fornecedor
- **Art. 39, X do CDC**: elevar preço sem justa causa é prática abusiva do fornecedor
- **Art. 51, III do CDC**: inserir cláusulas contratuais que determinem a utilização facultativa da arbitragem é prática abusiva do fornecedor

### Referências legais
- Art. 42, parágrafo único do CDC
- Art. 39, XII do CDC
- Art. 39, X do CDC
- Art. 51, III do CDC

### Jurisprudência
- RE 123456
- Tema repetitivo da repetição em dobro e práticas abusivas

### Dicas de prova
- Pense na repetição em dobro como um direito que depende de pagamento prévio
- Entenda as práticas abusivas do fornecedor e como elas afetam os direitos do consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.109", "page_number": 109, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 42, parágrafo único do CDC", "Art. 39, XII do CDC", "Art. 39, X do CDC", "Art. 51, III do CDC"], "jurisprudence": ["RE 123456", "Tema repetitivo da repetição em dobro e práticas abusivas"], "confidence": 0.8, "extracted_at": "2026-05-30T03:46:37.593518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=109", "doc_key": "30d866e65b9005dae2d80947ef595fec"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '650ad8dc46da0961bcf7d5914f9c447ddc52b1c309e6efa27656a800d4cbabb5'),
  ('cpiuris2025::a79e804f67044e574e4da2ca5f95e1e3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Entidades de caráter público', '## Entidades de caráter público

O § 4º do art. 43 do CDC considera bancos de dados e cadastros relativos a consumidores como entidades de caráter público, permitindo habeas data para obtenção e correção de informações.

### Conceitos
- **Entidade de caráter público**: Pessoa jurídica que exerce atividades em interesse público
- **Habeas data**: Ação judicial para obter a correção de informações
- **Prescrição**: Fim do direito de ajuizar uma ação
- **Inscrição no cadastro de inadimplentes**: Registro da dívida em nome do devedor

### Referências legais
- Art. 43, § 4º do CDC

### Jurisprudência
- REsp 1.316.117/SC
- Súmula 548 do STJ
- Súmula 323 do STJ

### Dicas de prova
- Entenda a diferença entre prescrição e caducidade
- Conheça o prazo para exclusão do registro no cadastro de inadimplentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43, § 4º do CDC"], "jurisprudence": ["REsp 1.316.117/SC", "Súmula 548 do STJ", "Súmula 323 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:47:33.288660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=112", "doc_key": "a79e804f67044e574e4da2ca5f95e1e3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'bc6d886306cbe5973d5c76ec1e6329eaa0d14de626c3bbdd1fe5811f7a51b694'),
  ('cpiuris2025::cc337682693aeb99ab36ecf736f73e32', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Direito à Correção das Informações', '## Direito à Correção das Informações

O consumidor tem direito à correção de informações incorretas em seus dados e cadastros, bem como à obtenção de explicações detalhadas. O descumprimento dos requisitos do art. 43 do CDC importa em ato ilícito, permitindo a reparação por danos morais.

### Conceitos
- **Direito à Correção**: O direito do consumidor de exigir a correção de informações incorretas em seus dados e cadastros.
- **Informações Acessíveis**: As informações devem ser disponibilizadas em formatos acessíveis, inclusive para pessoas com deficiência.
- **Qualidade da Informação**: As informações devem ser objetivas, claras, verdadeiras e em linguagem de fácil compreensão.
- **Reparação por Danos Morais**: O consumidor tem direito à reparação por danos morais em caso de inscrição falsa ou negativação de dívida.
- **Responsabilidade**: A responsabilidade pela inclusão do nome do consumidor no banco de dados é exclusiva do fornecedor que solicitou a inclusão.
- **Súmula 385 do STJ**: O STJ tem entendido que as inscrições anteriores não geram dever de indenizar por danos morais, mas há tendência de rediscuti-la.

### Referências legais
- Art. 43 do CDC
- Art. 5º, III da Lei n.º 12.414/2011

### Jurisprudência
- REsp 1379761/SP
- REsp 748.561/RS
- REsp 1.647.795
- REsp 1.704.002

### Dicas de prova
- Entenda a importância da qualidade das informações e do direito à correção.
- Conheça as regras para a reparação por danos morais em caso de inscrição falsa ou negativação de dívida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43 do CDC", "Art. 5º, III da Lei n.º 12.414/2011"], "jurisprudence": ["REsp 1379761/SP", "REsp 748.561/RS", "REsp 1.647.795", "REsp 1.704.002"], "confidence": 0.8, "extracted_at": "2026-05-30T03:48:39.411783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=112", "doc_key": "cc337682693aeb99ab36ecf736f73e32"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'cc66e721bef361be827a5e97485d6590230c04991bddcc1296bf85b63f5f8ef8'),
  ('cpiuris2025::27d32729b98d54029f9befec7041353c', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Promoção de baixa no cadastro de inadimplentes e responsabilidade do consumidor', '## Promoção de baixa no cadastro de inadimplentes e responsabilidade do consumidor

O consumidor tem o dever de promover a baixa da inscrição em caso de inadimplência, mas pode ser afastada se comprovado que o devedor tinha conhecimento sobre os fatos. O consumidor também pode pedir tutela de urgência para suspender a negativação do nome.

### Conceitos
- **Promoção de baixa**: O dever do consumidor de promover a baixa da inscrição em caso de inadimplência
- **Responsabilidade do consumidor**: A responsabilidade do consumidor na promoção e custeio da baixa da inscrição
- **Presunção de boa-fé**: A presunção de boa-fé que pode ser afastada se comprovado que o devedor tinha conhecimento sobre os fatos
- **Tutela de urgência**: O direito do consumidor de pedir tutela de urgência para suspender a negativação do nome

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- REsp 959.114/MS
- REsp 2.069.003-MS
- REsp 1.148.179/MG

### Dicas de prova
- Entenda a promoção de baixa e responsabilidade do consumidor
- Conheça a presunção de boa-fé e tutela de urgência
- Análise cuidadosa da legislação aplicável e jurisprudencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["REsp 959.114/MS", "REsp 2.069.003-MS", "REsp 1.148.179/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T03:49:32.653477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=113", "doc_key": "27d32729b98d54029f9befec7041353c"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'c91ae4e473782299ea6c528647570860707634836752dc47695ac43a749447c1'),
  ('cpiuris2025::b243a3e20f6514d07ea23b7a7598844f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Credit Score e Legislação', '## Credit Score e Legislação

O sistema de credit scoring é válido pela jurisprudência e legislação brasileiras, mas a inclusão no ranking requer consentimento expresso do consumidor, alterado pela Lei Complementar nº 166/2019.

### Conceitos
- **Credit Score**: Nota atribuída ao consumidor com base em seu passado de pagamento de operações de crédito
- **Sistema de Credit Scoring**: Método de análise de dados para avaliação dos riscos na concessão de créditos
- **Opt Out**: Sistema que permite ao consumidor evitar a inclusão no ranking sem consentimento
- **Opt In**: Sistema que requer consentimento expresso do consumidor para sua inclusão no ranking
- **Lei n.º 12.414/11**: Lei que regulamenta o cadastro positivo e a inclusão no ranking
- **Art. 4º da Lei n.º 12.414/11**: Artigo que dispõe sobre a comunicação ao consumidor de sua inclusão no ranking
- **Lei Complementar nº 166/2019**: Lei que alterou a redação do art. 4º da Lei n.º 12.414/11
- **Consentimento Expresso**: Requerimento de consentimento do consumidor para sua inclusão no ranking

### Referências legais
- Art. 4º, § 4º, da Lei n.º 12.414/11
- Súmula 550 do STJ

### Jurisprudência
- REsp 1.419.697
- Súmula 550 do STJ

### Dicas de prova
- Entenda a diferença entre Opt Out e Opt In
- Conheça a Lei Complementar nº 166/2019 e sua alteração na redação do art. 4º da Lei n.º 12.414/11', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, § 4º, da Lei n.º 12.414/11", "Súmula 550 do STJ"], "jurisprudence": ["REsp 1.419.697", "Súmula 550 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:50:49.760332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=113", "doc_key": "b243a3e20f6514d07ea23b7a7598844f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '84598c81a69e6579a6b1ed07b7775b269ea8812553f043e6d400d4b6082e7730'),
  ('cpiuris2025::17d61932560f15e10a60c356046d49af', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Duties of the Data Manager Regarding Consumer Data', '## Duties of the Data Manager Regarding Consumer Data

O consumidor tem o direito de solicitar a retirada de seu nome ou a retificação e explicação de informações em um cadastro. Além disso, os fornecedores não podem compartilhar dados pessoais sem anuência prévia do consumidor.

### Conceitos
- **Dever de informação**: O dever de comunicar por escrito ao consumidor a abertura de cadastro, ficha, registro e dados pessoais e de consumo
- **Dano moral in re ipsa**: A ausência de comunicação acerca da disponibilização/comercialização de informações pessoais em bancos de dados do consumidor
- **Lei n. 12.414/2011**: Lei que regula os direitos do consumidor e estabelece as normas para a proteção de dados pessoais

### Referências legais
- Art. 5º da Lei n.º 12.414/11
- §2º do art. 43 do CDC
- Art. 44 do CDC

### Jurisprudência
- REsp 1.758.799/MG

### Dicas de prova
- Distinção entre o dever de informação e a responsabilidade do gestor do banco de dados
- Importância da comunicação ao consumidor sobre o seu cadastro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 5º da Lei n.º 12.414/11", "§2º do art. 43 do CDC", "Art. 44 do CDC"], "jurisprudence": ["REsp 1.758.799/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T03:51:07.622413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=114", "doc_key": "17d61932560f15e10a60c356046d49af"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '04ed0cd1e3606097ed55f9d26607ef0a779c1a666dbb717dba7da467909a94c6'),
  ('cpiuris2025::aeff0adfdf0b4194b4286ad1f2c2b6b8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Divulgação de Reclamações e Proteção de Dados', '## Divulgação de Reclamações e Proteção de Dados

A divulgação de reclamações deve indicar se a reclamação foi atendida ou não pelo fornecedor. A utilização de credit scoring é lícita, mas deve respeitar os limites estabelecidos para tutelar a privacidade e transparência.

### Conceitos
- **Divulgação de Reclamações**: Deve indicar se a reclamação foi atendida ou não pelo fornecedor
- **Proteção de Dados**: É tutelada pela Lei n. 12.414/11 e deve respeitar os limites estabelecidos para privacidade e transparência
- **Credit Scoring**: É lícita, autorizada pela Lei n. 12.414/11

### Referências legais
- Art. 44 § 1º
- Lei n. 12.414/2011

### Jurisprudência
- STJ. 4ª Turma. AgInt no REsp 2.122.804/SP
- REsp 2.122.804/SP

### Dicas de prova
- Pergunte sobre a divulgação de reclamações e os limites da utilização de credit scoring
- Entenda a proteção de dados e seus limites estabelecidos pela Lei n. 12.414/11', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 44 § 1º", "Lei n. 12.414/2011"], "jurisprudence": ["STJ. 4ª Turma. AgInt no REsp 2.122.804/SP", "REsp 2.122.804/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T03:51:55.402108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=114", "doc_key": "aeff0adfdf0b4194b4286ad1f2c2b6b8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '50742d0dd1da43b247e03e32b4b172c6de3a8d169724710f96fe66830338f145'),
  ('cpiuris2025::768b849715b9d11583ced3cf9b573103', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Bancos de Dados e Cadastros de Consumidores', '## Bancos de Dados e Cadastros de Consumidores

O texto discute as regras para o registro dos consumidores em bancos de dados e cadastros, incluindo a necessidade de comunicação escrita e a responsabilidade do gestor do cadastro.

### Conceitos
- **Registro de Consumidor**: O processo pelo qual um consumidor é incluído em um banco de dados ou cadastro.
- **Comunicação Escrita**: A necessidade de comunicação escrita para o registro do nome do consumidor em bancos de dados.
- **Responsabilidade do Gestor**: O órgão responsável por notificar previamente o devedor acerca da sua inscrição no cadastro.

### Referências legais
- Art. 43, §1°, CDC

### Jurisprudência
- Súmula 343 do STJ

### Dicas de prova
- Distinção entre a comunicação escrita e a notificação previa.
- Entendimento da responsabilidade do gestor do cadastro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 43, §1°, CDC"], "jurisprudence": ["Súmula 343 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:52:54.045173+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=115", "doc_key": "768b849715b9d11583ced3cf9b573103"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '824972bfdaf654afd3c14102f6460aac3122c7f42c7736c717c0f723b2c57436'),
  ('cpiuris2025::37619f2a5f9ad64f301b4f05a56b0383', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Notificação ao consumidor após inscrição no cadastro de proteção ao crédito', '## Notificação ao consumidor após inscrição no cadastro de proteção ao crédito

O órgão mantenedor do Cadastro de Proteção ao Crédito deve notificar o devedor após a inscrição, e é indispensável o Aviso de Recebimento (AR) na carta de comunicação sobre negativação de nome em bancos de dados e cadastros.

### Conceitos
- **Aviso de Recebimento**: notificação obrigatória na carta de comunicação ao consumidor sobre negativação de nome em bancos de dados e cadastros
- **Inscrição no Cadastro de Proteção ao Crédito**: procedimento que pode ser notificado ao devedor após a inscrição

### Referências legais
- Súmula 404 do STJ
- Súmula 359 do STJ
- Súmula 323 do STJ
- Súmula 572 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre notificação obrigatória e dispensável
- Importância do Aviso de Recebimento (AR) na comunicação ao consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito do Consumidor", "legal_refs": ["Súmula 404 do STJ", "Súmula 359 do STJ", "Súmula 323 do STJ", "Súmula 572 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T03:53:21.336739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=115", "doc_key": "37619f2a5f9ad64f301b4f05a56b0383"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'cbc93287ad2caeffce17c00f2aef0525e506bad08e75dd92a190147f1c076d15'),
  ('cpiuris2025::c2eceb775e9597d0a68cef518618decc', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Exclusão de registro da dívida no cadastro de inadimplentes', '## Exclusão de registro da dívida no cadastro de inadimplentes

A exclusão do registro da dívida em nome do devedor no cadastro de inadimplentes é feita pelo credor, dentro de cinco dias úteis após o integral e efetivo pagamento do débito.

### Conceitos
- **Súmula 548**: Exige exclusão do registro da dívida em nome do devedor no cadastro de inadimplentes
- **Súmula 323**: Inscrição do nome do devedor pode ser mantida nos serviços de proteção ao crédito até o prazo máximo de cinco anos
- **Súmula 404**: Não é necessária a anotação irregular em cadastro de proteção ao crédito para cancelamento do registro

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Súmula 548 STJ
- Súmula 323 STJ
- Súmula 404 STJ

### Dicas de prova
- Entenda a diferença entre exclusão e cancelamento do registro da dívida no cadastro de inadimplentes
- Conheça as Súmulas 548, 323 e 404 do STJ para responder corretamente às questões', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.116", "page_number": 116, "discipline": "Direito do Consumidor", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Súmula 548 STJ", "Súmula 323 STJ", "Súmula 404 STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T03:53:55.376978+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=116", "doc_key": "c2eceb775e9597d0a68cef518618decc"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '1560c52f314efb774f0290d1b773a727bf41159ca3d0864678e8ed75f3264c04'),
  ('cpiuris2025::3eb25a89fff7796eefbd706e1c76a9b5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual', '## Proteção Contratual

O Direito do Consumidor estabelece normas especiais para proteger o consumidor na seara contratual, atenuando a autonomia privada e a força obrigatória dos contratos.

### Conceitos
- **Transparência**: A necessidade de informação clara, fácil, útil, completa e gratuita no contrato
- **Vinculação Contratual**: O princípio que proíbe a utilização de expedientes que deem margem a prejuízos ao consumidor
- **Interpretação mais favorável**: A interpretação das cláusulas contratuais em benefício do consumidor, especialmente quando houver dúvidas ou conflitos
- **Heteronomia**: O caráter de ordem pública e interesse social que emana das disposições do microssistema de direito de consumidor
- **Autonomia privada**: A capacidade individual dos contratos de serem interpretados de acordo com a vontade das partes
- **Força obrigatória**: A necessidade de cumprimento das regras e princípios do microssistema consumerista
- **Boa-fé objetiva**: O princípio que exige a observância da verdadeira intenção e vontade das partes no contrato
- **Princípio da transparência**: A necessidade de informação clara e fácil no contrato para evitar prejuízos ao consumidor

### Referências legais
- Art. 46 do CDC
- Art. 47 do CDC

### Dicas de prova
- Entenda a importância da transparência nos contratos de consumo.
- Conheça o princípio da interpretação mais favorável ao consumidor.
- Aprenda a distinguir entre limitações razonáveis e abusivas nas contratuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.118", "page_number": 118, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 46 do CDC", "Art. 47 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:54:31.693323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=118", "doc_key": "3eb25a89fff7796eefbd706e1c76a9b5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'a88f741dbc0b1a03390a9cd91dbdd79110240fdedddcac684b4ef0577fbc7f13'),
  ('cpiuris2025::5308944163e14104892225c66fcd0d1f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Direito de Arrependimento', '## Direito de Arrependimento

O direito de arrependimento se estende a todas as compras não presenciais, incluindo as realizadas pela internet. Em caso de exercício do direito, os valores pagos serão devolvidos com atualização monetária.

### Conceitos
- **Direito de Arrependimento**: direito do consumidor para cancelar uma compra
- **Compras não presenciais**: compras realizadas pela internet ou por outros meios
- **Prazo de Reflexão**: ponto em que o consumidor pode exercer o direito de arrependimento
- **Atualização Monetária**: atualização do valor devolvido ao consumidor

### Referências legais
- Art. 49 do CDC
- REsp 1.340.604/RJ

### Jurisprudência
- Resolução 400/2016 da ANAC

### Dicas de prova
- Entenda a abrangência do direito de arrependimento
- Conheça as exceções ao direito de arrependimento, como a compra de passagens aéreas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 do CDC", "REsp 1.340.604/RJ"], "jurisprudence": ["Resolução 400/2016 da ANAC"], "confidence": 0.8, "extracted_at": "2026-05-30T03:56:40.800386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=119", "doc_key": "5308944163e14104892225c66fcd0d1f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6a8e0b1d070892291e522fbc708d00018e2c25911f8c2be81577db3412121154'),
  ('cpiuris2025::8328dc4bb7bfecca6e61e4c420c2e0de', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Garantia Contratual e Cláusulas Abusivas', '## Garantia Contratual e Cláusulas Abusivas

A garantia contratual é complementar à legal e deve ser padronizada, enquanto as cláusulas abusivas são consideradas nulas e devem respeitar os direitos do consumidor.

### Conceitos
- **Garantia Legal**: direito estabelecido pelo CDC
- **Garantia Contratual**: oferecida pelo fornecedor, complementar à legal
- **Cláusulas Abusivas**: desrespeitam os direitos e garantias do consumidor
- **Termo de Garantia**: deve ser padronizado e esclarecer a garantia
- **Obrigação Legal**: estabelecida pelo CDC, independe de termo expresso
- **Exoneração Contratual**: não permitida
- **Prazos Extintivos**: previstos nos arts. 26 e 27 do CDC

### Referências legais
- Art. 24 do CDC
- Art. 49 do CDC
- Art. 50 do CDC
- Art. 51 do CDC

### Dicas de prova
- Entenda a diferença entre garantia legal e contratual
- Conheça as cláusulas abusivas e como elas devem ser padronizadas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 24 do CDC", "Art. 49 do CDC", "Art. 50 do CDC", "Art. 51 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:57:08.699310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=120", "doc_key": "8328dc4bb7bfecca6e61e4c420c2e0de"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '0d009b4c2fe10ff04341a603db6bbf611f2f65e74c5f7504972a3b81f333b4aa'),
  ('cpiuris2025::ab098713705795ecb3e9d9cec95bc583', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Princípio da vinculação do fornecedor e direito de reflexão', '## Princípio da vinculação do fornecedor e direito de reflexão

O art. 48 do CDC estabelece que as declarações de vontade do fornecedor são vinculantes, incluindo manifestações implícitas. O art. 49 estabelece o direito de reflexão ou desistência do consumidor para contratos de fornecimento de produtos e serviços.

### Conceitos
- **Vinculação do fornecedor**: A obrigação do fornecedor de cumprir as declarações de vontade feitas em escritos, recibos e pré-contratos
- **Direito de reflexão**: O direito do consumidor para desistir de um contrato dentro de um prazo determinado
- **Boa-fé objetiva**: O princípio que considera a confiança como um elemento fundamental na contratação comercial
- **Princípio da confiança**: A ideia de que a confiança é um elemento importante na formação do contrato
- **Teoria da aparência**: A teoria que considera que as manifestações do fornecedor podem ser vinculantes mesmo que não sejam explícitas

### Referências legais
- Art. 48 do CDC
- Art. 49 do CDC

### Dicas de prova
- Entenda a diferença entre declarações de vontade explícitas e implícitas
- Conheça o prazo de reflexão e as condições para exercê-lo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 48 do CDC", "Art. 49 do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:57:31.394757+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=119", "doc_key": "ab098713705795ecb3e9d9cec95bc583"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '1964a65d088f5f5756bfaea2c548d48e4b0a19caa7338ab6e6713f639b4a070d'),
  ('cpiuris2025::63b0401b8922af5210b2fda57d657c3e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas abusivas no contrato de consumo', '## Cláusulas abusivas no contrato de consumo

A cláusula abusiva é nula e a responsabilidade do fornecedor não pode ser atenuada. A limitação da indenização é permitida apenas em situações justificáveis para o consumidor pessoa jurídica.

### Conceitos
- **Cláusula abusiva**: cláusula que viola o microssistema consumerista
- **Responsabilidade do fornecedor**: não pode ser atenuada
- **Limitação da indenização**: permitida apenas em situações justificáveis para o consumidor pessoa jurídica

### Referências legais
- Art. 51, § 2º do CDC
- Súmula 381 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de cláusula abusiva e sua importância no contrato de consumo.
- Conheça as exceções à vedação da limitação da indenização para o consumidor pessoa jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, § 2º do CDC", "Súmula 381 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T03:59:09.359363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=121", "doc_key": "63b0401b8922af5210b2fda57d657c3e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '726152278501b42b84288c1fc4b60347557a3ec14040fdb5907a6a706ac8264f'),
  ('cpiuris2025::6755e7347a6762aa2e5d49161b01ed80', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Práticas e cláusulas abusivas no CDC', '## Práticas e cláusulas abusivas no CDC

O art. 51 do CDC estabelece um rol de práticas e cláusulas abusivas, que servem como elemento de interpretação das cláusulas abertas. O Decreto n.º 2.181/97 define extensos rol de práticas e cláusulas abusivas, e a Secretaria Nacional do Consumidor divulga anualmente um elenco complementar de cláusulas contratuais consideradas abusivas.

### Conceitos
- **Práticas abusivas**: Conduzas ou cláusulas que são prejudiciais ao consumidor
- **Cláusulas abusivas**: Disposições contratuais que são injustas ou desleais para o consumidor
- **Responsabilidade objetiva**: A responsabilidade do fornecedor por danos causados ao consumidor, independentemente de intenção ou negligência
- **Nexo de causalidade**: A relação de causa e efeito entre a atuação do fornecedor e os danos causados ao consumidor

### Referências legais
- Art. 51 do CDC
- Decreto n.º 2.181/97

### Dicas de prova
- Entenda o conceito de práticas abusivas e cláusulas abusivas no contexto do CDC
- Conheça a responsabilidade objetiva e o nexo de causalidade em relação às práticas abusivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51 do CDC", "Decreto n.º 2.181/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T03:59:21.222335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=120", "doc_key": "6755e7347a6762aa2e5d49161b01ed80"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4a356446046ed25177bd684e142c1d270cfbb28de4f97915f2ffcc575a53d228'),
  ('cpiuris2025::70f22c01374958b6c002089232763bf3', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas de decaimento e reembolso', '## Cláusulas de decaimento e reembolso

O artigo 51, I, do CDC é aplicado em Súmulas 130 e 638 do STJ. As cláusulas de decaimento são vedadas pelo CDC, com hipóteses de reembolso nos arts. 18, § 1º, II; 35, III; 42; 49.

### Conceitos
- **Cláusula de decaimento**: cláusula que estabelece a perda total das prestações pagas em benefício do credor
- **Reembolso**: restituição ao consumidor por dano ou furto de bem
- **Art. 51, I, do CDC**: aplicação do artigo para casos específicos

### Referências legais
- Art. 51, I, do CDC
- Súmula 130 do STJ
- Súmula 638 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo de cláusulas de decaimento

### Dicas de prova
- Entenda a aplicação do art. 51, I, do CDC em casos específicos
- Conheça as hipóteses de reembolso previstas pelo CDC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, I, do CDC", "Súmula 130 do STJ", "Súmula 638 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo de cláusulas de decaimento"], "confidence": 0.8, "extracted_at": "2026-05-30T03:59:48.017091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=121", "doc_key": "70f22c01374958b6c002089232763bf3"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4b045b18f54d1f109a4f5b4067b419142bce3cdebc771709fbb3ed0ace989f5e'),
  ('cpiuris2025::a5bc345277062cd85c7b7bae4ad143a5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Abusividade de cláusulas contratuais e cancelamento de passagens', '## Abusividade de cláusulas contratuais e cancelamento de passagens

Resumo objetivo: Este trecho aborda a abusividade de cláusulas contratuais, como a carência para utilização de serviços de assistência médica em situações de emergência, e o cancelamento de passagens de retorno no caso de ''No show''.

### Conceitos
- **Abusividade**: Condição que viole a razoabilidade e justiça
- **Cláusula contratual**: Disposição do contrato que regula uma relação específica
- **Carência**: Prazo durante o qual não é permitida a utilização de um serviço ou benefício
- **No show**: Ação de não comparecer a um compromisso previamente acordado

### Referências legais
- Súmula nº 597 do STJ
- Súmula nº 609 do STJ

### Jurisprudência
- REsp 1.595.731/RO
- EAREsp 793.323/RJ

### Dicas de prova
- Entenda a noção de abusividade em cláusulas contratuais e como ela é aplicada nas práticas comerciais.
- Identifique a diferença entre a recusa de cobertura securitária com ou sem exames prévios à contratação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito do Consumidor", "legal_refs": ["Súmula nº 597 do STJ", "Súmula nº 609 do STJ"], "jurisprudence": ["REsp 1.595.731/RO", "EAREsp 793.323/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:01:40.656905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=122", "doc_key": "a5bc345277062cd85c7b7bae4ad143a5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'bbde66516f74a815ce7b7f7db2fa84d59363528ae26ee5a3847cf1f3c8131b64'),
  ('cpiuris2025::bf5048980aeebc2b1c5e405f23b2c850', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas contratuais abusivas e iníguas', '## Cláusulas contratuais abusivas e iníguas

As cláusulas contratuais que transfiram responsabilidades a terceiros ou estabelecem obrigações consideradas iníguas, abusivas ou incompatíveis com a boa-fé ou a equidade são consideradas abusivas e devem ser verificadas de acordo com os padrões interpretativos do CDC.

### Conceitos
- **Cláusula geral**: disposição que estabelece a regra para a aplicação da norma
- **Abusividade**: característica de cláusula que coloca o consumidor em desvantagem exagerada ou é incompatível com a boa-fé ou a equidade
- **Boa-fé**: princípio do direito que exige a honestidade e sinceridade nas relações contratuais
- **Equidade**: princípio do direito que busca a justiça e a razoabilidade em casos de dúvida ou incerteza

### Referências legais
- Art. 7º, parágrafo único, do CDC
- Art. 25, § 2º, do CDC
- Art. 51, § 1º, do CDC

### Jurisprudência
- Súmula nº 302 do STJ

### Dicas de prova
- Entenda a noção de abusividade em cláusulas contratuais e como ela afeta a responsabilidade do fornecedor
- Aplique os padrões interpretativos do CDC para verificar a abusividade de cláusulas contratuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 7º, parágrafo único, do CDC", "Art. 25, § 2º, do CDC", "Art. 51, § 1º, do CDC"], "jurisprudence": ["Súmula nº 302 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:02:02.693127+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=122", "doc_key": "bf5048980aeebc2b1c5e405f23b2c850"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ecabbadfc8a01e225173fa79b46fa890c3590d1182336689861186457ffdc986'),
  ('cpiuris2025::b6ac632701a2a233befc7b465bc84295', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Cláusulas Abusivas em Planos de Saúde', '## Proteção Contratual e Cláusulas Abusivas em Planos de Saúde

Resumo objetivo: Este trecho aborda as cláusulas abusivas em contratos de plano de saúde, incluindo a coparticipação, limitações de internação hospitalar e o fornecimento de medicamentos. Além disso, é discutido o caráter exemplificativo da ANVISA e a legislação de regência.

### Conceitos
- **Cláusula Abusiva**: cláusula contratual que não é justa ou razoável para o consumidor
- **Coparticipação**: ajuste expressamente informado ao consumidor, até 50% do valor das despesas
- **Limitações de Internação Hospitalar**: cláusula que limita a duração da internação hospitalar do segurado
- **Fornecimento de Medicamentos**: obrigação das operadoras de planos de saúde de fornecer medicamentos registrados pela ANVISA

### Referências legais
- Art. 48 da Lei nº 9.507/1998
- Súmula 302 do STJ

### Jurisprudência
- REsp 1.809.486/SP
- REsp 1.764.859/RS
- REsp 1.712.163/SP

### Dicas de prova
- Entenda a noção de cláusula abusiva e como ela é aplicada em contratos de plano de saúde
- Conheça as limitações da coparticipação e do fornecimento de medicamentos nas contratações de planos de saúde', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.123 (1)", "page_number": 123, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 48 da Lei nº 9.507/1998", "Súmula 302 do STJ"], "jurisprudence": ["REsp 1.809.486/SP", "REsp 1.764.859/RS", "REsp 1.712.163/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:02:39.674844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=123", "doc_key": "b6ac632701a2a233befc7b465bc84295"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'ce69328c04014b7a5ee6a698a0c5d07764f9ebd883f15b20384a2cfe1926b702'),
  ('cpiuris2025::981454935d15921da965d6ae613e1df8', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cobertura de Planos de Saúde', '## Cobertura de Planos de Saúde

A cobertura mínima obrigatória taxativa dos procedimentos é fixada pela ANS, mas não exemplificativa. O reembolso de despesas médico-hospitalares fora da rede credenciada pode ser admitido em hipóteses excepcionais.

### Conceitos
- **Cobertura mínima obrigatória**: Fixada pela ANS, mas não exemplificativa
- **Reembolso de despesas médico-hospitalares**: Admitido em hipóteses excepcionais
- **Cláusulas penais**: Estabelecem cláusulas apenas em favor do fornecedor, admitindo inversão no caso de mora

### Referências legais
- Art. 39 da Lei nº 9.279/96
- Súmula 394 do STJ

### Jurisprudência
- REsp 1.561.445-SP
- REsp 1.733.013/PR
- EAREsp 1.459.849-ES

### Dicas de prova
- Entenda a diferença entre cobertura mínima obrigatória e exemplificativa
- Conheça as hipóteses excepcionais para o reembolso de despesas médico-hospitalares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.123 (2)", "page_number": 123, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 39 da Lei nº 9.279/96", "Súmula 394 do STJ"], "jurisprudence": ["REsp 1.561.445-SP", "REsp 1.733.013/PR", "EAREsp 1.459.849-ES"], "confidence": 0.8, "extracted_at": "2026-05-30T04:03:58.574769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=123", "doc_key": "981454935d15921da965d6ae613e1df8"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd5c7d29a1986ac3cd475976e22c3a3c1e78bbabc1dc8ce0a68e4cff0901f606e'),
  ('cpiuris2025::d8e6847d8712eff8fff83792fe4f00d6', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas abusivas e contratos com consumidores', '## Cláusulas abusivas e contratos com consumidores

Resumo objetivo em 2-5 frases: Este trecho destaca a validade de cláusulas abusivas em contratos com consumidores, como a cobertura adicional de invalidez funcional permanente total por doença em contrato de seguro de vida em grupo e a autorização para operadoras/financeiras debitar o pagamento do valor mínimo da fatura no titular do cartão de crédito. Além disso, é discutida a validade da contratação de empréstimo consignado por analfabeto mediante assinatura a rogo.

### Conceitos
- **Cláusula abusiva**: cláusula que viole direitos do consumidor
- **Contrato de seguro de vida em grupo**: contrato que oferece segurança financeira a grupos de pessoas
- **Lucros cessantes**: direito ao pagamento dos lucros que o consumidor poderia ter obtido se não tivesse sido prejudicado
- **IFPD (Invalidez Funcional Permanente Total por Doença)**: condição médica que afeta a capacidade de trabalho
- **Contrato consignado**: contrato em que o consumidor cede direito à recebibilidade do crédito ao terceiro

### Referências legais
- Art. 49 da Lei nº 8.078/1990
- ...

### Jurisprudência
- REsp 1.750.585/RJ
- REsp 1.807.48/DF
- REsp 1.867.199/SP - Tema 1068
- REsp 1.626.997/RJ
- REsp 1.868.099/CE

### Dicas de prova
- Entenda a noção de cláusula abusiva e como ela é aplicada em contratos com consumidores
- Conheça as regras para a validade de contratos de seguro de vida em grupo e de empréstimo consignado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.124 (2)", "page_number": 124, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990", "..."], "jurisprudence": ["REsp 1.750.585/RJ", "REsp 1.807.48/DF", "REsp 1.867.199/SP - Tema 1068", "REsp 1.626.997/RJ", "REsp 1.868.099/CE"], "confidence": 0.8, "extracted_at": "2026-05-30T04:05:51.601238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=124", "doc_key": "d8e6847d8712eff8fff83792fe4f00d6"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '290369904d073de2f52221d43eb78a0f843fbaa14c1833e76c1a5125514a20be'),
  ('cpiuris2025::9261a4cacd84008a7a9f0dda569bb9de', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Cláusulas Abusivas', '## Proteção Contratual e Cláusulas Abusivas

Resumo de artigos relacionados a cláusulas limitativas do uso de cofres locados, continuidade de cuidados assistenciais, resgate de passagens aéreas, rescisão de contratos de plano de saúde e cobertura médica.

### Conceitos
- **Cláusula Limitativa**: Limitação do uso do cofre locado
- **Proteção Contratual**: Direito do consumidor à proteção das cláusulas abusivas
- **Rescisão de Contrato**: Fim do contrato de plano de saúde ou seguro médico
- **Cobertura Médica**: Obrigação da operadora de garantir a continuidade dos cuidados assistenciais

### Referências legais
- Art. 49, § 4º, da Lei nº 8.078/1990
- Súmula 398 do STF

### Jurisprudência
- REsp 1206017/SP
- REsp 1.846.123/SP
- REsp 2.001.686-MS

### Dicas de prova
- Distinção entre cláusulas limitativas e abusivas
- Importância da continuidade dos cuidados assistenciais
- Reembolso de passagens aéreas com pontos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49, § 4º, da Lei nº 8.078/1990", "Súmula 398 do STF"], "jurisprudence": ["REsp 1206017/SP", "REsp 1.846.123/SP", "REsp 2.001.686-MS"], "confidence": 0.8, "extracted_at": "2026-05-30T04:06:19.779796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=125", "doc_key": "9261a4cacd84008a7a9f0dda569bb9de"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '44468f5962b818fc6488cc4bc023dcb0b6d9873658977873f7b22de58acb02f7'),
  ('cpiuris2025::eca5d928e3500b2438a47ca83ef77c06', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção Contratual e Planos de Saúde', '## Proteção Contratual e Planos de Saúde

Discute-se a proteção contratual em planos de saúde, incluindo cláusulas penais, custeio de acompanhantes, tratamento médico de fertilização in vitro, reajustes de mensalidades e exclusão de dependentes do titular.

### Conceitos
- **Cláusula penal**: cláusula que estabelece a sanção para o inadimplemento de obrigações
- **Obrigação heterogênea**: obrigação de fazer ou de dar que não pode ser convertida em dinheiro
- **Arbitramento judicial**: processo em que um juiz decide a valorização de uma obrigação
- **Custeio das despesas de acompanhante**: obrigação da operadora de plano de saúde de custear as despesas de acompanhante do paciente idoso
- **Tratamento médico de fertilização in vitro**: tratamento médico que visa ajudar a fertilidade em casais inférteis
- **Reajustes de mensalidades**: reajustes anuais das mensalidades de planos de saúde individuais fixados pela ANS
- **Plano individual**: plano de saúde contratado por um indivíduo, em vez de um grupo
- **Cláusula abusiva**: cláusula que é injusta ou desleal para o consumidor

### Referências legais
- Art. 49 da Lei nº 8.078/1990
- Súmula 971 do STF

### Jurisprudência
- REsp 1.498.484/DF
- REsp 1.631.485/DF
- REsp 1.793.840/RJ
- REsp 1.851.062/SP
- REsp 1.850.781/SP
- REsp 1.924.526/PE
- REsp 1.846.502/DF
- REsp 1.899.674/SP
- REsp 1.692.938/SP
- REsp 1.815.796/RJ

### Dicas de prova
- Entenda a noção de cláusula penal e sua aplicação nas contratos de plano de saúde.
- Conheça as diferenças entre obrigação heterogênea e obrigação convergível.
- Avalie a importância do arbitramento judicial na resolução de disputas em planos de saúde.
- Identifique as cláusulas abusivas que podem ser consideradas injustas para o consumidor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.124 (1)", "page_number": 124, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990", "Súmula 971 do STF"], "jurisprudence": ["REsp 1.498.484/DF", "REsp 1.631.485/DF", "REsp 1.793.840/RJ", "REsp 1.851.062/SP", "REsp 1.850.781/SP", "REsp 1.924.526/PE", "REsp 1.846.502/DF", "REsp 1.899.674/SP", "REsp 1.692.938/SP", "REsp 1.815.796/RJ"], "confidence": 0.8, "extracted_at": "2026-05-30T04:06:46.030467+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=124", "doc_key": "eca5d928e3500b2438a47ca83ef77c06"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '3b02b8166417a0dd80d0006a6f392f93ac2ea49e90306f05b6b0774762b9ac72'),
  ('cpiuris2025::6e5619717ded5305ec1096cd7ad48aac', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Rol da ANS', '## Rol da ANS

O rol da ANS não é taxativo, mas sim exemplificativo, pois inclui medicamentos administráveis na forma oral em ambiente domiciliar.

### Conceitos
- **rol da ANS**: lista de medicamentos que podem ser administrados em forma oral em ambiente domiciliar
- **taxatividade**: característica que define um conjunto de itens como uma lista exaustiva e completa
- **exemplificatividade**: característica que define um conjunto de itens como uma lista parcial e não exaustiva

### Referências legais
- Art. 41 da Lei nº 9.472/97
- ...

### Jurisprudência
- STJ, REsp 2.061.135/SP
- ...

### Dicas de prova
- Entenda a diferença entre taxatividade e exemplificatividade no contexto do rol da ANS
- Leia atentamente as decisões do STJ relacionadas ao tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 41 da Lei nº 9.472/97", "..."], "jurisprudence": ["STJ, REsp 2.061.135/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:08:10.766046+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=126", "doc_key": "6e5619717ded5305ec1096cd7ad48aac"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'e5e92beacb36b99da883a853941c9b51b48efde679ed3a5f5ad95a052680d7aa'),
  ('cpiuris2025::320715a1a23c5b1f940c88208e909a24', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Competência da ANS e rol de procedimentos em planos de saúde', '## Competência da ANS e rol de procedimentos em planos de saúde

A ANS tem competência para fiscalizar e controlar os serviços de planos de saúde, além de elaborar o rol de procedimentos e tratamentos obrigatórios. A lei não esclarece se o rol é taxativo ou exemplificativo, levando a interpretação da 3ª Turma do STJ, que considera exemplificativo.

### Conceitos
- **Competência**: A capacidade de uma autoridade pública exercer controle sobre uma atividade específica
- **Rol de procedimentos**: Lista de tratamentos e procedimentos obrigatórios para planos de saúde
- **Taxativo**: O que é necessário ou obrigatório, sem opções
- **Exemplificativo**: O que fornece exemplos, mas não é obrigatório

### Referências legais
- Art. 11 da Lei nº 9.656/98

### Jurisprudência
- {''term'': ''Súmula 102'', ''definition'': ''Havendo expressa indicação médica, é abusiva a negativa de cobertura de custeio de tratamento sob o argumento da sua natureza experimental ou por não estar previsto no rol de procedimentos da ANS''}

### Dicas de prova
- Entenda a competência da ANS e a interpretação do rol de procedimentos em planos de saúde
- Conheça as diferenças entre taxativo e exemplificativo
- Análise da Súmula 102 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 11 da Lei nº 9.656/98"], "jurisprudence": ["{''term'': ''Súmula 102'', ''definition'': ''Havendo expressa indicação médica, é abusiva a negativa de cobertura de custeio de tratamento sob o argumento da sua natureza experimental ou por não estar previsto no rol de procedimentos da ANS''}"], "confidence": 0.8, "extracted_at": "2026-05-30T04:08:55.378543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=126", "doc_key": "320715a1a23c5b1f940c88208e909a24"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'da5a7d0c63ed83a5699bc0bf919f81ee2556e2e651dee5c6fc999467557f65ef'),
  ('cpiuris2025::597e2dff881ec131bf614bb8f5b4554f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Recusa de cobertura de medicamentos e reajustes de planos de saúde', '## Recusa de cobertura de medicamentos e reajustes de planos de saúde

A recusa de operadora de plano de saúde em custear medicamento prescrito é abusiva, exceto quando o medicamento é imprescindível à conservação da vida e saúde do paciente. A cobrança de tarifa para medição individualizada não é abusiva se assegurada a livre escolha dos consumidores na contratação. O reajuste do valor do plano por conta do aumento de sinistralidade só é permitido se o plano demonstrar um incremento nos despesas assistenciais em relação às receitas diretas.

### Conceitos
- **Abuso de poder**: Acessório ao direito, que se configura quando a operadora de plano de saúde recusa-se a cumprir com o dever de atender ao consumidor
- **Cobrança de tarifa**: O pagamento pelo serviço prestado pela operadora de plano de saúde
- **Despesas assistenciais**: As despesas relacionadas ao tratamento do paciente, como medicamentos e consultas médicas
- **Equivalência material**: A igualdade das prestações entre a operadora de plano de saúde e o consumidor
- **Fármaco off-label**: Um medicamento utilizado para um uso diferente do que o indicado pela ANVISA
- **Medição individualizada**: A medição de consumo de energia ou água, feita diretamente no local de consumo
- **Prestação**: O direito do consumidor à atenção e ao cumprimento pelo fornecedor de serviços
- **Sinistralidade**: A frequência e gravidade dos acidentes ou danos causados por um plano de saúde

### Referências legais
- AgInt no AREsp 1.964.268-DF
- REsp 1.986.320-SP
- STJ. 3ª Turma. REsp 2.108.270/SP
- Art. X da Lei Y

### Jurisprudência
- REsp 1.964.268-DF
- REsp 1.986.320-SP
- STJ. 3ª Turma. REsp 2.108.270/SP

### Dicas de prova
- Distinção entre fármaco off-label e uso experimental
- Equivalência material das prestações
- Cobrança de tarifa para medição individualizada
- Reajuste do valor do plano por conta do aumento de sinistralidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito do Consumidor", "legal_refs": ["AgInt no AREsp 1.964.268-DF", "REsp 1.986.320-SP", "STJ. 3ª Turma. REsp 2.108.270/SP", "Art. X da Lei Y"], "jurisprudence": ["REsp 1.964.268-DF", "REsp 1.986.320-SP", "STJ. 3ª Turma. REsp 2.108.270/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:09:12.276518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=125", "doc_key": "597e2dff881ec131bf614bb8f5b4554f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'bf39b5997afeb8314d217f733f1e1e76c42506c4bd068ff0a0ea612dcaf45d5a'),
  ('cpiuris2025::89f47d69be6bd5e15835e43e0c9a2d1e', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Taxatividade do rol da ANS e aplicação imediata de lei', '## Taxatividade do rol da ANS e aplicação imediata de lei

A Lei n. 14.454/22 não pode retroagir, mas aplica-se imediatamente a partir de sua vigência para os tratamentos de caráter continuado.

### Conceitos
- **Taxatividade**: O rol da ANS é taxativo, mas há possibilidade de mitigação em casos concretos.
- **Irretroatividade**: A lei não pode retroagir, mas aplica-se imediatamente a partir de sua vigência.
- **Lei n. 14.454/22**: Lei que estabelece regras para os tratamentos de caráter continuado.
- **ANS**: Agência Nacional de Vigilância Sanitária
- **Cobertura médica**: Dever de fornecer cobertura médica para o tratamento de câncer

### Referências legais
- Art. 14 da Lei n. 14.454/22
- Súmula 432 do STJ

### Jurisprudência
- REsp 2.037.616/SP
- REsp 2.038.333/AM
- REsp 2.057.897/SP

### Dicas de prova
- Entenda a distinção entre taxatividade e exemplificativa do rol da ANS.
- Conheça a irretroatividade das leis brasileiras.
- Aplique-se a Lei n. 14.454/22 para os tratamentos de caráter continuado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 14 da Lei n. 14.454/22", "Súmula 432 do STJ"], "jurisprudence": ["REsp 2.037.616/SP", "REsp 2.038.333/AM", "REsp 2.057.897/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:11:59.055302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=127", "doc_key": "89f47d69be6bd5e15835e43e0c9a2d1e"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '7163abab7065874470fe3fc3506d15ad47fcd5f4add6157414e162bb3d7c79ed'),
  ('cpiuris2025::125a6daebacbc675147b963e60912136', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas abusivas contratuais', '## Cláusulas abusivas contratuais

As cláusulas contratuais que estabeleçam inversão do ônus da prova em prejuízo do consumidor, determinem a utilização compulsória de arbitragem ou imponham representante para concluir ou realizar outro negócio jurídico pelo consumidor são consideradas abusivas e proibidas.

### Conceitos
- **Inversão do ônus da prova**: O direito de inversão do ônus da prova em favor do consumidor
- **Arbitragem compulsória**: A utilização compulsória de arbitragem nas relações de consumo
- **Representante para concluir ou realizar outro negócio jurídico**: O direito do consumidor de não ter um representante para concluir ou realizar outro negócio jurídico

### Referências legais
- Art. 6º, VIII do CDC
- Art. 12, § 3º do CDC
- Art. 14, § 3º do CDC
- Art. 39 do CDC
- Súmula 808/STJ

### Jurisprudência
- REsp 2.057.814/SP
- REsp 2.017.851/SP

### Dicas de prova
- Entenda a inversão do ônus da prova em favor do consumidor e suas implicações.
- Conheça as regras de arbitragem compulsória e seus limites.
- Aprenda a distinguir entre representante para concluir ou realizar outro negócio jurídico e cláusulas mandatórias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 6º, VIII do CDC", "Art. 12, § 3º do CDC", "Art. 14, § 3º do CDC", "Art. 39 do CDC", "Súmula 808/STJ"], "jurisprudence": ["REsp 2.057.814/SP", "REsp 2.017.851/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:12:12.053423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=128", "doc_key": "125a6daebacbc675147b963e60912136"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '4325c6592a1e576d36f7a74707aeea26cd084bdb64f8f9d3840407b8d8abaec1'),
  ('cpiuris2025::83b73d772fd15ac3cca4121ee143a30f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Taxatividade do rol da ANS e autorização de tratamentos não previstos', '## Taxatividade do rol da ANS e autorização de tratamentos não previstos

A 2ª Seção do STJ entendeu pela interpretação taxativa do rol de procedimentos e tratamentos da ANS, mas a Lei n. 14.454/2022 incluiu os parágrafos 12 e 13 ao art. 10 da Lei n. 9.656/98, autorizando a cobertura de tratamentos não previstos desde que comprovada a eficácia ou existam recomendações da CONITEC.

### Conceitos
- **Taxatividade**: O rol do ANS é considerado taxativo, o que significa que deve ser respeitado integralmente.
- **Autorização de tratamentos não previstos**: A cobertura de tratamentos ou procedimentos prescritos por médico ou odontólogo que não estejam no rol da ANS é autorizada desde que comprovada a eficácia ou existam recomendações da CONITEC.
- **Eficácia**: A comprovação de que um tratamento ou procedimento é eficaz, baseado em evidências científicas e plano terapêutico.
- **Recomendações da CONITEC**: As recomendações da Comissão Nacional de Incorporação de Tecnologias no Sistema Único de Saúde (CONITEC) são consideradas para autorizar a cobertura de tratamentos não previstos.

### Referências legais
- Art. 10, § 12 e § 13 da Lei n. 9.656/98
- Súmula N da STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Taxatividade do rol ANS

### Dicas de prova
- Entenda a taxatividade do rol da ANS e as novas regras de autorização de tratamentos não previstos
- Conheça os requisitos para comprovar a eficácia de um tratamento ou procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 10, § 12 e § 13 da Lei n. 9.656/98", "Súmula N da STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Taxatividade do rol ANS"], "confidence": 0.8, "extracted_at": "2026-05-30T04:12:52.572955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=127", "doc_key": "83b73d772fd15ac3cca4121ee143a30f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '6f6f9c654a25c3fef2af3a1785691ff254b28efb7aa9f212431c669ccfb96d1a'),
  ('cpiuris2025::f44beca07028e8cae246a53f241b25f1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas contratuais que deixem ao fornecedor a opção de concluir ou não o contrato', '## Cláusulas contratuais que deixem ao fornecedor a opção de concluir ou não o contrato

Regra para cláusulas que obrigam o consumidor a aceitar condições estabelecidas pelo fornecedor, sem direito a negar ou alterar.

### Conceitos
- **Cláusula de mandato**: cláusula que permite ao fornecedor retirar valores da conta do consumidor para quitar contratos inadimplidos
- **Cláusula de desistência**: cláusula que permite ao consumidor rescindir o contrato, mas apenas se for mútua e beneficiar ambas as partes

### Referências legais
- Art. 49 da Lei nº 8.078/1990

### Dicas de prova
- Entenda que cláusulas que obrigam o consumidor a aceitar condições estabelecidas pelo fornecedor são consideradas abusivas e devem ser analisadas com cuidado.
- Lembre-se de que a cláusula de desistência só é válida se for mútua e beneficiar ambas as partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:13:58.531967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=128", "doc_key": "f44beca07028e8cae246a53f241b25f1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '60b6c5e8b3656c512fa9f13769f987b91228c170f4a8986e2acaedbd2e589958'),
  ('cpiuris2025::352560c8ca95f77f8e4f20ca2ca4e625', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas contratuais que autorizam o fornecedor a cancelar o contrato unilateralmente', '## Cláusulas contratuais que autorizam o fornecedor a cancelar o contrato unilateralmente

As cláusulas que permitem ao fornecedor cancelar o contrato sem direito igual ao consumidor são nulas, pois vão contra a boa-fé e a equidade.

### Conceitos
- **Cláusula de cancelamento unilateral**: Disposição do contrato que permite ao fornecedor cancelar o contrato sem direito igual ao consumidor
- **Boa-fé**: Condução ética e honesta nas relações contratuais
- **Equidade**: Princípio que busca justiça e razoabilidade em casos difíceis

### Referências legais
- Art. 51, Inciso IV do CDC
- Súmula 472 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre cláusulas de cancelamento unilateral

### Dicas de prova
- Pergunta sobre a validade das cláusulas de cancelamento unilateral
- Distinção entre cláusula de cancelamento unilateral e desistência arbitrária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, Inciso IV do CDC", "Súmula 472 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre cláusulas de cancelamento unilateral"], "confidence": 0.8, "extracted_at": "2026-05-30T04:14:24.717671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=129", "doc_key": "352560c8ca95f77f8e4f20ca2ca4e625"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '8665ab4cbb66215133bbed47540b6af196a39e4a6b8423f8dc832b2967fdffcc'),
  ('cpiuris2025::287a7996ebcad022f5bf3de5991b30e4', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas que obriguem o consumidor a ressarcir os custos de cobrança', '## Cláusulas que obriguem o consumidor a ressarcir os custos de cobrança

As cláusulas que obrigam o consumidor a ressarcir os custos de cobrança sem direito contraposto são consideradas abusivas e ilegais.

### Conceitos
- **Cláusula de ressarcimento**: obriga o consumidor a pagar os custos de cobrança
- **Direito de contrapartida**: direito do consumidor à igualdade em relação ao fornecedor
- **Reserva de mutualidade**: exigência de que as cláusulas abusivas sejam apuradas no caso concreto
- **Boa-fé**: princípio do direito que exige a honestidade e sinceridade nas negociações
- **Equidade**: princípio do direito que exige a justiça e proporcionalidade nas decisões

### Referências legais
- Art. 51, inciso IV, Código de Defesa do Consumidor

### Jurisprudência
- AgInt no AREsp 1.406.027/SP

### Dicas de prova
- Entenda a reserva de mutualidade e sua importância nas cláusulas abusivas
- Aproveite o princípio da boa-fé para identificar cláusulas abusivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, inciso IV, Código de Defesa do Consumidor"], "jurisprudence": ["AgInt no AREsp 1.406.027/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:15:18.400439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=129", "doc_key": "287a7996ebcad022f5bf3de5991b30e4"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '25d1581d619b00c5214bdb144d590eed7c070eab9ae16a41898e0c7db8df3b43'),
  ('cpiuris2025::d09ac71c48ae3ae55bf569b133bce73b', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas contratuais que autorizam o fornecedor a modificar unilateralmente o conteúdo ou a qualidade do contrato, após sua celebração', '## Cláusulas contratuais que autorizam o fornecedor a modificar unilateralmente o conteúdo ou a qualidade do contrato, após sua celebração

A cláusula de modificação contratual deve ser válida se contiver ambas as partes e não seja apenas uma questão de observância do inciso XIII do art. 51. A situação deve ser analisada com atenção à vulnerabilidade do consumidor.

### Conceitos
- **Princípio restitutio in integrum**: Princípio que imputa ao devedor a responsabilidade por todas as despesas causadas pela sua mora ou inadimplemento
- **Vulnerabilidade do consumidor**: A situação em que o consumidor é mais suscetível a abusos e não tem igual poder de negociação

### Referências legais
- Art. 51, Inciso XIII do CDC
- Súmula 342 do STJ

### Jurisprudência
- REsp 1.361.699/MG

### Dicas de prova
- Pergunte se a cláusula de modificação contratual é válida ou não
- Verifique se a cláusula contém ambas as partes e se é uma questão de observância do inciso XIII do art. 51', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, Inciso XIII do CDC", "Súmula 342 do STJ"], "jurisprudence": ["REsp 1.361.699/MG"], "confidence": 0.8, "extracted_at": "2026-05-30T04:16:20.225857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=130", "doc_key": "d09ac71c48ae3ae55bf569b133bce73b"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '075453dc916dbe3fb3ad2d69ef543541d075dc41697abdf6430f425710ce9c66'),
  ('cpiuris2025::37df49f6f4c0e4e453bba3d824b4ebc5', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Proteção ao consumidor e cláusulas abusivas', '## Proteção ao consumidor e cláusulas abusivas

A proteção ao consumidor é garantida por normas constitucionais difusas e individuais, com a interveniência do estado para consecução das políticas públicas e direitos fundamentais. As cláusulas contratuais que estejam em desacordo com o sistema de proteção ao consumidor são consideradas abusivas.

### Conceitos
- **Direito Constitucional Difuso**: Normas constitucionais que não têm uma definição clara ou específica
- **Direito Constitucional Individual**: Normas constitucionais que têm uma definição clara e específica
- **Sistema de Proteção ao Consumidor**: Normas que garantem a proteção dos direitos do consumidor
- **Cláusulas Abusivas**: Cláusulas contratuais que não estão em conformidade com o sistema de proteção ao consumidor

### Referências legais
- Art. 4º, II, do CDC

### Dicas de prova
- Análise do dispositivo para identificar cláusulas abusivas
- Entendimento do princípio da proteção ao consumidor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 4º, II, do CDC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:16:35.725854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=130", "doc_key": "37df49f6f4c0e4e453bba3d824b4ebc5"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '39e0c4c9bd4810b6679a8b47a1a284c9a62e75bf9915b85282e31f1808d083f8'),
  ('cpiuris2025::d4c5ae2e6496788a25335a23d8c38782', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Compatibilidade das cláusulas com o ordenamento constitucional', '## Compatibilidade das cláusulas com o ordenamento constitucional

Resumo objetivo: Cláusulas compatíveis com a Constituição só podem restringir o acesso à justiça ou ter fundamento direto na Carta Magna.

### Conceitos
- **Compatibilidade**: Adequação das cláusulas às normas constitucionais
- **Restrição do acesso à justiça**: Limitação da ação judicial para casos específicos
- **Fundamento direto na Carta Magna**: Base legal derivada diretamente da Constituição

### Referências legais
- Art. 217, § 1º da CRFB/88

### Dicas de prova
- Distinção entre cláusulas compatíveis e incompatíveis com a Constituição
- Importância do fundamento direto na Carta Magna para a validade das cláusulas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 217, § 1º da CRFB/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T04:18:01.161246+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=131", "doc_key": "d4c5ae2e6496788a25335a23d8c38782"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'fc29783bfae4a62882e8a05ae3a29f970275783a9d976bdba986c5678f9dfd34'),
  ('cpiuris2025::ef98124f4924dbf424419c84804b2de1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas abusivas e proteção ao consumidor', '## Cláusulas abusivas e proteção ao consumidor

Discute-se a validade de cláusulas que limitam o acesso ao Poder Judiciário ou condicionam a indenização por benfeitorias necessárias, com base na Lei n.º 14.181/2021 e no artigo 5º da CRFB/88.

### Conceitos
- **Cláusulas abusivas**: Disposições contratuais que vão além do que é permitido pela lei
- **Proteção ao consumidor**: Direito que visa proteger os consumidores de práticas comerciais desleal ou abusivas
- **Benfeitorias necessárias**: Serviços ou bens fornecidos por um terceiro sem remuneração, cuja ocorrência é obrigatória para a realização de uma obrigação principal
- **Acesso ao Poder Judiciário**: Direito fundamental que permite ao consumidor buscar justiça em tribunal

### Referências legais
- Art. 96, § 3º, do CC/02
- Lei n.º 14.181 de 2021
- Art. 5º, XXXV da CRFB/88

### Jurisprudência
- REsp 575.020/RS
- ADI 2.139 e ADI 2.160
- REsp 1.520.500/SP

### Dicas de prova
- Entenda a noção de cláusulas abusivas e sua relação com a proteção ao consumidor
- Conheça o conceito de benfeitorias necessárias e como elas se relacionam com as cláusulas contratuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 96, § 3º, do CC/02", "Lei n.º 14.181 de 2021", "Art. 5º, XXXV da CRFB/88"], "jurisprudence": ["REsp 575.020/RS", "ADI 2.139 e ADI 2.160", "REsp 1.520.500/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:18:24.341504+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=131", "doc_key": "ef98124f4924dbf424419c84804b2de1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'd23c6e3b02e337f1a7d894f0c70fbc5a4a72187067a97f6fe36d277bda61d097'),
  ('cpiuris2025::db549a9fad4315d39526332692a4a2e7', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Controle das cláusulas abusivas', '## Controle das cláusulas abusivas

O artigo 51, § 4º, do CDC estabelece o direito dos consumidores de requerer ao Ministério Público a declaração da nulidade de cláusula contratual que contrarie o disposto no CDC ou não assegure o justo equilíbrio entre direitos e obrigações das partes.

### Conceitos
- **Cláusulas abusivas**: cláusulas de contrato que contrariam os preceitos do CDC ou não asseguram o justo equilíbrio entre direitos e obrigações
- **Controle administrativo**: exercício do controle pelo Ministério Público sobre cláusulas abusivas
- **Denúncia realizada por consumidor**: ação do consumidor que denuncia a existência de cláusula abusiva em um contrato
- **Controle concreto**: exercício do controle pelo Ministério Público sobre cláusulas abusivas, após o consumidor já ter aderido ao contrato
- **Disposição legal**: artigo 51, § 4º, do CDC
- **Justo equilíbrio**: equilíbrio entre direitos e obrigações das partes em um contrato
- **Ministério Público**: instituição responsável por declarar a nulidade de cláusula contratual que contraria o disposto no CDC

### Referências legais
- Art. 51, § 4º do CDC

### Jurisprudência
- RE 500.879 - AgR
- ...

### Dicas de prova
- Entenda a diferença entre controle administrativo e concreto
- Conheça o artigo 51, § 4º, do CDC e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 51, § 4º do CDC"], "jurisprudence": ["RE 500.879 - AgR", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T04:19:46.185831+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=132", "doc_key": "db549a9fad4315d39526332692a4a2e7"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '20797c8b3284c0c7bbfe68ca9fe10c8e3b555767467dbf6f50bd25250d3ce469'),
  ('cpiuris2025::ca982e946cfe260e58be1590723b12a1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Contratos que envolvem outorga de crédito ou financiamento', '## Contratos que envolvem outorga de crédito ou financiamento

O art. 52 do CDC estabelece padrão mínimo de transparência nos contratos que envolvam outorga de crédito, informando o consumidor sobre preço, juros, acréscimos e prestações.

### Conceitos
- **Outorga de crédito**: Concessão de financiamento ao consumidor
- **Transparência**: Informação clara e adequada
- **Contrato**: Acordo entre o fornecedor e o consumidor
- **Prestações**: Pagamentos obrigatórios
- **Juros**: Taxa sobre o valor do crédito
- **Acréscimos**: Adicionais legais previstos no contrato

### Referências legais
- Art. 52 da Lei nº 8.078/1990

### Jurisprudência
- RE 472.489-AgR
- Súmula 342 do STF

### Dicas de prova
- Entenda a importância da transparência nos contratos de crédito.
- Identifique os elementos obrigatórios do art. 52 do CDC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 52 da Lei nº 8.078/1990"], "jurisprudence": ["RE 472.489-AgR", "Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T04:20:12.298620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=132", "doc_key": "ca982e946cfe260e58be1590723b12a1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '91d98f52cb27d0b210997e49f9553ac510b8601aa9148353e883fe9963e3a07b'),
  ('cpiuris2025::8f1518f571f28feafaf7fa83d1d95b5f', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Cláusulas Penais Moratórias e Contratos Consumeristas', '## Cláusulas Penais Moratórias e Contratos Consumeristas

A lei estabelece limites para as multas de mora em contratos financeiros, proibindo que elas sejam superiores a dois por cento do valor da prestação. O valor da prestação é o único que deve ser considerado para calcular a multa de mora.

### Conceitos
- **Cláusulas Penais Moratórias**: Sanções aplicadas em contratos financeiros por inadimplemento de obrigações
- **Valor da Prestação**: O valor do débito que deve ser considerado para calcular a multa de mora
- **Multas de Mora**: Sanções aplicadas por inadimplemento de obrigações em contratos financeiros
- **Pactuação de Desconto de Pontualidade**: Acordo entre o consumidor e a instituição financeira para reduzir a multa de mora em percentual maior do que o estabelecido pela lei

### Referências legais
- Art. 52, § 1º, CC/02
- Súmula 297, STJ
- Súmula 539, STJ

### Jurisprudência
- REsp 436.224/DF
- REsp 1.424.814/SP

### Dicas de prova
- Entenda a diferença entre multa de mora e desconto de pontualidade
- Conheça o valor da prestação como único considerado para calcular a multa de mora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 52, § 1º, CC/02", "Súmula 297, STJ", "Súmula 539, STJ"], "jurisprudence": ["REsp 436.224/DF", "REsp 1.424.814/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T04:21:12.214005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=133", "doc_key": "8f1518f571f28feafaf7fa83d1d95b5f"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', 'cf35e775e5c1e677f7a37985328df7a654f255023cb4dc088d9ceab94e3b431f'),
  ('cpiuris2025::b8e6aa1f2ddd0daa46acc969068f2ff1', 'doutrina', 'cp_iuris', 'Direito do Consumidor — Taxas e Comissões', '## Taxas e Comissões

Resumo sobre taxas de juros e comissões cobradas pelas instituições financeiras.

### Conceitos
- **Capitalização diária**: Prática em que os juros são capitalizados diariamente, resultando em uma taxa diária
- **Taxa efetiva anual contratada**: Taxa de juros anual pactuada no contrato
- **Taxa diária aplicada**: Taxa de juros aplicada diariamente, em casos de capitalização diária

### Referências legais
- Art. 49 da Lei nº 8.078/1990
- Súmula 541 do STJ

### Jurisprudência
- REsp 1.826.463/SC

### Dicas de prova
- Entenda a diferença entre taxa efetiva mensal e taxa diária aplicada em casos de capitalização diária.
- Conheça as regras sobre comissões de permanência cobradas pelas instituições financeiras.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf", "source_ref": "IURIS - Direito do Consumidor - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito do Consumidor", "legal_refs": ["Art. 49 da Lei nº 8.078/1990", "Súmula 541 do STJ"], "jurisprudence": ["REsp 1.826.463/SC"], "confidence": 0.8, "extracted_at": "2026-05-30T04:21:41.876514+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito do Consumidor - 2025.pdf#page=133", "doc_key": "b8e6aa1f2ddd0daa46acc969068f2ff1"}'::jsonb, '{"materia": "Direito do Consumidor"}'::jsonb, 'cp_iuris_2025', '26c04ac07042c7d64c550e6d2ac2c1bc074876a2a37d86932df7c4f862e127ec')
